// تحويل Timestamp/Date/primitive إلى Date (مع الحفاظ على القيمة الأصلية)
const convertTimestamp = (timestamp: any): Date => {
  // Firestore Timestamp
  if (timestamp && typeof timestamp === 'object' && typeof timestamp.toDate === 'function') {
    return timestamp.toDate();
  }
  // JavaScript Date
  if (timestamp instanceof Date) {
    return timestamp;
  }
  // رقم (millis) أو نص يمكن تحويله
  if (typeof timestamp === 'number') {
    return new Date(timestamp);
  }
  if (typeof timestamp === 'string') {
    const d = new Date(timestamp);
    return isNaN(d.getTime()) ? new Date() : d;
  }
  // قيمة غير معروفة: fallback إلى الآن
  return new Date();
};

// تحويل Date إلى Timestamp
const toTimestamp = (date: Date) => serverTimestamp();

// تنظيف عميق لإزالة القيم undefined من الكائنات والمصفوفات قبل الحفظ في Firestore
const isPlainObject = (obj: any) => {
  if (obj === null) return false;
  const proto = Object.getPrototypeOf(obj);
  return proto === Object.prototype || proto === null;
};

export const sanitizeFirestoreData = (value: any): any => {
  if (value === undefined) return undefined;
  if (value === null) return null;
  if (Array.isArray(value)) {
    return value
      .map((v) => sanitizeFirestoreData(v))
      .filter((v) => v !== undefined);
  }
  if (value instanceof Date) return value;
  // احتفظ بكائنات Firebase الخاصة مثل Timestamp و FieldValue كما هي
  if (!isPlainObject(value)) return value;
  const result: Record<string, any> = {};
  for (const [key, val] of Object.entries(value)) {
    const sanitizedVal = sanitizeFirestoreData(val);
    if (sanitizedVal !== undefined) {
      result[key] = sanitizedVal;
    }
  }
  return result;
};

// خدمة الملفات الشخصية
export const profileService = {
  // إنشاء ملف شخصي جديد
  async create(profileData: { userId: string; shopId: string; role: string; fullName: string | null; phone: string | null }): Promise<void> {
    await setDoc(doc(db, 'profiles', profileData.userId), {
      userId: profileData.userId,
      shopId: profileData.shopId,
      role: profileData.role,
      fullName: profileData.fullName,
      phone: profileData.phone,
      createdAt: serverTimestamp()
    });
  },

  // الحصول على ملف شخصي بواسطة معرف المستخدم
  async getById(userId: string): Promise<Profile | null> {
    const docRef = doc(db, 'profiles', userId);
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      const data = docSnap.data();
      return {
        userId: docSnap.id,
        ...data,
        createdAt: convertTimestamp(data.createdAt)
      } as Profile;
    }
    return null;
  },

  // تحديث ملف شخصي
  async update(userId: string, data: Partial<Omit<Profile, 'userId' | 'createdAt'>>): Promise<void> {
    const docRef = doc(db, 'profiles', userId);
    await updateDoc(docRef, {
      ...data,
      updatedAt: serverTimestamp()
    });
  },

  // الحصول على جميع الملفات الشخصية لمحل معين
  async getByShopId(shopId: string): Promise<Profile[]> {
    const q = query(collection(db, 'profiles'), where('shopId', '==', shopId));
    const snapshot = await getDocs(q);

    return snapshot.docs.map(doc => {
      const data = doc.data();
      return {
        userId: doc.id,
        ...data,
        createdAt: convertTimestamp(data.createdAt)
      } as Profile;
    });
  }
};

// خدمة الإحالات
export const referralService = {
  // إنشاء إحالة جديدة
  async create(referralData: Omit<Referral, 'id' | 'createdAt' | 'updatedAt'>): Promise<string> {
    const docRef = await addDoc(collection(db, 'referrals'), {
      ...referralData,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp()
    });
    return docRef.id;
  },

  // الحصول على الإحالات بواسطة معرف المحيل
  async getByReferrerId(referrerId: string): Promise<Referral[]> {
    try {
      const q = query(
        collection(db, 'referrals'),
        where('referrerId', '==', referrerId),
        orderBy('createdAt', 'desc')
      );
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
        createdAt: convertTimestamp(doc.data().createdAt),
        updatedAt: convertTimestamp(doc.data().updatedAt)
      } as Referral));
    } catch (err: any) {
      const msg = String(err?.message || '');
      // في حال عدم توفر الفهرس المركب، استخدم استعلامًا بديلًا بدون ترتيب ثم رتب محليًا
      if (msg.includes('requires an index')) {
        const fallbackQ = query(
          collection(db, 'referrals'),
          where('referrerId', '==', referrerId)
        );
        const snapshot = await getDocs(fallbackQ);
        return snapshot.docs
          .map(doc => ({
            id: doc.id,
            ...doc.data(),
            createdAt: convertTimestamp(doc.data().createdAt),
            updatedAt: convertTimestamp(doc.data().updatedAt)
          } as Referral))
          .sort((a, b) => (b.createdAt?.getTime?.() || 0) - (a.createdAt?.getTime?.() || 0));
      }
      throw err;
    }
  },

  // الحصول على إحالة بواسطة رمز الإحالة
  async getByReferralCode(referralCode: string): Promise<Referral | null> {
    const q = query(
      collection(db, 'referrals'),
      where('referralCode', '==', referralCode),
      limit(1)
    );
    const querySnapshot = await getDocs(q);
    if (querySnapshot.empty) {
      return null;
    }
    const doc = querySnapshot.docs[0];
    return {
      id: doc.id,
      ...doc.data(),
      createdAt: convertTimestamp(doc.data().createdAt),
      updatedAt: convertTimestamp(doc.data().updatedAt)
    } as Referral;
  },

  // تحديث حالة الإحالة
  async updateStatus(id: string, status: Referral['status']): Promise<void> {
    await updateDoc(doc(db, 'referrals', id), {
      status,
      updatedAt: serverTimestamp()
    });
  },

  // إنشاء رمز إحالة فريد
  generateReferralCode(userId: string): string {
    const timestamp = Date.now().toString(36);
    const userHash = userId.slice(-6);
    return `REF_${userHash}_${timestamp}`.toUpperCase();
  }
};

// خدمة المعاملات - وظائف إضافية
export const transactionServiceExtra = {
  // الحصول على آخر المعاملات لمحل معين
  async getLastTransactions(shopId: string, limit: number = 30): Promise<Transaction[]> {
    try {
      // استخدام Cloud Function للحصول على آخر المعاملات
      const { getLastTransactions } = await import('./functions');
      const result = await getLastTransactions({ walletId: shopId, limit });
      return result.transactions;
    } catch (error) {
      console.error('Error in getLastTransactions:', error);
      // في حالة فشل Cloud Function، نستخدم الطريقة المباشرة كاحتياط
      const q = query(
        collection(db, 'transactions'),
        where('shopId', '==', shopId)
      );

      const snapshot = await getDocs(q);

      // فرز محلياً حسب createdAt تنازلياً وتحديد العدد المطلوب
      const items = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          ...data,
          createdAt: convertTimestamp(data.createdAt)
        } as Transaction;
      });

      return items
        .sort((a, b) => {
          const ta = a.createdAt ? new Date(a.createdAt).getTime() : 0;
          const tb = b.createdAt ? new Date(b.createdAt).getTime() : 0;
          return tb - ta;
        })
        .slice(0, limit);
    }
  },

  // الحصول على معاملات المستخدم التاجر
  async getMerchantTransactions(merchantUserId: string, limit: number = 30): Promise<Transaction[]> {
    try {
      // استخدام Cloud Function للحصول على معاملات التاجر
      const { getLastTransactions } = await import('./functions');
      const result = await getLastTransactions({ merchantUserId, limit });
      return result.transactions;
    } catch (error) {
      console.error('Error in getMerchantTransactions:', error);
      // في حالة فشل Cloud Function، نستخدم الطريقة المباشرة كاحتياط
      const q = query(
        collection(db, 'transactions'),
        where('merchantUserId', '==', merchantUserId)
      );

      const snapshot = await getDocs(q);

      const items = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          ...data,
          createdAt: convertTimestamp(data.createdAt)
        } as Transaction;
      });

      return items
        .sort((a, b) => {
          const ta = a.createdAt ? new Date(a.createdAt).getTime() : 0;
          const tb = b.createdAt ? new Date(b.createdAt).getTime() : 0;
          return tb - ta;
        })
        .slice(0, limit);
    }
  }
};

