export const telegramNotifier = {
  async send(userId: string, message: string): Promise<void> {
    try {
      const data = await userDataService.getUserData(userId);
      const chatId = String((data as any)?.telegramChatId || (data as any)?.chat_id || '').trim();
      if (!chatId) {
        throw new Error('Telegram Chat ID غير مضبوط للمستخدم');
      }
      const workerUrl = (await systemSettingsService.getTelegramWorkerUrl()) || DEFAULT_WORKER_URL;
      const url = workerUrl.replace(/\/$/, '');
      const resp = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chat_id: chatId, text: message })
      });
      if (!resp.ok) {
        const text = await resp.text().catch(() => '');
        throw new Error(text || 'فشل إرسال إشعار تليجرام عبر العامل');
      }
    } catch { }
  }
};

