// خدمة إدارة التقارير والإحصائيات منفصلة عن حدود المحافظ
import { userDataService } from '../integrations/firebase/services';
import { isManualFirestoreHoldEffective } from './manualFirestoreSyncHold';

export interface ReportsData {
  lastDailyResetDate: Date | null;
  lastMonthlyResetDate: Date | null;
  hiddenDailyTransactionIds: string[];
  hiddenMonthlyTransactionIds: string[];
  // بيانات الأرباح
  dailyProfit: number;
  monthlyProfit: number;
  lastDailyProfitResetDate: Date | null;
  lastMonthlyProfitResetDate: Date | null;
}

let _reportsCache: { [key: string]: ReportsData } = {};

export const reportsService = {
  // تصفية الذاكرة المؤقتة (يستخدم عند تحديث البيانات من مصادر خارجية)
  invalidateCache: (userId?: string) => {
    const key = userId || 'default';
    delete _reportsCache[key];
  },

  // مزامنة بيانات التقارير من Firebase إلى التخزين المحلي
  async syncReportsDataFromFirebase(userId?: string): Promise<ReportsData | null> {
    try {
      if (!userId) return null;
      const userData = await userDataService.getUserData(userId);
      const remote = (userData as any)?.reportsData;
      if (!remote) return null;

      const reportsKey = `reportsData_${userId}`;
      const normalizeDate = (d: any): Date | null => {
        if (!d) return null;
        try {
          return (d?.toDate ? d.toDate() : new Date(d));
        } catch {
          return null;
        }
      };

      const normalized: ReportsData = {
        lastDailyResetDate: normalizeDate(remote.lastDailyResetDate),
        lastMonthlyResetDate: normalizeDate(remote.lastMonthlyResetDate),
        hiddenDailyTransactionIds: Array.isArray(remote.hiddenDailyTransactionIds) ? remote.hiddenDailyTransactionIds : [],
        hiddenMonthlyTransactionIds: Array.isArray(remote.hiddenMonthlyTransactionIds) ? remote.hiddenMonthlyTransactionIds : [],
        dailyProfit: Number(remote.dailyProfit ?? 0),
        monthlyProfit: Number(remote.monthlyProfit ?? 0),
        lastDailyProfitResetDate: normalizeDate(remote.lastDailyProfitResetDate),
        lastMonthlyProfitResetDate: normalizeDate(remote.lastMonthlyProfitResetDate)
      };

      // حماية البيانات المحلية من التجاوز ببيانات قديمة من الخادم
      // إذا كان لدينا تصفير محلي أحدث، نحتفظ به
      const local = reportsService.getReportsData(userId);

      // حماية التصفير اليومي
      if (local.lastDailyResetDate) {
        if (!normalized.lastDailyResetDate || local.lastDailyResetDate.getTime() > normalized.lastDailyResetDate.getTime()) {
          normalized.lastDailyResetDate = local.lastDailyResetDate;
          normalized.dailyProfit = local.dailyProfit;
          normalized.lastDailyProfitResetDate = local.lastDailyProfitResetDate;
        }
      }
      if (Array.isArray(local.hiddenDailyTransactionIds) && local.hiddenDailyTransactionIds.length) {
        const set = new Set<string>([
          ...normalized.hiddenDailyTransactionIds,
          ...local.hiddenDailyTransactionIds
        ]);
        normalized.hiddenDailyTransactionIds = Array.from(set);
      }

      // حماية التصفير الشهري
      if (local.lastMonthlyResetDate) {
        if (!normalized.lastMonthlyResetDate || local.lastMonthlyResetDate.getTime() > normalized.lastMonthlyResetDate.getTime()) {
          normalized.lastMonthlyResetDate = local.lastMonthlyResetDate;
          normalized.monthlyProfit = local.monthlyProfit;
          normalized.lastMonthlyProfitResetDate = local.lastMonthlyProfitResetDate;
        }
      }
      if (Array.isArray(local.hiddenMonthlyTransactionIds) && local.hiddenMonthlyTransactionIds.length) {
        const set = new Set<string>([
          ...normalized.hiddenMonthlyTransactionIds,
          ...local.hiddenMonthlyTransactionIds
        ]);
        normalized.hiddenMonthlyTransactionIds = Array.from(set);
      }

      try { localStorage.setItem(reportsKey, JSON.stringify(normalized)); } catch {}
      return normalized;
    } catch (e) {
      console.warn('تعذر مزامنة بيانات التقارير من Firebase:', e);
      return null;
    }
  },
  // فحص ما إذا كان يجب تصفير التقارير اليومية
  shouldResetDailyReports: (lastResetDate: Date | null): boolean => {
    if (!lastResetDate) {
      return true; // أول مرة - يجب التصفير
    }

    const now = new Date();
    const lastReset = new Date(lastResetDate);
    
    // فحص إذا كان يوم جديد (بعد منتصف الليل)
    const isDifferentDay = now.toDateString() !== lastReset.toDateString();
    
    return isDifferentDay;
  },

  // فحص ما إذا كان يجب تصفير التقارير الشهرية
  shouldResetMonthlyReports: (lastResetDate: Date | null): boolean => {
    if (!lastResetDate) {
      return true; // أول مرة - يجب التصفير
    }

    const now = new Date();
    const lastReset = new Date(lastResetDate);
    
    // فحص إذا كان اليوم الحالي هو الأول من الشهر وآخر تصفير كان في شهر مختلف
    const isFirstDayOfMonth = now.getDate() === 1;
    const isDifferentMonth = now.getMonth() !== lastReset.getMonth() || 
                            now.getFullYear() !== lastReset.getFullYear();
    
    return isFirstDayOfMonth && isDifferentMonth;
  },

  // التحقق من الحاجة لتصفير التقارير (يومياً وشهرياً)
  autoResetReportsIfNeeded: (userId?: string): { dailyReset: boolean; monthlyReset: boolean } => {
    try {
      const reportsKey = userId ? `reportsData_${userId}` : 'reportsData';
      let reportsData = reportsService.getReportsData(userId);

      let dailyReset = false;
      const monthlyReset = false;

      // عند بدء يوم جديد (بعد 12 صباحاً) تحديث تواريخ وأرباح اليوم لتصفير أرباح المبيعات مع باقي أرباح اليوم
      if (reportsService.shouldResetDailyReports(reportsData.lastDailyProfitResetDate ?? reportsData.lastDailyResetDate)) {
        reportsService.applyDailyResetAtMidnight(userId);
        dailyReset = true;
        reportsData = reportsService.getReportsData(userId);
      }

      if (!reportsData.lastDailyResetDate) {
        reportsData.lastDailyResetDate = new Date();
      }

      if (!reportsData.lastDailyProfitResetDate) {
        reportsData.lastDailyProfitResetDate = new Date();
      }

      if (!reportsData.lastMonthlyResetDate) {
        reportsData.lastMonthlyResetDate = new Date();
      }

      if (!reportsData.lastMonthlyProfitResetDate) {
        reportsData.lastMonthlyProfitResetDate = new Date();
      }

      // حفظ البيانات المحدثة
      localStorage.setItem(reportsKey, JSON.stringify({
        ...reportsData,
        lastDailyResetDate: reportsData.lastDailyResetDate?.toISOString?.() ?? reportsData.lastDailyResetDate,
        lastDailyProfitResetDate: reportsData.lastDailyProfitResetDate?.toISOString?.() ?? reportsData.lastDailyProfitResetDate,
        lastMonthlyResetDate: reportsData.lastMonthlyResetDate?.toISOString?.() ?? reportsData.lastMonthlyResetDate,
        lastMonthlyProfitResetDate: reportsData.lastMonthlyProfitResetDate?.toISOString?.() ?? reportsData.lastMonthlyProfitResetDate
      }));
      _reportsCache[userId || 'default'] = reportsData;
      // حفظ إلى Firebase عند توفر userId (إن لم يكن قد تم التحديث عبر applyDailyResetAtMidnight)
      if (userId && !dailyReset) {
        try {
          userDataService.updateUserData(userId, { reportsData: { ...reportsData } });
        } catch (e) {
          console.warn('تعذر تحديث بيانات التقارير في Firebase بعد التصفير التلقائي:', e);
        }
      }
      
      return { dailyReset, monthlyReset };
    } catch (error) {
      console.error('خطأ في التصفير التلقائي للتقارير:', error);
      return { dailyReset: false, monthlyReset: false };
    }
  },

  // تصفير التقارير يدوياً
  resetReportsManually: (type: 'daily' | 'monthly', transactions: any[], userId?: string): string[] => {
    try {
      const reportsKey = userId ? `reportsData_${userId}` : 'reportsData';
      const savedReportsData = localStorage.getItem(reportsKey);
      let reportsData: ReportsData = {
        lastDailyResetDate: null,
        lastMonthlyResetDate: null,
        hiddenDailyTransactionIds: [],
        hiddenMonthlyTransactionIds: [],
        dailyProfit: 0,
        monthlyProfit: 0,
        lastDailyProfitResetDate: null,
        lastMonthlyProfitResetDate: null
      };

      if (savedReportsData) {
        const parsed = JSON.parse(savedReportsData);
        reportsData = {
          lastDailyResetDate: parsed.lastDailyResetDate ? new Date(parsed.lastDailyResetDate) : null,
          lastMonthlyResetDate: parsed.lastMonthlyResetDate ? new Date(parsed.lastMonthlyResetDate) : null,
          hiddenDailyTransactionIds: parsed.hiddenDailyTransactionIds || [],
          hiddenMonthlyTransactionIds: parsed.hiddenMonthlyTransactionIds || [],
          dailyProfit: parsed.dailyProfit || 0,
          monthlyProfit: parsed.monthlyProfit || 0,
          lastDailyProfitResetDate: parsed.lastDailyProfitResetDate ? new Date(parsed.lastDailyProfitResetDate) : null,
          lastMonthlyProfitResetDate: parsed.lastMonthlyProfitResetDate ? new Date(parsed.lastMonthlyProfitResetDate) : null
        };
      }

      let transactionIdsToHide: string[] = [];

      const toId = (tx: any) => String(tx?.id ?? tx?.transactionId ?? '').trim();
      if (type === 'daily') {
        // إخفاء كل معاملات اليوم الحالي لتصفير تقرير اليوم
        const today = new Date().toDateString();
        transactionIdsToHide = transactions
          .filter(tx => new Date(tx.createdAt).toDateString() === today)
          .map(tx => toId(tx))
          .filter(Boolean);
        
        reportsData.hiddenDailyTransactionIds = [...new Set([...reportsData.hiddenDailyTransactionIds, ...transactionIdsToHide])];
        reportsData.lastDailyResetDate = new Date();
        reportsData.dailyProfit = 0;
        reportsData.lastDailyProfitResetDate = new Date();
      } else {
        // إخفاء كل معاملات الشهر الحالي لتصفير تقرير الشهر
        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();
        const monthTransactions = transactions.filter(tx => {
          const txDate = new Date(tx.createdAt);
          return txDate.getMonth() === currentMonth && txDate.getFullYear() === currentYear;
        });
        transactionIdsToHide = monthTransactions.map(tx => toId(tx)).filter(Boolean);
        
        reportsData.hiddenMonthlyTransactionIds = [...new Set([...reportsData.hiddenMonthlyTransactionIds, ...transactionIdsToHide])];
        reportsData.hiddenDailyTransactionIds = [...new Set([...reportsData.hiddenDailyTransactionIds, ...transactionIdsToHide])];
        
        reportsData.lastMonthlyResetDate = now;
        reportsData.lastMonthlyProfitResetDate = now;
        reportsData.lastDailyResetDate = now;
        reportsData.lastDailyProfitResetDate = now;
        reportsData.monthlyProfit = 0;
        reportsData.dailyProfit = 0;
      }

      // حفظ البيانات المحدثة
      localStorage.setItem(reportsKey, JSON.stringify(reportsData));
      _reportsCache[userId || 'default'] = reportsData;
      // حفظ إلى Firebase عند توفر userId
      if (userId) {
        try {
          userDataService.updateUserData(userId, { reportsData: { ...reportsData } });
        } catch (e) {
          console.warn('تعذر تحديث بيانات التقارير في Firebase بعد التصفير اليدوي:', e);
        }
      }
      
      console.log(`تم تصفير التقارير ${type === 'daily' ? 'اليومية' : 'الشهرية'} يدوياً`);
      return transactionIdsToHide;
    } catch (error) {
      console.error('خطأ في التصفير اليدوي للتقارير:', error);
      return [];
    }
  },

  /**
   * تطبيق تصفير يومي عند منتصف الليل (بعد أرشفة اليوم السابق).
   * يحدّث lastDailyResetDate و lastDailyProfitResetDate و dailyProfit = 0 لضمان تصفير أرباح اليوم (بما فيها أرباح المبيعات) في الويب والأندرويد.
   */
  applyDailyResetAtMidnight: (userId?: string): void => {
    try {
      if (!userId) return;
      const reportsKey = `reportsData_${userId}`;
      const reportsData = reportsService.getReportsData(userId);
      const now = new Date();
      reportsData.lastDailyResetDate = now;
      reportsData.lastDailyProfitResetDate = now;
      reportsData.dailyProfit = 0;
      try {
        localStorage.setItem(reportsKey, JSON.stringify({
          ...reportsData,
          lastDailyResetDate: now.toISOString(),
          lastDailyProfitResetDate: now.toISOString()
        }));
      } catch {}
      _reportsCache[userId] = { ...reportsData };
      userDataService.updateUserData(userId, {
        reportsData: {
          lastDailyResetDate: now,
          lastDailyProfitResetDate: now,
          dailyProfit: 0,
          lastMonthlyResetDate: reportsData.lastMonthlyResetDate,
          lastMonthlyProfitResetDate: reportsData.lastMonthlyProfitResetDate,
          hiddenDailyTransactionIds: reportsData.hiddenDailyTransactionIds,
          hiddenMonthlyTransactionIds: reportsData.hiddenMonthlyTransactionIds,
          monthlyProfit: reportsData.monthlyProfit
        }
      }).catch((e) => console.warn('تعذر مزامنة تصفير الأرباح اليومية مع Firebase:', e));
    } catch (e) {
      console.warn('تعذر تطبيق تصفير الأرباح اليومية عند منتصف الليل:', e);
    }
  },

  // الحصول على بيانات التقارير
  getReportsData: (userId?: string): ReportsData => {
    try {
      const cacheKey = userId || 'default';
      if (_reportsCache[cacheKey]) {
        return { ..._reportsCache[cacheKey] };
      }

      const reportsKey = userId ? `reportsData_${userId}` : 'reportsData';
      const savedData = localStorage.getItem(reportsKey);
      
      let reportsData: ReportsData = {
          lastDailyResetDate: null,
          lastMonthlyResetDate: null,
          hiddenDailyTransactionIds: [],
          hiddenMonthlyTransactionIds: [],
          dailyProfit: 0,
          monthlyProfit: 0,
          lastDailyProfitResetDate: null,
          lastMonthlyProfitResetDate: null
      };

      if (savedData) {
        const parsed = JSON.parse(savedData);
        reportsData = {
          lastDailyResetDate: parsed.lastDailyResetDate ? new Date(parsed.lastDailyResetDate) : null,
          lastMonthlyResetDate: parsed.lastMonthlyResetDate ? new Date(parsed.lastMonthlyResetDate) : null,
          hiddenDailyTransactionIds: parsed.hiddenDailyTransactionIds || [],
          hiddenMonthlyTransactionIds: parsed.hiddenMonthlyTransactionIds || [],
          dailyProfit: parsed.dailyProfit || 0,
          monthlyProfit: parsed.monthlyProfit || 0,
          lastDailyProfitResetDate: parsed.lastDailyProfitResetDate ? new Date(parsed.lastDailyProfitResetDate) : null,
          lastMonthlyProfitResetDate: parsed.lastMonthlyProfitResetDate ? new Date(parsed.lastMonthlyProfitResetDate) : null
        };
      } else if (userId) {
        // Migration logic
        const legacyData = localStorage.getItem('reportsData');
        if (legacyData) {
           try {
             const parsed = JSON.parse(legacyData);
             reportsData = {
               lastDailyResetDate: parsed.lastDailyResetDate ? new Date(parsed.lastDailyResetDate) : null,
               lastMonthlyResetDate: parsed.lastMonthlyResetDate ? new Date(parsed.lastMonthlyResetDate) : null,
               hiddenDailyTransactionIds: parsed.hiddenDailyTransactionIds || [],
               hiddenMonthlyTransactionIds: parsed.hiddenMonthlyTransactionIds || [],
               dailyProfit: parsed.dailyProfit || 0,
               monthlyProfit: parsed.monthlyProfit || 0,
               lastDailyProfitResetDate: parsed.lastDailyProfitResetDate ? new Date(parsed.lastDailyProfitResetDate) : null,
               lastMonthlyProfitResetDate: parsed.lastMonthlyProfitResetDate ? new Date(parsed.lastMonthlyProfitResetDate) : null
             };
             localStorage.setItem(reportsKey, JSON.stringify(reportsData));
           } catch {}
        }
      }

      _reportsCache[cacheKey] = reportsData;
      return { ...reportsData };
    } catch (error) {
      console.error('خطأ في قراءة بيانات التقارير:', error);
      return {
        lastDailyResetDate: null,
        lastMonthlyResetDate: null,
        hiddenDailyTransactionIds: [],
        hiddenMonthlyTransactionIds: [],
        dailyProfit: 0,
        monthlyProfit: 0,
        lastDailyProfitResetDate: null,
        lastMonthlyProfitResetDate: null
      };
    }
  },

  // تصفية المعاملات المخفية
  filterVisibleTransactions: (transactions: any[], type: 'daily' | 'monthly', userId?: string): any[] => {
    try {
      const reportsData = reportsService.getReportsData(userId);
      const hiddenIds = type === 'daily'
        ? reportsData.hiddenDailyTransactionIds
        : reportsData.hiddenMonthlyTransactionIds;

      const toId = (tx: any) => String(tx?.id ?? tx?.transactionId ?? '').trim();
      const filtered = transactions.filter(tx => {
        const id = toId(tx);
        if (!id) return true;
        if (hiddenIds.includes(id)) return false;
        return true;
      });

      return filtered;
    } catch (error) {
      console.error('خطأ في تصفية المعاملات:', error);
      return transactions;
    }
  },

  // إضافة ربح إلى التقارير
  addProfit: (amount: number, type: 'daily' | 'monthly', userId?: string): void => {
    try {
      const reportsKey = userId ? `reportsData_${userId}` : 'reportsData';
      const reportsData = reportsService.getReportsData(userId);
      
      if (type === 'daily') {
        reportsData.dailyProfit += amount;
      } else {
        reportsData.monthlyProfit += amount;
      }
      
      localStorage.setItem(reportsKey, JSON.stringify(reportsData));
      _reportsCache[userId || 'default'] = reportsData;
      // مزامنة مع Firebase — لا تُرسل عند تفعيل «تأجيل المزامنة / الأوفلاين اليدوي»
      if (userId && !isManualFirestoreHoldEffective(userId)) {
        try {
          userDataService.updateUserData(userId, { reportsData: { ...reportsData } });
        } catch (e) {
          console.warn('تعذر مزامنة أرباح التقارير مع Firebase:', e);
        }
      }
      try { window.dispatchEvent(new CustomEvent('reportsUpdated', { detail: { userId, type, amount } })); } catch {}
    } catch (error) {
      console.error('خطأ في إضافة الربح:', error);
    }
  },

  // الحصول على الأرباح
  getProfits: (userId?: string): { dailyProfit: number; monthlyProfit: number } => {
    try {
      const reportsData = reportsService.getReportsData(userId);
      return {
        dailyProfit: reportsData.dailyProfit,
        monthlyProfit: reportsData.monthlyProfit
      };
    } catch (error) {
      console.error('خطأ في قراءة الأرباح:', error);
      return { dailyProfit: 0, monthlyProfit: 0 };
    }
  },

  // إزالة تأثيرات معاملة من التقارير (خصم الربح اليومي/الشهري)
  removeTransactionEffects: (transaction: any, userId?: string): void => {
    try {
      const reportsKey = userId ? `reportsData_${userId}` : 'reportsData';
      const reportsData = reportsService.getReportsData(userId);

      // التأكد من وجود تاريخ صحيح للمعاملة
      const txDate = new Date(transaction.createdAt);
      const today = new Date();
      const currentMonth = today.getMonth();
      const currentYear = today.getFullYear();

      // حساب الربح الخاص بهذه المعاملة
      const profitToRemove = reportsService.calculateTransactionProfit(transaction);

      // خصم من الربح اليومي إذا كانت المعاملة ضمن اليوم الحالي ولم تكن مخفية
      if (txDate.toDateString() === today.toDateString()) {
        // التأكد من أن المعاملة غير مخفية يومياً
        const hiddenDailyIds = reportsData.hiddenDailyTransactionIds || [];
        if (!hiddenDailyIds.includes(transaction.id)) {
          reportsData.dailyProfit = Math.round((reportsData.dailyProfit - profitToRemove) * 100) / 100;
          // تم السماح بالقيم السالبة بناءً على طلب المستخدم (للخصومات مثل عمولة ATM)
        }
      }

      // خصم من الربح الشهري إذا كانت ضمن الشهر الحالي ولم تكن مخفية
      if (txDate.getMonth() === currentMonth && txDate.getFullYear() === currentYear) {
        const hiddenMonthlyIds = reportsData.hiddenMonthlyTransactionIds || [];
        if (!hiddenMonthlyIds.includes(transaction.id)) {
          reportsData.monthlyProfit = Math.round((reportsData.monthlyProfit - profitToRemove) * 100) / 100;
          // تم السماح بالقيم السالبة بناءً على طلب المستخدم (للخصومات مثل عمولة ATM)
        }
      }

      localStorage.setItem(reportsKey, JSON.stringify(reportsData));
      _reportsCache[userId || 'default'] = reportsData;
      // مزامنة مع Firebase
      if (userId) {
        try {
          userDataService.updateUserData(userId, { reportsData: { ...reportsData } });
        } catch (e) {
          console.warn('تعذر مزامنة خصم تأثيرات المعاملة مع Firebase:', e);
        }
      }
    } catch (error) {
      console.error('خطأ في خصم تأثيرات المعاملة من التقارير:', error);
    }
  },

  // حساب الربح من المعاملة
  calculateTransactionProfit: (transaction: any): number => {
    const statusRaw = String((transaction as any)?.status || '').toLowerCase();
    if (statusRaw && statusRaw !== 'completed' && statusRaw !== 'confirmed') {
      return 0;
    }

    const rawType = String(transaction.type || transaction.txnType || '').toLowerCase();
    
    // معالجة خاصة لعمولة سحب ATM (تخصم من الأرباح)
    if (rawType === 'atm_withdraw') {
       const commission = Number(transaction.commission || 0);
       return -1 * Math.abs(commission);
    }

    const fee = Number((transaction as any)?.fee ?? 0);
    if (transaction.commission !== undefined) {
      const base = Math.max(0, Number(transaction.commission || 0));
      return Math.round((base + Math.max(0, fee)) * 100) / 100;
    }

    const normalizedType = rawType === 'withdrawal' ? 'withdraw' : rawType;

    if (normalizedType === 'withdraw' || normalizedType === 'receive' || normalizedType === 'send' || normalizedType === 'transfer') {
      const fallback = Math.round(Number(transaction.amount || 0) * 0.01 * 100) / 100;
      return Math.round((fallback + Math.max(0, fee)) * 100) / 100;
    }

    return 0;
  }
};

// توافقاً مع استخدام بعض الأجزاء التي تستورد باسم ReportsService
export const ReportsService = reportsService;
