/**
 * خدمة إدارة الرقم السري الرئيسي مع ربطه بالمستخدم وحفظه في Firestore و localStorage
 */

import { doc, getDoc, setDoc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { db } from '@/firebase';
import { userDataService } from '@/integrations/firebase/services';

const MASTER_PIN_KEY_BASE = 'master_pin';
const masterPinCache: Map<string, string> = new Map(); // يخزن القيمة المشفرة لكل مستخدم

// Helper to convert Arabic digits to English
function normalizePinDigits(pin: string): string {
  return pin.replace(/[٠-٩]/g, d => '0123456789'['٠١٢٣٤٥٦٧٨٩'.indexOf(d)]);
}

function getKey(userId?: string) {
  return userId ? `${MASTER_PIN_KEY_BASE}_${userId}` : MASTER_PIN_KEY_BASE;
}

async function loadFromFirestore(userId: string): Promise<string | null> {
  try {
    const data = await userDataService.getUserData(userId);
    const encoded = (data?.security && data.security.masterPin) || (data as any)?.masterPin || null;
    return typeof encoded === 'string' && encoded.length > 0 ? encoded : null;
  } catch {
    // فشل الشبكة أو عدم وجود الوثيقة
    try {
      const docRef = doc(db, 'users', userId);
      const snap = await getDoc(docRef);
      if (snap.exists()) {
        const data: any = snap.data();
        const encoded = (data?.security && data.security.masterPin) || data?.masterPin || null;
        return typeof encoded === 'string' && encoded.length > 0 ? encoded : null;
      }
    } catch {}
    return null;
  }
}

function loadFromLocalStorage(userId?: string): string | null {
  try {
    const val = localStorage.getItem(getKey(userId));
    return val && val.length > 0 ? val : null;
  } catch {
    return null;
  }
}

async function persistToFirestore(userId: string, encodedPin: string | null) {
  try {
    const payload: any = {
      security: {
        masterPin: encodedPin || null,
        masterPinUpdatedAt: serverTimestamp()
      },
      updatedAt: serverTimestamp()
    };
    await setDoc(doc(db, 'users', userId), payload, { merge: true });
  } catch (e) {
    // محاولة بديلة باستخدام updateDoc إذا كان المستند موجوداً
    try {
      await updateDoc(doc(db, 'users', userId), {
        security: {
          masterPin: encodedPin || null,
          masterPinUpdatedAt: serverTimestamp()
        },
        updatedAt: serverTimestamp()
      });
    } catch {}
  }
}

function persistToLocalStorage(userId: string | undefined, encodedPin: string | null) {
  try {
    const key = getKey(userId);
    if (encodedPin) {
      localStorage.setItem(key, encodedPin);
    } else {
      localStorage.removeItem(key);
    }
  } catch {}
}

export class MasterPinService {
  /**
   * التحقق من وجود رقم سري رئيسي (يحمّل من الذاكرة أو التخزين إذا لزم)
   */
  static async hasMasterPin(userId?: string): Promise<boolean> {
    const userKey = getKey(userId);
    // 1) فحص الكاش للمفتاح الخاص بالمستخدم
    if (masterPinCache.has(userKey)) {
      const val = masterPinCache.get(userKey)!;
      return val !== '' && val != null;
    }
    // 2) فحص التخزين المحلي للمفتاح الخاص بالمستخدم
    const localValUser = loadFromLocalStorage(userId);
    if (localValUser) {
      masterPinCache.set(userKey, localValUser);
      return true;
    }
    // 3) في حال توفر userId، افحص المفتاح الأساسي (غير المرتبط بمستخدم) وقم بمهاجرته
    if (userId) {
      const baseVal = loadFromLocalStorage(undefined);
      if (baseVal) {
        // هجرة: انقل القيمة إلى مفتاح المستخدم واحفظها في Firestore، واحذف المفتاح الأساسي
        masterPinCache.set(userKey, baseVal);
        persistToLocalStorage(userId, baseVal);
        try { persistToLocalStorage(undefined, null); } catch {}
        await persistToFirestore(userId, baseVal);
        return true;
      }
    }
    // 4) فحص Firestore عند توفر userId ثم مزامنة محلية
    if (userId) {
      const remoteVal = await loadFromFirestore(userId);
      if (remoteVal) {
        masterPinCache.set(userKey, remoteVal);
        persistToLocalStorage(userId, remoteVal);
        try { persistToLocalStorage(undefined, null); } catch {}
        return true;
      }
    }
    return false;
  }

  /**
   * إنشاء رقم سري رئيسي جديد
   */
  static async createMasterPin(pin: string, userId?: string): Promise<boolean> {
    try {
      const trimmed = (pin || '').trim();
      const normalizedPin = normalizePinDigits(trimmed);
      if (!normalizedPin || normalizedPin.length < 4) return false;
      // مطابقة تطبيق سطح المكتب: UTF-8 ثم base64 — للأرقام فقط يعادل btoa بعد التطبيع
      const encodedPin = btoa(normalizedPin);
      const key = getKey(userId);
      masterPinCache.set(key, encodedPin);
      persistToLocalStorage(userId, encodedPin);
      if (userId) await persistToFirestore(userId, encodedPin);
      return true;
    } catch (error) {
      console.error('Error creating master PIN:', error);
      return false;
    }
  }

  /**
   * التحقق من صحة الرقم السري الرئيسي
   */
  static async verifyMasterPin(inputPin: string, userId?: string): Promise<boolean> {
    try {
      const trimmedPin = inputPin.trim();
      const normalizedPin = normalizePinDigits(trimmedPin);
      
      const key = getKey(userId);
      // 1) التحقق الطبيعي باستخدام المفتاح المحدد
      if (await this.hasMasterPin(userId)) {
        const savedEncoded = masterPinCache.get(key);
        if (savedEncoded) {
          const decodedPin = atob(savedEncoded);
          // Check both raw (trimmed) and normalized (English digits)
          if (decodedPin === trimmedPin || decodedPin === normalizedPin) return true;
        }
      }

      // 2) محاولة استعادة/تصحيح: إذا فشل التحقق مع userId، نتحقق من المفتاح العام (master_pin)
      // هذا يعالج حالة وجود رقم سري صحيح في المفتاح العام ورقم خطأ في مفتاح المستخدم
      if (userId) {
        const genericKey = getKey(undefined);
        const genericVal = localStorage.getItem(genericKey);
        
        if (genericVal) {
          try {
            const genericDecoded = atob(genericVal);
            // Check both raw and normalized against generic pin
            if (genericDecoded === trimmedPin || genericDecoded === normalizedPin) {
              console.log('Master PIN auto-correction: Generic PIN matched while User PIN failed. Updating User PIN.');
              
              // تحديث مفتاح المستخدم بالقيمة الصحيحة من المفتاح العام
              masterPinCache.set(key, genericVal);
              persistToLocalStorage(userId, genericVal);
              await persistToFirestore(userId, genericVal);
              
              return true;
            }
          } catch {}
        }
      }

      return false;
    } catch (error) {
      console.error('Error verifying master PIN:', error);
      return false;
    }
  }

  /**
   * تغيير الرقم السري الرئيسي
   */
  static async changeMasterPin(currentPin: string, newPin: string, userId?: string): Promise<boolean> {
    try {
      const ok = await this.verifyMasterPin(currentPin, userId);
      if (!ok) return false;
      return await this.createMasterPin(newPin, userId);
    } catch (error) {
      console.error('Error changing master PIN:', error);
      return false;
    }
  }

  /**
   * حذف الرقم السري الرئيسي
   */
  static async deleteMasterPin(userId?: string): Promise<boolean> {
    try {
      const key = getKey(userId);
      masterPinCache.delete(key);
      persistToLocalStorage(userId, null);
      if (userId) {
        persistToLocalStorage(undefined, null); // حذف المفتاح العام أيضاً
        await persistToFirestore(userId, null);
      }
      return true;
    } catch (error) {
      console.error('Error deleting master PIN:', error);
      return false;
    }
  }

  /**
   * الحصول على الرقم السري (للاختبار فقط)
   */
  static async getMasterPin(userId?: string): Promise<string | null> {
    try {
      const key = getKey(userId);
      if (!(await this.hasMasterPin(userId))) return null;
      const savedEncoded = masterPinCache.get(key);
      return savedEncoded ? atob(savedEncoded) : null;
    } catch (error) {
      console.error('Error getting master PIN:', error);
      return null;
    }
  }
}