// ✅ روابط فالباك من البيئة في حال تعذّر تحميلها من فايرستور
const ENV_ANDROID_URL = (import.meta as any)?.env?.VITE_ANDROID_DOWNLOAD_URL as string | undefined;
const ENV_PC_URL = (import.meta as any)?.env?.VITE_PC_DOWNLOAD_URL as string | undefined;
const ENV_PC32_URL = (import.meta as any)?.env?.VITE_PC32_DOWNLOAD_URL as string | undefined;
// ✅ فالباك لرقم الإصدار عبر متغيرات البيئة في حال تعذّر القراءة من فايرستور
const ENV_ANDROID_VERSION = (import.meta as any)?.env?.VITE_ANDROID_VERSION as string | undefined;
const ENV_PC_VERSION = (import.meta as any)?.env?.VITE_PC_VERSION as string | undefined;
const ENV_PC32_VERSION = (import.meta as any)?.env?.VITE_PC32_VERSION as string | undefined;

// محاولة ذكية لاستخراج رقم الإصدار من اسم الملف/الرابط إذا كان يتضمن نمطاً مألوفاً
function inferVersionFromUrl(url?: string): string | undefined {
  if (!url) return undefined;
  try {
    const filename = url.split('?')[0].split('#')[0].split('/').pop() || '';
    // أمثلة: app-1.2.3.exe, release_v2.0.zip, Cashy-Setup-2.1.0.exe
    const match = filename.match(/v?(\d+\.\d+(?:\.\d+)?)/i);
    return match?.[1];
  } catch {
    return undefined;
  }
}

const SMS_AGENT_UPDATES_DOC_PATH = ['siteContent', 'sms_agent_updates'] as const;

export interface SmsAgentUpdateInfo {
  version?: string;
  url?: string;
  notes?: string;
  force?: boolean;
  code?: number;
  cancelled?: boolean;
}

export async function setSmsAgentUpdateInfo(
  info: SmsAgentUpdateInfo,
  adminId: string
): Promise<void> {
  const cleaned: any = {};
  Object.entries(info || {}).forEach(([k, v]) => { if (v !== undefined) cleaned[k] = v; });
  const payload: any = { ...cleaned, updatedAt: serverTimestamp(), updatedBy: adminId || 'admin' };
  await setDoc(doc(db, SMS_AGENT_UPDATES_DOC_PATH[0], SMS_AGENT_UPDATES_DOC_PATH[1]), payload, { merge: true });
}

export async function fetchSmsAgentUpdates(): Promise<SmsAgentUpdateInfo> {
  try {
    const refDoc = doc(db, SMS_AGENT_UPDATES_DOC_PATH[0], SMS_AGENT_UPDATES_DOC_PATH[1]);
    const snap = await getDoc(refDoc);
    
    const data = (snap.exists() ? (snap.data() as any) : {}) || {};
    return {
      version: data?.version ? String(data.version) : undefined,
      url: data?.url ? String(data.url) : undefined,
      notes: data?.notes ? String(data.notes) : undefined,
      force: !!data?.force,
      code: typeof data?.code === 'number' ? data.code : (typeof data?.versionCode === 'number' ? data.versionCode : undefined),
    };
  } catch (error) {
    console.warn('Error fetching SMS agent updates:', error);
    return {};
  }
}

export type AppTarget = 'android' | 'pc' | 'pc32';

export interface AppDownloads {
  androidUrl?: string;
  pcUrl?: string;
  pc32Url?: string;
  androidVersion?: string;
  pcVersion?: string;
  pc32Version?: string;
  /** رقم إصدار الأندرويد (versionCode) — إن وُجد يتحقق التطبيق منه قبل عرض نافذة التحديث */
  androidVersionCode?: number;
  /** تحديث إجباري — لا يظهر زر "لاحقاً" في نافذة التحديث */
  androidForce?: boolean;
  updatedAt?: any;
  updatedBy?: string;
}

// يحوّل روابط Google Drive من نمط العرض إلى رابط تنزيل مباشر لتجنّب ORB
export function resolveDownloadUrl(url?: string): string | undefined {
  if (!url) return undefined;
  
  // تحقق من الروابط المحظورة
  if (sanitizeUrl(url) === undefined) return undefined;

  try {
    // أنماط مدعومة:
    // - https://drive.google.com/file/d/<FILE_ID>/view?usp=sharing
    // - https://drive.google.com/uc?export=download&id=<FILE_ID>
    // - https://drive.google.com/open?id=<FILE_ID>
    const fileMatch = url.match(/drive\.google\.com\/file\/d\/([^/]+)\//);
    const openMatch = url.match(/drive\.google\.com\/open\?id=([^&]+)/);
    const id = fileMatch?.[1] || openMatch?.[1];
    if (id) {
      return `https://drive.google.com/uc?export=download&id=${id}`;
    }
    // إن كان بالفعل رابط uc مباشرةً، أعده كما هو
    if (/drive\.google\.com\/uc\?/.test(url)) return url;
    // روابط غير Google Drive تبقى كما هي
    return url;
  } catch {
    return url;
  }
}

const APP_DOC_PATH = ['siteContent', 'appDownloads'] as const;
const DESKTOP_UPDATES_DOC_PATH = ['siteContent', 'desktop_updates'] as const;
const ANDROID_UPDATES_DOC_PATH = ['siteContent', 'android_updates'] as const;
const APP_DOWNLOADS_CACHE_KEY = 'appDownloadsCache';
const CACHE_TTL = 6 * 60 * 60 * 1000; // 6 hours

// روابط محظورة تسبب مشاكل (مثل ORB errors)
const BLOCKED_URL_IDS = ['1LMXQdSVB3-gIW-89fwWoq113IIEelhxR'];

function sanitizeUrl(url?: string): string | undefined {
  if (!url) return undefined;
  for (const id of BLOCKED_URL_IDS) {
    if (url.includes(id)) return undefined;
  }
  return url;
}

function sanitizeAppDownloads(data: AppDownloads): AppDownloads {
  return {
    ...data,
    androidUrl: sanitizeUrl(data.androidUrl),
    pcUrl: sanitizeUrl(data.pcUrl),
    pc32Url: sanitizeUrl(data.pc32Url),
  };
}

// دالة متزامنة تُعيد فوراً آخر روابط محفوظة في التخزين المحلي أو قيم البيئة
export function getCachedOrEnvAppDownloads(): AppDownloads {
  try {
    const cached = localStorage.getItem(APP_DOWNLOADS_CACHE_KEY);
    if (cached) {
      const cachedData = JSON.parse(cached) as AppDownloads;
      const merged: AppDownloads = {
        androidUrl: cachedData?.androidUrl || ENV_ANDROID_URL,
        pcUrl: cachedData?.pcUrl || ENV_PC_URL,
        pc32Url: cachedData?.pc32Url || ENV_PC32_URL,
        androidVersion: cachedData?.androidVersion || ENV_ANDROID_VERSION,
        pcVersion: cachedData?.pcVersion || ENV_PC_VERSION,
        pc32Version: cachedData?.pc32Version || ENV_PC32_VERSION,
        updatedAt: cachedData?.updatedAt,
        updatedBy: cachedData?.updatedBy,
      };
      if (!merged.pcVersion) merged.pcVersion = inferVersionFromUrl(merged.pcUrl);
      if (!merged.androidVersion) merged.androidVersion = inferVersionFromUrl(merged.androidUrl);
      if (!merged.pc32Version) merged.pc32Version = inferVersionFromUrl(merged.pc32Url);
      return sanitizeAppDownloads(merged);
    }
  } catch {}
  const fallback: AppDownloads = {
    androidUrl: ENV_ANDROID_URL,
    pcUrl: ENV_PC_URL,
    pc32Url: ENV_PC32_URL,
    androidVersion: ENV_ANDROID_VERSION,
    pcVersion: ENV_PC_VERSION,
    pc32Version: ENV_PC32_VERSION,
  };
  if (!fallback.pcVersion) fallback.pcVersion = inferVersionFromUrl(fallback.pcUrl);
  if (!fallback.androidVersion) fallback.androidVersion = inferVersionFromUrl(fallback.androidUrl);
  if (!fallback.pc32Version) fallback.pc32Version = inferVersionFromUrl(fallback.pc32Url);
  return sanitizeAppDownloads(fallback);
}

export async function getAppDownloads(forceRefresh = false): Promise<AppDownloads> {
  try {
    // Check cache validity
    if (!forceRefresh) {
      try {
        const cached = localStorage.getItem(APP_DOWNLOADS_CACHE_KEY);
        const cachedTs = localStorage.getItem(APP_DOWNLOADS_CACHE_KEY + '_ts');
        if (cached && cachedTs) {
          const now = Date.now();
          if (now - Number(cachedTs) < CACHE_TTL) {
             const cachedData = JSON.parse(cached) as AppDownloads;
             // Return cached if valid
             return sanitizeAppDownloads(cachedData);
          }
        }
      } catch {}
    }

    const appDoc = await getDoc(doc(db, APP_DOC_PATH[0], APP_DOC_PATH[1]));
    if (appDoc.exists()) {
      const data = appDoc.data() as AppDownloads;
      try {
        localStorage.setItem(APP_DOWNLOADS_CACHE_KEY, JSON.stringify(data));
        localStorage.setItem(APP_DOWNLOADS_CACHE_KEY + '_ts', String(Date.now()));
      } catch {}
      // دمج قيم البيئة كقِيَم افتراضية في حال كانت الحقول غير موجودة
      const merged: AppDownloads = {
        androidUrl: data?.androidUrl || ENV_ANDROID_URL,
        pcUrl: data?.pcUrl || ENV_PC_URL,
        pc32Url: data?.pc32Url || ENV_PC32_URL,
        androidVersion: data?.androidVersion || ENV_ANDROID_VERSION,
        pcVersion: data?.pcVersion || ENV_PC_VERSION,
        pc32Version: data?.pc32Version || ENV_PC32_VERSION,
        updatedAt: data?.updatedAt,
        updatedBy: data?.updatedBy,
      };
      // إن لم توجد نسخة، جرّب استنتاجها من الرابط
      if (!merged.pcVersion) merged.pcVersion = inferVersionFromUrl(merged.pcUrl);
      if (!merged.androidVersion) merged.androidVersion = inferVersionFromUrl(merged.androidUrl);
      if (!merged.pc32Version) merged.pc32Version = inferVersionFromUrl(merged.pc32Url);
      return sanitizeAppDownloads(merged);
    }
    // لا يوجد مستند: استخدم الفالباك من البيئة إن وجِد
    const fallback: AppDownloads = {
      androidUrl: ENV_ANDROID_URL,
      pcUrl: ENV_PC_URL,
      pc32Url: ENV_PC32_URL,
      androidVersion: ENV_ANDROID_VERSION,
      pcVersion: ENV_PC_VERSION,
      pc32Version: ENV_PC32_VERSION,
    };
    if (!fallback.pcVersion) fallback.pcVersion = inferVersionFromUrl(fallback.pcUrl);
    if (!fallback.androidVersion) fallback.androidVersion = inferVersionFromUrl(fallback.androidUrl);
    if (!fallback.pc32Version) fallback.pc32Version = inferVersionFromUrl(fallback.pc32Url);
    return sanitizeAppDownloads(fallback);
  } catch (e) {
    const msg = (e as any)?.message || '';
    const code = (e as any)?.code || '';
    if (code === 'permission-denied' || msg.includes('Missing or insufficient permissions')) {
      console.warn('⚠️ Cannot read app downloads (unauth/public). Using cached or empty.', e);
    } else {
      console.error('❌ Error loading app downloads:', e);
    }
    try {
      const cached = localStorage.getItem(APP_DOWNLOADS_CACHE_KEY);
      if (cached) {
        const cachedData = JSON.parse(cached) as AppDownloads;
        const merged: AppDownloads = {
          androidUrl: cachedData?.androidUrl || ENV_ANDROID_URL,
          pcUrl: cachedData?.pcUrl || ENV_PC_URL,
          pc32Url: cachedData?.pc32Url || ENV_PC32_URL,
          androidVersion: cachedData?.androidVersion || ENV_ANDROID_VERSION,
          pcVersion: cachedData?.pcVersion || ENV_PC_VERSION,
          pc32Version: cachedData?.pc32Version || ENV_PC32_VERSION,
          updatedAt: cachedData?.updatedAt,
          updatedBy: cachedData?.updatedBy,
        };
        if (!merged.pcVersion) merged.pcVersion = inferVersionFromUrl(merged.pcUrl);
        if (!merged.androidVersion) merged.androidVersion = inferVersionFromUrl(merged.androidUrl);
        if (!merged.pc32Version) merged.pc32Version = inferVersionFromUrl(merged.pc32Url);
        return sanitizeAppDownloads(merged);
      }
    } catch {}
    // فالباك نهائي: استخدم قيم البيئة إن وُجدت
    const finalFallback: AppDownloads = {
      androidUrl: ENV_ANDROID_URL,
      pcUrl: ENV_PC_URL,
      pc32Url: ENV_PC32_URL,
      androidVersion: ENV_ANDROID_VERSION,
      pcVersion: ENV_PC_VERSION,
      pc32Version: ENV_PC32_VERSION,
    };
    if (!finalFallback.pcVersion) finalFallback.pcVersion = inferVersionFromUrl(finalFallback.pcUrl);
    if (!finalFallback.androidVersion) finalFallback.androidVersion = inferVersionFromUrl(finalFallback.androidUrl);
    if (!finalFallback.pc32Version) finalFallback.pc32Version = inferVersionFromUrl(finalFallback.pc32Url);
    return sanitizeAppDownloads(finalFallback);
  }
}

// تم استبدال الاستماع المستمر بالجلب مرة واحدة (cache-first)
export function listenAppDownloads(
  onChange: (data: AppDownloads) => void
): () => void {
  // جلب البيانات مرة واحدة فقط عند الاستدعاء
  getAppDownloads().then(onChange);
  // إرجاع دالة تفكيك فارغة للحفاظ على التوافق
  return () => {};
}

export async function uploadAppBinary(
  file: File,
  target: AppTarget,
  adminId: string,
  version?: string
): Promise<string> {
  const storage = getStorage();
  const safeName = file.name.replace(/[^a-zA-Z0-9_.-]/g, '_');
  // استخدم مسار "public/apps" ليتوافق مع قواعد التخزين الحالية (allow write if auth != null)
  const path = `public/apps/${target}/${Date.now()}_${safeName}`;
  const storageRef = ref(storage, path);

  try {
    await uploadBytes(storageRef, file);
    const url = await getDownloadURL(storageRef);

    const payload: Partial<AppDownloads> = {
      updatedAt: serverTimestamp(),
      updatedBy: adminId || 'admin',
    };
    if (target === 'android') {
      payload.androidUrl = url;
      if (version) payload.androidVersion = version;
    } else if (target === 'pc') {
      payload.pcUrl = url;
      if (version) payload.pcVersion = version;
    } else {
      payload.pc32Url = url;
      if (version) payload.pc32Version = version;
    }

    await setDoc(doc(db, APP_DOC_PATH[0], APP_DOC_PATH[1]), payload, { merge: true });

    // تحديث الكاش المحلي
    try {
      const cached = localStorage.getItem(APP_DOWNLOADS_CACHE_KEY);
      const cachedData = cached ? JSON.parse(cached) : {};
      // نستبدل serverTimestamp بقيمة يمكن تخزينها في JSON
      const cachePayload = { ...payload, updatedAt: Date.now() };
      const newData = { ...cachedData, ...cachePayload };
      localStorage.setItem(APP_DOWNLOADS_CACHE_KEY, JSON.stringify(newData));
      localStorage.setItem(APP_DOWNLOADS_CACHE_KEY + '_ts', String(Date.now()));
    } catch {}

    return url;
  } catch (e) {
    console.error('❌ Error uploading app binary:', e);
    throw e;
  }
}

// رفع برفع قابل للاستئناف مع تقدم ووقت قاطع
export async function uploadAppBinaryResumable(
  file: File,
  target: AppTarget,
  adminId: string,
  version?: string,
  onProgress?: (progress: number) => void,
  timeoutMs: number = 120000
): Promise<string> {
  const storage = getStorage();
  const safeName = file.name.replace(/[^a-zA-Z0-9_.-]/g, '_');
  const path = `public/apps/${target}/${Date.now()}_${safeName}`;
  const storageRef = ref(storage, path);

  return new Promise<string>((resolve, reject) => {
    const task = uploadBytesResumable(storageRef, file);
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      try { task.cancel(); } catch {}
      reject(new Error('Upload timed out'));
    }, timeoutMs);

    task.on('state_changed', (snapshot) => {
      const progress = Math.round((snapshot.bytesTransferred / snapshot.totalBytes) * 100);
      if (onProgress) onProgress(progress);
    }, (error) => {
      clearTimeout(timer);
      reject(error);
    }, async () => {
      try {
        clearTimeout(timer);
        if (timedOut) return; // already rejected
        const url = await getDownloadURL(storageRef);
        const payload: Partial<AppDownloads> = {
          updatedAt: serverTimestamp(),
          updatedBy: adminId || 'admin',
        };
        if (target === 'android') {
          payload.androidUrl = url;
          if (version) payload.androidVersion = version;
        } else if (target === 'pc') {
          payload.pcUrl = url;
          if (version) payload.pcVersion = version;
        } else {
          payload.pc32Url = url;
          if (version) payload.pc32Version = version;
        }
        // حماية من تعليق عملية الكتابة في Firestore بمهلة قصوى مستقلة
        const writeTimeoutMs = Math.min(Math.max(20000, Math.floor(timeoutMs / 10)), 60000); // بين 20-60 ثانية
        const writePromise = setDoc(doc(db, APP_DOC_PATH[0], APP_DOC_PATH[1]), payload, { merge: true });
        
        // تحديث الكاش المحلي بعد الرفع
        try {
          const cached = localStorage.getItem(APP_DOWNLOADS_CACHE_KEY);
          const cachedData = cached ? JSON.parse(cached) : {};
          const newData = { ...cachedData, ...payload };
          localStorage.setItem(APP_DOWNLOADS_CACHE_KEY, JSON.stringify(newData));
          localStorage.setItem(APP_DOWNLOADS_CACHE_KEY + '_ts', String(Date.now()));
        } catch {}

        let writeTimedOut = false;
        const writeTimeout = new Promise<void>((resolve) => setTimeout(() => { writeTimedOut = true; resolve(); }, writeTimeoutMs));
        try {
          await Promise.race([writePromise, writeTimeout]);
        } catch (writeErr) {
          console.warn('⚠️ Firestore write error, proceeding with URL only:', writeErr);
        }
        if (writeTimedOut) {
          console.warn('⚠️ Firestore update timed out; تم رفع الملف، لكن لم يتم تحديث معلومات الإصدار في قاعدة البيانات بعد.');
          // نكمل بإرجاع الرابط حتى لا تتعطل الواجهة
        }
        resolve(url);
      } catch (e) {
        reject(e);
      }
    });
  });
}

// تحديث الروابط مباشرة بدون رفع ملفات
export async function setAppDownloadLinks(
  links: Partial<AppDownloads>,
  adminId: string
): Promise<void> {
  // Remove undefined fields to avoid Firestore invalid data errors
  const cleaned: Partial<AppDownloads> = {};
  Object.entries(links || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      // allow empty strings, but skip undefined
      (cleaned as any)[key] = value;
    }
  });

  const payload: Partial<AppDownloads> = {
    ...cleaned,
    updatedAt: serverTimestamp(),
    updatedBy: adminId || 'admin',
  };
  await setDoc(doc(db, APP_DOC_PATH[0], APP_DOC_PATH[1]), payload, { merge: true });

  // تحديث الكاش المحلي لضمان ظهور البيانات الجديدة عند التحديث
  try {
    const cached = localStorage.getItem(APP_DOWNLOADS_CACHE_KEY);
    const cachedData = cached ? JSON.parse(cached) : {};
    // نستبدل serverTimestamp بقيمة يمكن تخزينها في JSON
    const cachePayload = { ...payload, updatedAt: Date.now() };
    const newData = { ...cachedData, ...cachePayload };
    localStorage.setItem(APP_DOWNLOADS_CACHE_KEY, JSON.stringify(newData));
    localStorage.setItem(APP_DOWNLOADS_CACHE_KEY + '_ts', String(Date.now()));
  } catch {}
}

export interface DesktopUpdateInfo {
  version?: string;
  downloadURL_64?: string;
  downloadURL_32?: string;
  notes?: string;
  force?: boolean;
}

export async function setDesktopUpdateInfo(
  info: DesktopUpdateInfo,
  adminId: string
): Promise<void> {
  const cleaned: any = {};
  Object.entries(info || {}).forEach(([k, v]) => { if (v !== undefined) cleaned[k] = v; });
  const payload: any = { ...cleaned, updatedAt: serverTimestamp(), updatedBy: adminId || 'admin' };
  await setDoc(doc(db, DESKTOP_UPDATES_DOC_PATH[0], DESKTOP_UPDATES_DOC_PATH[1]), payload, { merge: true });
  
  // تحديث الكاش المحلي
  try {
    const cached = localStorage.getItem('desktop_update_cache');
    const cachedData = cached ? JSON.parse(cached) : {};
    const cachePayload = { ...payload, updatedAt: Date.now() };
    const newData = { ...cachedData, ...cachePayload };
    localStorage.setItem('desktop_update_cache', JSON.stringify(newData));
  } catch {}
}

export async function fetchDesktopUpdates(): Promise<DesktopUpdateInfo> {
  try {
    // محاولة قراءة الكاش أولاً
    try {
      const cachedRaw = localStorage.getItem('desktop_update_cache');
      if (cachedRaw) {
        const cached = JSON.parse(cachedRaw);
        // إذا كان الكاش حديثاً (مثلاً أقل من ساعة)، نعيده فوراً
        // لكن هنا سنعيده ونقوم بالتحديث في الخلفية أو نكتفي به إذا أردنا تقليل القراءات بشدة
        // سنقوم بالجلب من السيرفر دائماً لضمان الدقة في لوحة التحكم، ولكن الكاش مفيد للتحميل السريع
      }
    } catch {}

    const refDoc = doc(db, DESKTOP_UPDATES_DOC_PATH[0], DESKTOP_UPDATES_DOC_PATH[1]);
    const snap = await getDoc(refDoc);
    
    const data = (snap.exists() ? (snap.data() as any) : {}) || {};
    const payload = {
      version: data?.version ? String(data.version) : undefined,
      downloadURL_64: data?.downloadURL_64 ? String(data.downloadURL_64) : undefined,
      downloadURL_32: data?.downloadURL_32 ? String(data.downloadURL_32) : undefined,
      notes: data?.notes ? String(data.notes) : undefined,
      force: data?.force === true || data?.force === 'true',
    };
    
    try { localStorage.setItem('desktop_update_cache', JSON.stringify(payload)); } catch {}
    return payload;
  } catch (error) {
    console.warn('Error fetching desktop updates:', error);
    try {
      const cachedRaw = localStorage.getItem('desktop_update_cache');
      if (cachedRaw) return JSON.parse(cachedRaw);
    } catch {}
    return {};
  }
}

// تم استعادة الاستماع المستمر لتحديثات سطح المكتب لضمان ظهور النافذة فوراً عند النشر
export function listenDesktopUpdates(
  onChange: (data: { version?: string; downloadURL_64?: string; downloadURL_32?: string; notes?: string; force?: boolean }) => void
): () => void {
  const refDoc = doc(db, DESKTOP_UPDATES_DOC_PATH[0], DESKTOP_UPDATES_DOC_PATH[1]);
  // استماع حقيقي للتغييرات في قاعدة البيانات
  const unsub = onSnapshot(refDoc, (snap) => {
    if (snap.exists()) {
      const data = snap.data() as any;
      const payload = {
        version: data?.version ? String(data.version) : undefined,
        downloadURL_64: data?.downloadURL_64 ? String(data.downloadURL_64) : undefined,
        downloadURL_32: data?.downloadURL_32 ? String(data.downloadURL_32) : undefined,
        notes: data?.notes ? String(data.notes) : undefined,
        force: data?.force === true || data?.force === 'true',
      };
      // تحديث الكاش أيضاً عند ورود بيانات جديدة
      try { localStorage.setItem('desktop_update_cache', JSON.stringify(payload)); } catch {}
      onChange(payload);
    }
  }, (error) => {
    console.warn('Error listening to desktop updates:', error);
  });
  
  return unsub;
}

export function selectDesktopUrl(info: { downloadURL_64?: string; downloadURL_32?: string }): string | undefined {
  try {
    const ua = (typeof navigator !== 'undefined' ? navigator.userAgent.toLowerCase() : '') || '';
    const isWin64 = ua.includes('win64') || ua.includes('x64') || ua.includes('wow64') || ua.includes('amd64');
    const isArm64 = ua.includes('arm64');
    if (isWin64 || isArm64) return String(info?.downloadURL_64 || info?.downloadURL_32 || '');
    return String(info?.downloadURL_32 || info?.downloadURL_64 || '');
  } catch {
    return info?.downloadURL_64 || info?.downloadURL_32;
  }
}

export async function publishDesktopVersion(
  version: string,
  updateUrl64: string,
  updateUrli32: string,
  notes: string,
  force: boolean
): Promise<string> {
  // حاول أولاً النشر عبر دالة السيرفر لتفادي CORS
  try {
    const token = await auth.currentUser?.getIdToken?.();
    if (!token) throw new Error('missing-auth-token');
    const endpoint = 'https://us-central1-voda-c6abd.cloudfunctions.net/publishDesktopVersion';
    const resp = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ version, updateUrl64, updateUrli32, notes, force })
    });
    if (!resp.ok) {
      const txt = await resp.text();
      throw new Error(`publish failed: ${resp.status} ${txt}`);
    }
    const data = await resp.json();
    const url = String((data || {}).url || '');
    if (url) return url;
    throw new Error('no-url');
  } catch (e) {
    // فالباك: رفع مباشر عبر التخزين (يتطلب جلسة مصادقة صحيحة)
    const storage = getStorage();
    const storageRef = ref(storage, 'public/desktop_version.json');
    const json = JSON.stringify({ version, updateUrl64, updateUrli32, notes, force });
    const bytes = new Blob([json], { type: 'application/json' });
    await uploadBytes(storageRef, bytes, { contentType: 'application/json', cacheControl: 'no-cache, max-age=0' });
    const url = await getDownloadURL(storageRef);
    return url;
  }
}

export interface AndroidUpdateInfo {
  version?: string;
  url?: string;
  notes?: string;
  force?: boolean;
  code?: number;
}

export async function setAndroidUpdateInfo(
  info: AndroidUpdateInfo,
  adminId: string
): Promise<void> {
  const cleaned: any = {};
  Object.entries(info || {}).forEach(([k, v]) => { if (v !== undefined) cleaned[k] = v; });
  const payload: any = { ...cleaned, updatedAt: serverTimestamp(), updatedBy: adminId || 'admin' };
  await setDoc(doc(db, ANDROID_UPDATES_DOC_PATH[0], ANDROID_UPDATES_DOC_PATH[1]), payload, { merge: true });

  // تحديث الكاش المحلي
  try {
    const cached = localStorage.getItem('android_update_cache');
    const cachedData = cached ? JSON.parse(cached) : {};
    const cachePayload = { ...payload, updatedAt: Date.now() };
    const newData = { ...cachedData, ...cachePayload };
    localStorage.setItem('android_update_cache', JSON.stringify(newData));
  } catch {}
}

export async function fetchAndroidUpdates(): Promise<AndroidUpdateInfo> {
  try {
    const refDoc = doc(db, ANDROID_UPDATES_DOC_PATH[0], ANDROID_UPDATES_DOC_PATH[1]);
    const snap = await getDoc(refDoc);
    
    const data = (snap.exists() ? (snap.data() as any) : {}) || {};
    const payload: AndroidUpdateInfo = {
      version: data?.version ? String(data.version) : undefined,
      url: data?.url ? String(data.url) : undefined,
      notes: data?.notes ? String(data.notes) : undefined,
      force: !!data?.force,
      code: typeof data?.code === 'number' ? data.code : (typeof data?.versionCode === 'number' ? data.versionCode : undefined),
    };
    
    try { localStorage.setItem('android_update_cache', JSON.stringify(payload)); } catch {}
    return payload;
  } catch (error) {
    console.warn('Error fetching android updates:', error);
    try {
      const cachedRaw = localStorage.getItem('android_update_cache');
      if (cachedRaw) return JSON.parse(cachedRaw);
    } catch {}
    return {};
  }
}

/**
 * استماع فوري لإصدار الأندرويد (يعمل مع persistence وعند عدم استدعاء disableNetwork لتأجيل المزامنة).
 * يُحدّث الكاش المحلي عند كل لقطة.
 */
export function listenAndroidUpdates(
  onChange: (data: AndroidUpdateInfo) => void
): () => void {
  const refDoc = doc(db, ANDROID_UPDATES_DOC_PATH[0], ANDROID_UPDATES_DOC_PATH[1]);
  // جلب فوري من الكاش/الشبكة ثم المتابعة بالـ snapshot (تفادي فراغ أولي)
  void fetchAndroidUpdates().then(onChange);
  const unsub = onSnapshot(
    refDoc,
    (snap) => {
      const data = (snap.exists() ? (snap.data() as any) : {}) || {};
      const payload: AndroidUpdateInfo = {
        version: data?.version ? String(data.version) : undefined,
        url: data?.url ? String(data.url) : undefined,
        notes: data?.notes ? String(data.notes) : undefined,
        force: !!data?.force,
        code:
          typeof data?.code === 'number'
            ? data.code
            : typeof data?.versionCode === 'number'
              ? data.versionCode
              : undefined,
      };
      try {
        localStorage.setItem('android_update_cache', JSON.stringify(payload));
      } catch {
        /* ignore */
      }
      onChange(payload);
    },
    (err) => {
      console.warn('listenAndroidUpdates snapshot error:', err);
      try {
        const raw = localStorage.getItem('android_update_cache');
        if (raw) {
          const parsed = JSON.parse(raw) as AndroidUpdateInfo;
          if (parsed && (parsed.version || parsed.url || typeof parsed.code === 'number')) {
            onChange(parsed);
          }
        }
      } catch {
        /* ignore */
      }
      void fetchAndroidUpdates().then(onChange);
    }
  );
  return () => {
    try {
      unsub();
    } catch {
      /* ignore */
    }
  };
}

export async function publishAndroidVersion(
  version: string,
  url: string,
  notes: string,
  force: boolean
): Promise<string> {
  // حاول النشر عبر وظائف السحابة مع مهلة قصيرة، ثم فالباك فوري للتخزين
  try {
    const token = await auth.currentUser?.getIdToken?.();
    if (!token) throw new Error('missing-auth-token');
    const endpoint = 'https://us-central1-voda-c6abd.cloudfunctions.net/publishAndroidVersion';
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 8000);
    const resp = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ version, url, notes, force }),
      signal: controller.signal,
    }).catch((err) => { throw err; });
    clearTimeout(timeout);
    if (resp && resp.ok) {
      const data = await resp.json();
      const publishedUrl = String((data || {}).url || '');
      if (publishedUrl) return publishedUrl;
    }
    throw new Error('publish-via-function-failed');
  } catch {
    const storage = getStorage();
    const storageRef = ref(storage, 'public/android_version.json');
    const json = JSON.stringify({ version, url, notes, force });
    const bytes = new Blob([json], { type: 'application/json' });
    await uploadBytes(storageRef, bytes, { contentType: 'application/json', cacheControl: 'no-cache, max-age=0' });
    const publishedUrl = await getDownloadURL(storageRef);
    return publishedUrl;
  }
}
