import { doc, getDoc, setDoc } from 'firebase/firestore';
import { db, auth } from '@/firebase';
import React from 'react';

// نوع البيانات لإعدادات الواتساب
export interface WhatsAppSettings {
  phoneNumber: string;
  defaultMessage: string;
  isEnabled: boolean;
  lastUpdated: Date;
}

// الإعدادات الافتراضية
const DEFAULT_SETTINGS: WhatsAppSettings = {
  phoneNumber: "201000392539",
  defaultMessage: "مرحباً، أريد الاستفسار عن خدماتكم",
  isEnabled: true,
  lastUpdated: new Date()
};

// مرجع المستند في Firestore
const SETTINGS_DOC_ID = 'whatsapp-settings';
const SETTINGS_COLLECTION = 'app-settings';
const WHATSAPP_CACHE_KEY = 'whatsapp_settings_cache';

/**
 * تحميل إعدادات الواتساب من Firestore
 */
export const loadWhatsAppSettings = async (): Promise<WhatsAppSettings> => {
  try {
    // إذا لم يكن المستخدم مسجلاً الدخول، تجنب قراءة Firestore العامة لتفادي أخطاء الصلاحيات
    if (!auth.currentUser) {
      try {
        const cached = localStorage.getItem(WHATSAPP_CACHE_KEY);
        if (cached) {
          const parsed = JSON.parse(cached);
          return {
            phoneNumber: parsed.phoneNumber || DEFAULT_SETTINGS.phoneNumber,
            defaultMessage: parsed.defaultMessage || DEFAULT_SETTINGS.defaultMessage,
            isEnabled: parsed.isEnabled !== undefined ? parsed.isEnabled : DEFAULT_SETTINGS.isEnabled,
            lastUpdated: parsed.lastUpdated ? new Date(parsed.lastUpdated) : DEFAULT_SETTINGS.lastUpdated
          } as WhatsAppSettings;
        }
      } catch {}
      // مستخدم عام بدون كاش: ارجع الإعدادات الافتراضية بصمت
      return DEFAULT_SETTINGS;
    }

    const docRef = doc(db, SETTINGS_COLLECTION, SETTINGS_DOC_ID);
    const docSnap = await getDoc(docRef);
    
    if (docSnap.exists()) {
      const data = docSnap.data();
      const settings: WhatsAppSettings = {
        phoneNumber: data.phoneNumber || DEFAULT_SETTINGS.phoneNumber,
        defaultMessage: data.defaultMessage || DEFAULT_SETTINGS.defaultMessage,
        isEnabled: data.isEnabled !== undefined ? data.isEnabled : DEFAULT_SETTINGS.isEnabled,
        lastUpdated: data.lastUpdated?.toDate() || DEFAULT_SETTINGS.lastUpdated
      };
      // خزن نسخة في التخزين المحلي لاستخدامها لزوار غير مسجلين
      try { localStorage.setItem(WHATSAPP_CACHE_KEY, JSON.stringify(settings)); } catch {}
      return settings;
    } else {
      // إذا لم توجد الإعدادات، احفظ الإعدادات الافتراضية
      await saveWhatsAppSettings(DEFAULT_SETTINGS);
      return DEFAULT_SETTINGS;
    }
  } catch (error) {
    // في حال أخطاء الصلاحيات أو الشبكة، استخدم الكاش أو الافتراضي بدون إزعاج المستخدم العام
    try {
      const cached = localStorage.getItem(WHATSAPP_CACHE_KEY);
      if (cached) {
        const parsed = JSON.parse(cached);
        return {
          phoneNumber: parsed.phoneNumber || DEFAULT_SETTINGS.phoneNumber,
          defaultMessage: parsed.defaultMessage || DEFAULT_SETTINGS.defaultMessage,
          isEnabled: parsed.isEnabled !== undefined ? parsed.isEnabled : DEFAULT_SETTINGS.isEnabled,
          lastUpdated: parsed.lastUpdated ? new Date(parsed.lastUpdated) : DEFAULT_SETTINGS.lastUpdated
        } as WhatsAppSettings;
      }
    } catch {}
    return DEFAULT_SETTINGS;
  }
};

/**
 * حفظ إعدادات الواتساب في Firestore
 */
export const saveWhatsAppSettings = async (settings: Partial<WhatsAppSettings>): Promise<boolean> => {
  try {
    const docRef = doc(db, SETTINGS_COLLECTION, SETTINGS_DOC_ID);
    
    // تحديث الإعدادات مع الاحتفاظ بالقيم الموجودة
    const updatedSettings = {
      ...settings,
      lastUpdated: new Date()
    };
    
    await setDoc(docRef, updatedSettings, { merge: true });
    // حدث الكاش المحلي بعد نجاح الحفظ
    try { localStorage.setItem(WHATSAPP_CACHE_KEY, JSON.stringify(updatedSettings)); } catch {}
    return true;
  } catch (error) {
    console.error('خطأ في حفظ إعدادات الواتساب:', error);
    return false;
  }
};

/**
 * تنسيق رقم الواتساب (إزالة الرموز غير المرغوب فيها)
 */
export const formatPhoneNumber = (phoneNumber: string): string => {
  // إزالة جميع الرموز غير الرقمية
  const cleanNumber = phoneNumber.replace(/\D/g, '');
  
  // التأكد من وجود رقم صحيح
  if (cleanNumber.length < 10) {
    throw new Error('رقم الهاتف يجب أن يحتوي على 10 أرقام على الأقل');
  }
  
  return cleanNumber;
};

/**
 * التحقق من صحة رقم الواتساب
 */
export const validatePhoneNumber = (phoneNumber: string): boolean => {
  try {
    const formatted = formatPhoneNumber(phoneNumber);
    return formatted.length >= 10 && formatted.length <= 15;
  } catch {
    return false;
  }
};

/**
 * إنشاء رابط الواتساب
 */
export const createWhatsAppLink = (phoneNumber: string, message: string): string => {
  const formattedNumber = formatPhoneNumber(phoneNumber);
  const encodedMessage = encodeURIComponent(message);
  return `https://wa.me/${formattedNumber}?text=${encodedMessage}`;
};

/**
 * إنشاء رابط واتساب للاشتراك في باقة معينة
 */
export const createSubscriptionWhatsAppLink = async (
  planName: string, 
  price: string, 
  features: string[]
): Promise<string> => {
  const settings = await loadWhatsAppSettings();
  
  const message = `مرحباً! أريد الاشتراك في باقة ${planName} بسعر ${price}

المميزات المشمولة:
${features.map(feature => `✅ ${feature}`).join('\n')}

أرجو التواصل معي لإتمام عملية الاشتراك.`;

  return createWhatsAppLink(settings.phoneNumber, message);
};

/**
 * إنشاء رابط واتساب للاستفسار العام
 */
export const createGeneralWhatsAppLink = async (): Promise<string> => {
  const settings = await loadWhatsAppSettings();
  
  const message = `مرحباً! أريد الاستفسار عن خدمات CashyLink لإدارة المحافظ الإلكترونية.

أرجو التواصل معي لمعرفة المزيد عن الباقات المتاحة وكيفية البدء.`;

  return createWhatsAppLink(settings.phoneNumber, message);
};

// Hook لاستخدام إعدادات الواتساب في React
export const useWhatsAppSettings = () => {
  const [settings, setSettings] = React.useState<WhatsAppSettings | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    const loadSettings = async () => {
      try {
        setLoading(true);
        const loadedSettings = await loadWhatsAppSettings();
        setSettings(loadedSettings);
        setError(null);
      } catch (err) {
        setError('فشل في تحميل إعدادات الواتساب');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    loadSettings();
  }, []);

  const updateSettings = async (newSettings: Partial<WhatsAppSettings>) => {
    try {
      setLoading(true);
      const success = await saveWhatsAppSettings(newSettings);
      if (success && settings) {
        setSettings({ ...settings, ...newSettings, lastUpdated: new Date() });
        setError(null);
        return true;
      } else {
        setError('فشل في حفظ الإعدادات');
        return false;
      }
    } catch (err) {
      setError('خطأ في تحديث الإعدادات');
      console.error(err);
      return false;
    } finally {
      setLoading(false);
    }
  };

  return {
    settings,
    loading,
    error,
    updateSettings,
    refreshSettings: () => loadWhatsAppSettings().then(setSettings)
  };
};

