import React, { useEffect, useState, useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Check, X, Loader2, Clock } from 'lucide-react';
import { processVfNotification } from '@/utils/vfNotificationIntegration';
import { useToast } from '@/hooks/use-toast';

interface PendingTransaction {
  id: string;
  data: any;
  status: 'pending' | 'processing' | 'success' | 'error';
  errorMessage?: string;
  receivedAt: number;
}

export const PendingTransactionsDialog: React.FC = () => {
  const [open, setOpen] = useState(false);
  const [transactions, setTransactions] = useState<PendingTransaction[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const { toast } = useToast();
  const queueRef = useRef<PendingTransaction[]>([]);

  // Listen for pending transactions
  useEffect(() => {
    const handler = (e: CustomEvent) => {
      if (e.detail?.isPending) {
        const newTx: PendingTransaction = {
          id: `pending-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          data: e.detail,
          status: 'pending',
          receivedAt: Date.now()
        };
        
        setTransactions(prev => {
          // Avoid duplicates based on postedAt and text if possible, but ID is random
          const exists = prev.some(t => t.data.postedAt === newTx.data.postedAt && t.data.text === newTx.data.text);
          if (exists) return prev;
          return [...prev, newTx];
        });
        
        setOpen(true);
      }
    };

    window.addEventListener('vfNotificationReceived', handler as EventListener);
    return () => {
      window.removeEventListener('vfNotificationReceived', handler as EventListener);
    };
  }, []);

  // Process queue automatically when transactions are added
  useEffect(() => {
    if (open && transactions.some(t => t.status === 'pending') && !isProcessing) {
      processQueue();
    }
  }, [open, transactions, isProcessing]);

  const processQueue = async () => {
    setIsProcessing(true);
    
    // Get next pending transaction
    const pendingIndex = transactions.findIndex(t => t.status === 'pending');
    if (pendingIndex === -1) {
      setIsProcessing(false);
      return;
    }

    const tx = transactions[pendingIndex];
    
    // Update status to processing
    updateTransactionStatus(tx.id, 'processing');

    // Simulate a small delay for better UX (so user sees the processing state)
    await new Promise(resolve => setTimeout(resolve, 800));

    try {
      // Remove isPending flag to prevent recursion loop if we re-emit (though we call logic directly)
      const { isPending, ...cleanData } = tx.data;
      
      // We pass a custom toast that doesn't show anything to avoid spamming toasts
      const silentToast = { toast: () => {} }; 
      
      await processVfNotification(cleanData, silentToast);
      
      updateTransactionStatus(tx.id, 'success');
    } catch (err) {
      console.error('Error processing pending transaction', err);
      updateTransactionStatus(tx.id, 'error', 'فشل التسجيل');
    }

    // Process next
    setIsProcessing(false);
  };

  const updateTransactionStatus = (id: string, status: PendingTransaction['status'], error?: string) => {
    setTransactions(prev => prev.map(t => 
      t.id === id ? { ...t, status, errorMessage: error } : t
    ));
  };

  const handleClose = () => {
    setOpen(false);
    // Clear completed transactions after closing
    setTimeout(() => {
      setTransactions(prev => prev.filter(t => t.status !== 'success'));
    }, 500);
  };

  const allCompleted = transactions.length > 0 && transactions.every(t => t.status === 'success' || t.status === 'error');

  if (!open && transactions.length === 0) return null;

  return (
    <Dialog open={open} onOpenChange={(val) => !val && allCompleted && handleClose()}>
      <DialogContent className="sm:max-w-md" onPointerDownOutside={(e) => !allCompleted && e.preventDefault()}>
        <DialogHeader>
          <DialogTitle className="text-center text-xl mb-2">معاملات معلقة</DialogTitle>
          <p className="text-center text-muted-foreground text-sm">
            تم استرجاع معاملات لم يتم تسجيلها أثناء عمل التطبيق في الخلفية
          </p>
        </DialogHeader>

        <ScrollArea className="max-h-[60vh] mt-4 pr-4">
          <div className="space-y-4">
            {transactions.map((tx) => (
              <div 
                key={tx.id} 
                className={`p-4 rounded-lg border flex items-center justify-between transition-colors duration-300 ${
                  tx.status === 'success' ? 'bg-green-50 border-green-200 dark:bg-green-900/20 dark:border-green-800' :
                  tx.status === 'error' ? 'bg-red-50 border-red-200 dark:bg-red-900/20 dark:border-red-800' :
                  'bg-card border-border'
                }`}
              >
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-bold text-lg">
                      {tx.data.amount ? `${Number(tx.data.amount).toLocaleString('en-US', { maximumFractionDigits: 0 })} ج.م` : 'معاملة غير معروفة'}
                    </span>
                    <span className="text-xs text-muted-foreground bg-secondary px-2 py-0.5 rounded-full">
                      {new Date(tx.data.postedAt || Date.now()).toLocaleTimeString('ar-EG')}
                    </span>
                  </div>
                  <p className="text-sm text-muted-foreground line-clamp-1">
                    {tx.data.text || tx.data.title || 'لا يوجد تفاصيل'}
                  </p>
                  {tx.errorMessage && (
                    <p className="text-xs text-red-500 mt-1">{tx.errorMessage}</p>
                  )}
                </div>

                <div className="mr-4 flex-shrink-0">
                  {tx.status === 'pending' && (
                    <div className="h-8 w-8 rounded-full bg-red-100 text-red-600 flex items-center justify-center animate-pulse">
                      <X className="h-5 w-5" />
                    </div>
                  )}
                  {tx.status === 'processing' && (
                    <div className="h-8 w-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center">
                      <Loader2 className="h-5 w-5 animate-spin" />
                    </div>
                  )}
                  {tx.status === 'success' && (
                    <div className="h-8 w-8 rounded-full bg-green-100 text-green-600 flex items-center justify-center animate-in zoom-in duration-300">
                      <Check className="h-5 w-5" />
                    </div>
                  )}
                  {tx.status === 'error' && (
                    <div className="h-8 w-8 rounded-full bg-red-100 text-red-600 flex items-center justify-center">
                      <X className="h-5 w-5" />
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </ScrollArea>

        <div className="mt-6 flex justify-center">
          <Button 
            onClick={handleClose} 
            disabled={!allCompleted}
            className={`w-full transition-all duration-300 ${allCompleted ? 'bg-green-600 hover:bg-green-700' : ''}`}
          >
            {allCompleted ? 'إغلاق وتابعة العمل' : 'جاري المعالجة...'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};
