
/**
 * Utility for parsing SMS messages to extract transaction details.
 * Consolidated from App.tsx and mobileTransactionHandler.ts
 */

export interface ParsedSms {
  amount: number;
  sender?: string;
  senderName?: string;
  reference?: string;
  type: 'receive' | 'transfer';
  originalText: string;
  balance?: number;
  date?: string;
}

export const normalizeMsisdnEgypt = (phone: string): string => {
  if (!phone) return '';
  let p = phone.replace(/[^\d+]/g, ''); // keep + and digits
  if (p.startsWith('0020')) p = p.substring(4);
  else if (p.startsWith('+20')) p = p.substring(3);
  else if (p.startsWith('20') && p.length > 10) p = p.substring(2);
  
  // Standardize 01xxxxxxxxx
  if (p.length === 10 && (p.startsWith('10') || p.startsWith('11') || p.startsWith('12') || p.startsWith('15'))) {
    p = '0' + p;
  }
  return p;
};

const parseInstaPaySms = (text: string): ParsedSms | null => {
  // Check if it matches InstaPay pattern
  if (!text.includes("Received EGP") || !text.includes("Available Balance")) {
    return null;
  }

  const cleanMessage = text.replace(/\n/g, " ").trim();

  // Regex definitions
  const amountRegex = /Received\s+EGP\s*(\d+(?:\.\d+)?)/i;
  const phoneRegex = /from\s+(\d{10,15})/i;
  const refRegex = /Ref:\s*(\d+)/i;
  const balanceRegex = /Available Balance:\s*(\d+(?:\.\d+)?)/i;
  const dateRegex = /^(.+?):\s*Received/i;

  // Extraction
  const amountMatch = cleanMessage.match(amountRegex);
  const phoneMatch = cleanMessage.match(phoneRegex);
  const refMatch = cleanMessage.match(refRegex);
  const balanceMatch = cleanMessage.match(balanceRegex);
  const dateMatch = cleanMessage.match(dateRegex);

  if (!amountMatch) return null; // Amount is mandatory

  return {
    amount: parseFloat(amountMatch[1]),
    sender: phoneMatch ? normalizeMsisdnEgypt(phoneMatch[1]) : undefined,
    senderName: undefined, // InstaPay messages in this format don't seem to have a name, just phone
    reference: refMatch ? refMatch[1] : undefined,
    type: 'receive',
    originalText: text,
    balance: balanceMatch ? parseFloat(balanceMatch[1]) : undefined,
    date: dateMatch ? dateMatch[1].trim() : undefined,
  };
};

export const parseSms = (text: string): ParsedSms => {
  const originalText = String(text || '');
  // Clean message: replace newlines and multiple spaces with single space
  const msg = originalText.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
  
  // Try InstaPay parsing first
  const instaPayResult = parseInstaPaySms(originalText);
  if (instaPayResult) {
    return instaPayResult;
  }
  
  let type: 'receive' | 'transfer' = 'receive';
  
  // Determine type
  if (/(?:تم\s*تحويل|تحويل\s*مبلغ|sent|transferred|خصم\s*مبلغ|قام\s*العميل|تم\s*دفع)/i.test(msg)) {
      // Stronger check: "Transfer" word can appear in receipts too (e.g. "You received a transfer")
      // If it mentions "from" or "من", it's likely a receipt unless it also mentions "to" or "إلى"
      const isFrom = /(?:من\s*رقم|from|من(?:\s*محفظة)?)/i.test(msg);
      const isTo = /(?:لرقم|to|إلى|الي|لعميل)/i.test(msg);
      
      if (isFrom && !isTo) {
          type = 'receive';
      } else {
          type = 'transfer';
      }
  } else if (/InstaPay/i.test(msg) || /Received\s*EGP/i.test(msg) || /You\s*have\s*received/i.test(msg) || /تم\s*استلام/i.test(msg)) {
      type = 'receive';
  }

  // 1. Extract Amount
  // أولوية: آخر رقم قبل كلمة "جنيه" في الرسالة (لتفادي التقاط رصيدك الحالي أو أرقام أخرى)
  let amount = 0;
  try {
    const allMatches = Array.from(
      msg.matchAll(/(\d+(?:[\.,]\d+)?)\s*جنيه/gi)
    );
    if (allMatches.length > 0) {
      const last = allMatches[allMatches.length - 1];
      amount = parseFloat(String(last[1]).replace(',', '.'));
    }
  } catch {
    amount = 0;
  }

  if (!amount || amount <= 0) {
    // User Regex: مبلغ\s+(\d+(?:\.\d+)?)
    // Supports "مبلغ 5" or "مبلغ 5.50"
    // Also support English "amount" or "EGP"
    const amountRegex = /(?:مبلغ|amount)\s+(\d+(?:\.\d+)?)/i;
    const amountMatch = msg.match(amountRegex);
    
    if (amountMatch) {
      amount = parseFloat(amountMatch[1]);
    } else {
      // Fallback إلى regex الأقدم
      const fallbackMatch = msg.match(/(?:تم\s*تحويل|تم\s*إ?ستلام\s*مبلغ|إ?ستلام\s*مبلغ|تحويل\s*مبلغ|received|transfer)\s*(?:of)?\s*(?:EGP)?\s*([0-9.,]+)/i);
      if (fallbackMatch) {
          amount = parseFloat(String(fallbackMatch[1]).replace(/,/g, ''));
      }
    }
  }

  // 2. Extract Sender/Receiver Phone
  let sender: string | undefined;

  if (type === 'transfer') {
    // For transfers, we look for "To" number
    // "لرقم", "الى رقم", "To"
    const toRegex = /(?:لرقم|إلى\s*رقم|رقم|to)\s*[:\-\s]*([\+\d]{10,14})/i;
    const match = msg.match(toRegex);
    if (match) sender = match[1];
  } else {
    // For receipts, we look for "From" number
    const fromRegex = /(?:من\s*رقم|from\s*number|from|رقم|الهاتف)\s*[:\-\s]*([\+\d]{10,14})/i;
    const match = msg.match(fromRegex);
    if (match) sender = match[1];
  }
  
  if (sender) sender = normalizeMsisdnEgypt(sender);

  // 3. Extract Sender Name
  // Updated to handle "باسمAhmed" (no space) and other variations
  let senderName: string | undefined;
  
  // Arabic "Registered as"
  const nameRegex = /(?:المسجل\s*ب(?:إ|ا)سم|مسجل\s*ب(?:إ|ا)سم|ب(?:إ|ا)سم|اسم(?:\s*العميل)?|العميل)\s*[:\-\s]*([^\n؛،:]+?)(?=\s*(?:رصيدك|رقم|حساب|عملية|transaction|ref|reference|بنجاح|لتقييم|\.|$))/i;
  const nameMatch = msg.match(nameRegex);
  
  if (nameMatch) {
    senderName = nameMatch[1].trim();
  } else {
    // English/Other "Registered as" or "from"
    const engNameMatch = msg.match(/(?:registered\s*(?:name|as)|from|sender|name)\s*[:\-]?\s*([A-Za-z][A-Za-z\s]+?)(?=\s*(?:balance|mobile|number|account|ref|transaction|$))/i);
    
    // InstaPay specific: "You have received ... from NAME"
    // Example: "You have received 1,000.00 EGP from AHMED MOHAMED"
    // Matches "from" followed by name until end or specific keywords
    if (!senderName && /InstaPay/i.test(msg)) {
        const ipMatch = msg.match(/from\s+([A-Za-z\s]+?)(?=\s*(?:balance|account|ref|transaction|$))/i);
        if (ipMatch) senderName = ipMatch[1].trim();
    }

    // e& money special case: "from Ahmed 010..."
    if (!senderName && /e&\s*money/i.test(msg)) {
         const eMoneyMatch = msg.match(/from\s+([A-Za-z\s]+?)\s+[0-9+]/i);
         if (eMoneyMatch) senderName = eMoneyMatch[1].trim();
    }
    if (!senderName && engNameMatch) senderName = engNameMatch[1].trim();
  }

  // 4. Extract Reference / Transaction ID
  // User Regex: رقم العملية\s+(\d+)
  let reference: string | undefined;
  
  const txnRegex = /(?:رقم\s*العملية|transaction\s*id)\s+(\d+)/i;
  const txnMatch = msg.match(txnRegex);
  
  if (txnMatch) {
    reference = txnMatch[1];
  } else {
    // Fallback
    let refMatch = msg.match(/(?:Ref|Reference|المرجع|عملي[ةه]|transaction\s*id|رقم\s*(?:العملي[ةه]|عملي[ةه]|التحويل|المرجع))\s*[:\-\s]*([0-9A-Za-z\-]+)/i);

    // نمط خاص لرسائل فودافون: رقم طويل يسبق "تابع كل مصروفاتك..."
    if (!refMatch) {
      const beforeFollow = msg.match(/(\d{6,})\s*(?=\.?\s*تابع\s+كل\s+مصروفاتك)/i);
      if (beforeFollow) {
        refMatch = [, beforeFollow[1]] as any;
      }
    }

    const fallbackRefMatch = !refMatch ? msg.match(/\b([A-Za-z0-9\-]{10,})\b/g) : null;
    reference = refMatch ? refMatch[1] : (fallbackRefMatch ? fallbackRefMatch[fallbackRefMatch.length-1] : undefined);
  }

  // 5. Extract Balance
  // User Regex: رصيدك الحالي\s+(\d+(?:\.\d+)?)
  let balance: number | undefined;
  const balanceRegex = /(?:رصيد(?:ك|(?:\s*محفظتك))\s*ال(?:حالي|حالى)|current\s*balance)\s+(\d+(?:\.\d+)?)/i;
  const balanceMatch = msg.match(balanceRegex);
  if (balanceMatch) {
    balance = parseFloat(balanceMatch[1]);
  }

  // 6. Extract Date
  // User Regex: تاريخ العملية\s+([0-9\-:\s]+)
  let date: string | undefined;
  const dateRegex = /(?:تاريخ\s*العملية|transaction\s*date)\s+([0-9\-:\s]+)/i;
  const dateMatch = msg.match(dateRegex);
  if (dateMatch) {
    date = dateMatch[1].trim();
  }

  return {
    amount,
    sender,
    senderName,
    reference,
    type,
    originalText,
    balance,
    date
  };
};
