import { db, auth } from '@/firebase';
import { doc, setDoc, getDoc, serverTimestamp, Timestamp, increment } from 'firebase/firestore';
import { isManualFirestoreHoldEffective } from './manualFirestoreSyncHold';

// واجهة بيانات الحدود اليومية والشهرية
interface WalletDailyLimits {
  walletId: string;
  // الحدود اليومية
  dailyTransferLimit: number;    // 60,000 جنيه
  dailyWithdrawLimit: number;    // 100,000 جنيه
  dailyTransferUsed: number;     // المستخدم من التحويل اليوم
  dailyWithdrawUsed: number;     // المستخدم من السحب اليوم
  lastDailyReset: Timestamp | null;
  
  // الحدود الشهرية
  monthlyTransferLimit: number;  // 200,000 جنيه
  monthlyWithdrawLimit: number;  // 200,000 جنيه
  monthlyTransferUsed: number;   // المستخدم من التحويل هذا الشهر
  monthlyWithdrawUsed: number;   // المستخدم من السحب هذا الشهر
  lastMonthlyReset: Timestamp | null;
  
  updatedAt: Timestamp;
}

// نتيجة التحقق من الحدود
interface LimitCheckResult {
  canPerform: boolean;
  message?: string;
  dailyRemaining?: number;
  monthlyRemaining?: number;
  limitType?: 'daily' | 'monthly';
}

// خدمة إدارة الحدود اليومية والشهرية للمحافظ
export const walletDailyLimitsService = {
  parseNum(val: any, def: number): number {
    if (typeof val === 'number' && Number.isFinite(val)) return val;
    if (typeof val === 'string') {
      const s = val.replace(/[^0-9.-]/g, '');
      const n = parseFloat(s);
      return Number.isFinite(n) ? n : def;
    }
    return def;
  },
  
  // الحصول على معرف اليوم الحالي
  getCurrentDayId(): string {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  },

  // تحديث قيم الحدود (اليومي/الشهري) للمحفظة
  async setLimits(
    walletId: string,
    newLimits: {
      dailyTransferLimit?: number;
      dailyWithdrawLimit?: number;
      monthlyTransferLimit?: number;
      monthlyWithdrawLimit?: number;
    }
  ): Promise<WalletDailyLimits | null> {
    try {
      const uid = auth.currentUser?.uid;
      if (uid && isManualFirestoreHoldEffective(uid)) {
        const k = `walletLimits_${uid}_${walletId}`;
        const rawPrev = this.readRawWalletLimitsLocal(walletId);
        const prev = this.readWalletLimitsFromLocalStorage(walletId);
        const merged: Record<string, unknown> = {
          dailyTransferLimit:
            newLimits.dailyTransferLimit !== undefined
              ? newLimits.dailyTransferLimit
              : prev?.dailyTransferLimit ?? 60000,
          dailyWithdrawLimit:
            newLimits.dailyWithdrawLimit !== undefined
              ? newLimits.dailyWithdrawLimit
              : prev?.dailyWithdrawLimit ?? 100000,
          monthlyTransferLimit:
            newLimits.monthlyTransferLimit !== undefined
              ? newLimits.monthlyTransferLimit
              : prev?.monthlyTransferLimit ?? 200000,
          monthlyWithdrawLimit:
            newLimits.monthlyWithdrawLimit !== undefined
              ? newLimits.monthlyWithdrawLimit
              : prev?.monthlyWithdrawLimit ?? 200000,
          dailyTransferUsed: prev?.dailyTransferUsed ?? 0,
          dailyWithdrawUsed: prev?.dailyWithdrawUsed ?? 0,
          monthlyTransferUsed: prev?.monthlyTransferUsed ?? 0,
          monthlyWithdrawUsed: prev?.monthlyWithdrawUsed ?? 0,
          periodDayKey: rawPrev?.periodDayKey ?? this.getCurrentDayId(),
          periodMonthKey: rawPrev?.periodMonthKey ?? this.getCurrentMonthId(),
        };
        try {
          localStorage.setItem(k, JSON.stringify(merged));
        } catch {
          /* ignore */
        }
        return this.readWalletLimitsFromLocalStorage(walletId);
      }

      const limitsRef = doc(db, 'walletLimits', walletId);
      const updateData: any = { updatedAt: serverTimestamp(), ownerId: auth.currentUser?.uid };

      if (newLimits.dailyTransferLimit !== undefined) {
        updateData.dailyTransferLimit = newLimits.dailyTransferLimit;
      }
      if (newLimits.dailyWithdrawLimit !== undefined) {
        updateData.dailyWithdrawLimit = newLimits.dailyWithdrawLimit;
      }
      if (newLimits.monthlyTransferLimit !== undefined) {
        updateData.monthlyTransferLimit = newLimits.monthlyTransferLimit;
      }
      if (newLimits.monthlyWithdrawLimit !== undefined) {
        updateData.monthlyWithdrawLimit = newLimits.monthlyWithdrawLimit;
      }

      await setDoc(limitsRef, updateData, { merge: true });
      return await this.getWalletLimits(walletId);
    } catch (error) {
      console.error('خطأ في تحديث حدود المحفظة:', error);
      return null;
    }
  },

  // الحصول على معرف الشهر الحالي
  getCurrentMonthId(): string {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  },

  // التحقق من ضرورة إعادة تعيين الحدود اليومية (بعد منتصف الليل)
  shouldResetDailyLimits(lastReset: Timestamp | null): boolean {
    if (!lastReset) return true;
    
    const now = new Date();
    const lastResetDate = lastReset.toDate();
    
    // التحقق من تغيير اليوم
    return (
      now.getDate() !== lastResetDate.getDate() ||
      now.getMonth() !== lastResetDate.getMonth() ||
      now.getFullYear() !== lastResetDate.getFullYear()
    );
  },

  // التحقق من ضرورة إعادة تعيين الحدود الشهرية (بداية شهر جديد — أي يوم بعد تغيّر الشهر/السنة)
  shouldResetMonthlyLimits(lastReset: Timestamp | null): boolean {
    if (!lastReset) return true;
    const now = new Date();
    const lastResetDate = lastReset.toDate();
    return (
      now.getMonth() !== lastResetDate.getMonth() ||
      now.getFullYear() !== lastResetDate.getFullYear()
    );
  },

  /**
   * محاذاة الاستخدام المحفوظ محلياً مع اليوم/الشهر الحالي (توقيت الجهاز = منتصف الليل المحلي).
   * يُخزَّن periodDayKey و periodMonthKey مع السجل.
   */
  applyCalendarResetsToLocalParsed(parsed: Record<string, unknown> | null): { out: Record<string, unknown>; changed: boolean } {
    if (!parsed || typeof parsed !== 'object') {
      return { out: {}, changed: false };
    }
    const today = this.getCurrentDayId();
    const thisMonth = this.getCurrentMonthId();
    const out = { ...parsed };
    let changed = false;
    const prevDay = typeof out.periodDayKey === 'string' ? out.periodDayKey : '';
    const prevMonth = typeof out.periodMonthKey === 'string' ? out.periodMonthKey : '';

    if (!prevDay) {
      out.periodDayKey = today;
      changed = true;
    } else if (prevDay !== today) {
      out.dailyTransferUsed = 0;
      out.dailyWithdrawUsed = 0;
      out.periodDayKey = today;
      changed = true;
    }

    if (!prevMonth) {
      out.periodMonthKey = thisMonth;
      changed = true;
    } else if (prevMonth !== thisMonth) {
      out.monthlyTransferUsed = 0;
      out.monthlyWithdrawUsed = 0;
      out.periodMonthKey = thisMonth;
      changed = true;
    }

    return { out, changed };
  },

  writeWalletLimitsLocalStorage(walletId: string, data: Record<string, unknown>) {
    try {
      const uid = auth.currentUser?.uid;
      if (!uid || !walletId) return;
      const k = `walletLimits_${uid}_${walletId}`;
      localStorage.setItem(k, JSON.stringify(data));
    } catch {
      /* ignore */
    }
  },

  /**
   * تمرير كل سجلات walletLimits المحلية عبر تصفير اليوم/الشهر (منتصف الليل المحلي، أوفلاين/تأجيل).
   * يُستدعى من المجدول الليلي عندما لا يتوفر جلب من Firestore.
   */
  syncAllLocalWalletLimitsCalendars(uid: string): number {
    let n = 0;
    try {
      if (!uid || typeof localStorage === 'undefined') return 0;
      const prefix = `walletLimits_${uid}_`;
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k || !k.startsWith(prefix)) continue;
        const walletId = k.slice(prefix.length);
        if (!walletId) continue;
        this.readRawWalletLimitsLocal(walletId);
        n++;
      }
    } catch {
      /* ignore */
    }
    return n;
  },

  // الحصول على حدود المحفظة أو إنشاؤها إذا لم تكن موجودة
  async getWalletLimits(walletId: string): Promise<WalletDailyLimits | null> {
    try {
      const limitsRef = doc(db, 'walletLimits', walletId);
      let limitsSnap;
      
      try {
        limitsSnap = await getDoc(limitsRef);
      } catch (e) {
        console.error('فشل في جلب حدود المحفظة (قد يكون بسبب مشاكل في الشبكة):', e);
        // في حالة فشل القراءة، لا نقوم بإنشاء سجل جديد لتجنب تصفير البيانات
        return null;
      }

      if (limitsSnap.exists()) {
        const data = limitsSnap.data();
        const normalized: WalletDailyLimits = {
          walletId,
          dailyTransferLimit: this.parseNum((data as any).dailyTransferLimit, 60000),
          dailyWithdrawLimit: this.parseNum((data as any).dailyWithdrawLimit, 100000),
          dailyTransferUsed: this.parseNum((data as any).dailyTransferUsed, 0),
          dailyWithdrawUsed: this.parseNum((data as any).dailyWithdrawUsed, 0),
          lastDailyReset: (data as any).lastDailyReset || null,
          monthlyTransferLimit: this.parseNum((data as any).monthlyTransferLimit, 200000),
          monthlyWithdrawLimit: this.parseNum((data as any).monthlyWithdrawLimit, 200000),
          monthlyTransferUsed: this.parseNum((data as any).monthlyTransferUsed, 0),
          monthlyWithdrawUsed: this.parseNum((data as any).monthlyWithdrawUsed, 0),
          lastMonthlyReset: (data as any).lastMonthlyReset || null,
          updatedAt: (data as any).updatedAt || Timestamp.now()
        };
        return normalized;
      }
      
      // إنشاء سجل جديد فقط إذا تأكدنا أن المستند غير موجود
      const newLimits: WalletDailyLimits = {
        walletId,
        dailyTransferLimit: 60000,
        dailyWithdrawLimit: 100000,
        dailyTransferUsed: 0,
        dailyWithdrawUsed: 0,
        lastDailyReset: null,
        monthlyTransferLimit: 200000,
        monthlyWithdrawLimit: 200000,
        monthlyTransferUsed: 0,
        monthlyWithdrawUsed: 0,
        lastMonthlyReset: null,
        updatedAt: Timestamp.now()
      };
      
      // حفظ السجل الجديد
      await setDoc(limitsRef, {
        dailyTransferLimit: 60000,
        dailyWithdrawLimit: 100000,
        dailyTransferUsed: 0,
        dailyWithdrawUsed: 0,
        lastDailyReset: null,
        monthlyTransferLimit: 200000,
        monthlyWithdrawLimit: 200000,
        monthlyTransferUsed: 0,
        monthlyWithdrawUsed: 0,
        lastMonthlyReset: null,
        updatedAt: serverTimestamp(),
        ownerId: auth.currentUser?.uid
      });
      
      return newLimits;
    } catch (error) {
      console.error('خطأ في الحصول على حدود المحفظة:', error);
      return null;
    }
  },

  // إعادة تعيين الحدود اليومية
  async resetDailyLimits(walletId: string): Promise<boolean> {
    try {
      const uid = auth.currentUser?.uid;
      if (uid && isManualFirestoreHoldEffective(uid)) {
        const raw = this.readRawWalletLimitsLocal(walletId) || {
          dailyTransferLimit: 60000,
          dailyWithdrawLimit: 100000,
          monthlyTransferLimit: 200000,
          monthlyWithdrawLimit: 200000,
          dailyTransferUsed: 0,
          dailyWithdrawUsed: 0,
          monthlyTransferUsed: 0,
          monthlyWithdrawUsed: 0,
        };
        raw.dailyTransferUsed = 0;
        raw.dailyWithdrawUsed = 0;
        raw.periodDayKey = this.getCurrentDayId();
        this.writeWalletLimitsLocalStorage(walletId, raw as Record<string, unknown>);
        console.log(`🔄 تم إعادة تعيين الحدود اليومية محلياً للمحفظة ${walletId}`);
        return true;
      }

      const limitsRef = doc(db, 'walletLimits', walletId);
      
      await setDoc(limitsRef, {
        dailyTransferUsed: 0,
        dailyWithdrawUsed: 0,
        lastDailyReset: serverTimestamp(),
        updatedAt: serverTimestamp(),
        ownerId: auth.currentUser?.uid
      }, { merge: true });
      
      console.log(`🔄 تم إعادة تعيين الحدود اليومية للمحفظة ${walletId}`);
      return true;
    } catch (error) {
      console.error('خطأ في إعادة تعيين الحدود اليومية:', error);
      return false;
    }
  },

  // إعادة تعيين الحدود الشهرية
  async resetMonthlyLimits(walletId: string): Promise<boolean> {
    try {
      const uid = auth.currentUser?.uid;
      if (uid && isManualFirestoreHoldEffective(uid)) {
        const raw = this.readRawWalletLimitsLocal(walletId) || {
          dailyTransferLimit: 60000,
          dailyWithdrawLimit: 100000,
          monthlyTransferLimit: 200000,
          monthlyWithdrawLimit: 200000,
          dailyTransferUsed: 0,
          dailyWithdrawUsed: 0,
          monthlyTransferUsed: 0,
          monthlyWithdrawUsed: 0,
        };
        raw.monthlyTransferUsed = 0;
        raw.monthlyWithdrawUsed = 0;
        raw.periodMonthKey = this.getCurrentMonthId();
        this.writeWalletLimitsLocalStorage(walletId, raw as Record<string, unknown>);
        console.log(`🔄 تم إعادة تعيين الحدود الشهرية محلياً للمحفظة ${walletId}`);
        return true;
      }

      const limitsRef = doc(db, 'walletLimits', walletId);
      
      await setDoc(limitsRef, {
        monthlyTransferUsed: 0,
        monthlyWithdrawUsed: 0,
        lastMonthlyReset: serverTimestamp(),
        updatedAt: serverTimestamp(),
        ownerId: auth.currentUser?.uid
      }, { merge: true });
      
      console.log(`🔄 تم إعادة تعيين الحدود الشهرية للمحفظة ${walletId}`);
      return true;
    } catch (error) {
      console.error('خطأ في إعادة تعيين الحدود الشهرية:', error);
      return false;
    }
  },

  // التحقق التلقائي وإعادة التعيين إذا لزم الأمر
  async autoResetLimitsIfNeeded(walletId: string): Promise<WalletDailyLimits | null> {
    try {
      const uid = auth.currentUser?.uid;
      if (uid && isManualFirestoreHoldEffective(uid)) {
        return this.readWalletLimitsFromLocalStorage(walletId);
      }

      const limits = await this.getWalletLimits(walletId);
      if (!limits) return null;
      
      let needsUpdate = false;
      
      // التحقق من الحدود اليومية
      if (this.shouldResetDailyLimits(limits.lastDailyReset)) {
        await this.resetDailyLimits(walletId);
        needsUpdate = true;
      }
      
      // التحقق من الحدود الشهرية
      if (this.shouldResetMonthlyLimits(limits.lastMonthlyReset)) {
        await this.resetMonthlyLimits(walletId);
        needsUpdate = true;
      }
      
      // إعادة قراءة البيانات إذا تم التحديث
      if (needsUpdate) {
        return await this.getWalletLimits(walletId);
      }
      
      return limits;
    } catch (error) {
      console.error('خطأ في التحقق التلقائي من الحدود:', error);
      return null;
    }
  },

  /** قراءة JSON الخام بعد تصفير اليوم/الشهر إن لزم، مع حفظ التعديلات */
  readRawWalletLimitsLocal(walletId: string): Record<string, unknown> | null {
    try {
      const uid = auth.currentUser?.uid;
      if (!uid || !walletId) return null;
      const k = `walletLimits_${uid}_${walletId}`;
      const s = localStorage.getItem(k);
      if (!s) return null;
      const parsed = JSON.parse(s);
      if (!parsed || typeof parsed !== 'object') return null;
      const { out, changed } = this.applyCalendarResetsToLocalParsed(parsed as Record<string, unknown>);
      if (changed) {
        try {
          localStorage.setItem(k, JSON.stringify(out));
        } catch {
          /* ignore */
        }
      }
      return out;
    } catch {
      return null;
    }
  },

  /** قراءة حدود المحفظة من التخزين المحلي (نفس مفتاح لوحة التحكم) */
  readWalletLimitsFromLocalStorage(walletId: string): WalletDailyLimits | null {
    try {
      const raw = this.readRawWalletLimitsLocal(walletId);
      if (!raw) return null;
      return {
        walletId,
        dailyTransferLimit: this.parseNum(raw.dailyTransferLimit, 60000),
        dailyWithdrawLimit: this.parseNum(raw.dailyWithdrawLimit, 100000),
        dailyTransferUsed: this.parseNum(raw.dailyTransferUsed, 0),
        dailyWithdrawUsed: this.parseNum(raw.dailyWithdrawUsed, 0),
        lastDailyReset: null,
        monthlyTransferLimit: this.parseNum(raw.monthlyTransferLimit, 200000),
        monthlyWithdrawLimit: this.parseNum(raw.monthlyWithdrawLimit, 200000),
        monthlyTransferUsed: this.parseNum(raw.monthlyTransferUsed, 0),
        monthlyWithdrawUsed: this.parseNum(raw.monthlyWithdrawUsed, 0),
        lastMonthlyReset: null,
        updatedAt: Timestamp.now()
      };
    } catch {
      return null;
    }
  },

  /** تحويل كائن الحدود المعروض في الواجهة إلى شكل موحّد للتحقق */
  normalizeUiLimitsSnapshot(walletId: string, ui: Record<string, unknown> | null | undefined): WalletDailyLimits | null {
    if (!ui || typeof ui !== 'object') return null;
    return {
      walletId,
      dailyTransferLimit: this.parseNum((ui as any).dailyTransferLimit, 60000),
      dailyWithdrawLimit: this.parseNum((ui as any).dailyWithdrawLimit, 100000),
      dailyTransferUsed: this.parseNum((ui as any).dailyTransferUsed, 0),
      dailyWithdrawUsed: this.parseNum((ui as any).dailyWithdrawUsed, 0),
      lastDailyReset: null,
      monthlyTransferLimit: this.parseNum((ui as any).monthlyTransferLimit, 200000),
      monthlyWithdrawLimit: this.parseNum((ui as any).monthlyWithdrawLimit, 200000),
      monthlyTransferUsed: this.parseNum((ui as any).monthlyTransferUsed, 0),
      monthlyWithdrawUsed: this.parseNum((ui as any).monthlyWithdrawUsed, 0),
      lastMonthlyReset: null,
      updatedAt: Timestamp.now()
    };
  },

  checkLimitsForOperation(limits: WalletDailyLimits, amount: number, type: 'transfer' | 'withdraw'): LimitCheckResult {
    if (type === 'transfer') {
      const dailyRemaining = Math.max(0, this.parseNum(limits.dailyTransferLimit, 60000) - this.parseNum(limits.dailyTransferUsed, 0));
      if (amount > dailyRemaining) {
        return {
          canPerform: false,
          message: `تجاوز الحد اليومي للتحويل. المتبقي: ${dailyRemaining.toLocaleString()} ج.م من أصل ${limits.dailyTransferLimit.toLocaleString()} ج.م`,
          dailyRemaining,
          limitType: 'daily'
        };
      }
      const monthlyRemaining = Math.max(0, this.parseNum(limits.monthlyTransferLimit, 200000) - this.parseNum(limits.monthlyTransferUsed, 0));
      if (amount > monthlyRemaining) {
        return {
          canPerform: false,
          message: `تجاوز الحد الشهري للتحويل. المتبقي: ${monthlyRemaining.toLocaleString()} ج.م من أصل ${limits.monthlyTransferLimit.toLocaleString()} ج.م`,
          monthlyRemaining,
          limitType: 'monthly'
        };
      }
      return {
        canPerform: true,
        dailyRemaining: Math.max(0, dailyRemaining - amount),
        monthlyRemaining: Math.max(0, monthlyRemaining - amount)
      };
    }
    if (type === 'withdraw') {
      const dailyRemaining = Math.max(0, this.parseNum(limits.dailyWithdrawLimit, 100000) - this.parseNum(limits.dailyWithdrawUsed, 0));
      if (amount > dailyRemaining) {
        return {
          canPerform: false,
          message: `تجاوز الحد اليومي للسحب. المتبقي: ${dailyRemaining.toLocaleString()} ج.م من أصل ${limits.dailyWithdrawLimit.toLocaleString()} ج.م`,
          dailyRemaining,
          limitType: 'daily'
        };
      }
      const monthlyRemaining = Math.max(0, this.parseNum(limits.monthlyWithdrawLimit, 200000) - this.parseNum(limits.monthlyWithdrawUsed, 0));
      if (amount > monthlyRemaining) {
        return {
          canPerform: false,
          message: `تجاوز الحد الشهري للسحب. المتبقي: ${monthlyRemaining.toLocaleString()} ج.م من أصل ${limits.monthlyWithdrawLimit.toLocaleString()} ج.م`,
          monthlyRemaining,
          limitType: 'monthly'
        };
      }
      return {
        canPerform: true,
        dailyRemaining: Math.max(0, dailyRemaining - amount),
        monthlyRemaining: Math.max(0, monthlyRemaining - amount)
      };
    }
    return { canPerform: false, message: 'نوع العملية غير صحيح' };
  },

  /**
   * التحقق من إمكانية إجراء العملية.
   * @param uiLimitsSnapshot حدود مطابقة لما يظهر في الواجهة — إن وُجدت تُستخدم بدل قراءة Firestore (تفادي تعارض السيرفر/الكاش).
   */
  /** حدود افتراضية للتحقق عند تعذّر السيرفر أو غياب التخزين المحلي (أوفلاين/شبكة). */
  defaultLimitsForWallet(walletId: string): WalletDailyLimits {
    return {
      walletId,
      dailyTransferLimit: 60000,
      dailyWithdrawLimit: 100000,
      dailyTransferUsed: 0,
      dailyWithdrawUsed: 0,
      lastDailyReset: null,
      monthlyTransferLimit: 200000,
      monthlyWithdrawLimit: 200000,
      monthlyTransferUsed: 0,
      monthlyWithdrawUsed: 0,
      lastMonthlyReset: null,
      updatedAt: Timestamp.now(),
    };
  },

  async canPerformOperation(
    walletId: string,
    amount: number,
    type: 'transfer' | 'withdraw',
    uiLimitsSnapshot?: Record<string, unknown> | null
  ): Promise<LimitCheckResult> {
    try {
      if (isManualFirestoreHoldEffective(auth.currentUser?.uid)) {
        const loc = this.readWalletLimitsFromLocalStorage(walletId);
        if (loc) {
          return this.checkLimitsForOperation(loc, amount, type);
        }
      }
      const fromUi = this.normalizeUiLimitsSnapshot(walletId, uiLimitsSnapshot);
      if (fromUi) {
        return this.checkLimitsForOperation(fromUi, amount, type);
      }
      const localCached = this.readWalletLimitsFromLocalStorage(walletId);
      if (localCached) {
        return this.checkLimitsForOperation(localCached, amount, type);
      }
      const limits = await this.autoResetLimitsIfNeeded(walletId);
      if (limits) {
        return this.checkLimitsForOperation(limits, amount, type);
      }
      const againLocal = this.readWalletLimitsFromLocalStorage(walletId);
      if (againLocal) {
        return this.checkLimitsForOperation(againLocal, amount, type);
      }
      return this.checkLimitsForOperation(this.defaultLimitsForWallet(walletId), amount, type);
    } catch (error) {
      console.error('خطأ في التحقق من إمكانية إجراء العملية:', error);
      try {
        const loc = this.readWalletLimitsFromLocalStorage(walletId);
        if (loc) {
          return this.checkLimitsForOperation(loc, amount, type);
        }
      } catch {
        /* ignore */
      }
      return this.checkLimitsForOperation(this.defaultLimitsForWallet(walletId), amount, type);
    }
  },

  /** تحديث الاستخدام في التخزين المحلي فقط (تأجيل المزامنة / أوفلاين) */
  updateUsageLocal(
    walletId: string,
    amount: number,
    type: 'transfer' | 'withdraw',
    skipCheck: boolean
  ): WalletDailyLimits | null {
    let raw = this.readRawWalletLimitsLocal(walletId);
    if (!raw) {
      raw = {
        dailyTransferLimit: 60000,
        dailyWithdrawLimit: 100000,
        monthlyTransferLimit: 200000,
        monthlyWithdrawLimit: 200000,
        dailyTransferUsed: 0,
        dailyWithdrawUsed: 0,
        monthlyTransferUsed: 0,
        monthlyWithdrawUsed: 0,
        periodDayKey: this.getCurrentDayId(),
        periodMonthKey: this.getCurrentMonthId(),
      };
      this.writeWalletLimitsLocalStorage(walletId, raw);
      raw = this.readRawWalletLimitsLocal(walletId);
      if (!raw) return null;
    }

    const limits: WalletDailyLimits = {
      walletId,
      dailyTransferLimit: this.parseNum(raw.dailyTransferLimit, 60000),
      dailyWithdrawLimit: this.parseNum(raw.dailyWithdrawLimit, 100000),
      dailyTransferUsed: this.parseNum(raw.dailyTransferUsed, 0),
      dailyWithdrawUsed: this.parseNum(raw.dailyWithdrawUsed, 0),
      lastDailyReset: null,
      monthlyTransferLimit: this.parseNum(raw.monthlyTransferLimit, 200000),
      monthlyWithdrawLimit: this.parseNum(raw.monthlyWithdrawLimit, 200000),
      monthlyTransferUsed: this.parseNum(raw.monthlyTransferUsed, 0),
      monthlyWithdrawUsed: this.parseNum(raw.monthlyWithdrawUsed, 0),
      lastMonthlyReset: null,
      updatedAt: Timestamp.now(),
    };

    if (!skipCheck) {
      const canPerform = this.checkLimitsForOperation(limits, amount, type);
      if (!canPerform.canPerform) {
        throw new Error(canPerform.message || 'لا يمكن إجراء العملية');
      }
    }

    const next: Record<string, unknown> = { ...raw };
    if (type === 'transfer') {
      next.dailyTransferUsed = this.parseNum(next.dailyTransferUsed, 0) + amount;
      next.monthlyTransferUsed = this.parseNum(next.monthlyTransferUsed, 0) + amount;
    } else if (type === 'withdraw') {
      next.dailyWithdrawUsed = this.parseNum(next.dailyWithdrawUsed, 0) + amount;
      next.monthlyWithdrawUsed = this.parseNum(next.monthlyWithdrawUsed, 0) + amount;
    }
    next.periodDayKey = next.periodDayKey ?? this.getCurrentDayId();
    next.periodMonthKey = next.periodMonthKey ?? this.getCurrentMonthId();
    this.writeWalletLimitsLocalStorage(walletId, next);
    return this.readWalletLimitsFromLocalStorage(walletId);
  },

  /** تراجع الاستخدام في التخزين المحلي فقط (أوفلاين / تأجيل مزامنة Firestore) */
  rollbackUsageLocal(
    walletId: string,
    amount: number,
    type: 'transfer' | 'withdraw',
    transactionDate?: Date | string
  ): WalletDailyLimits | null {
    let raw = this.readRawWalletLimitsLocal(walletId);
    if (!raw) {
      raw = {
        dailyTransferLimit: 60000,
        dailyWithdrawLimit: 100000,
        monthlyTransferLimit: 200000,
        monthlyWithdrawLimit: 200000,
        dailyTransferUsed: 0,
        dailyWithdrawUsed: 0,
        monthlyTransferUsed: 0,
        monthlyWithdrawUsed: 0,
        periodDayKey: this.getCurrentDayId(),
        periodMonthKey: this.getCurrentMonthId(),
      };
      this.writeWalletLimitsLocalStorage(walletId, raw);
      raw = this.readRawWalletLimitsLocal(walletId);
      if (!raw) return null;
    }

    const now = new Date();
    const txDate = transactionDate ? new Date(transactionDate) : now;
    const isSameDay =
      txDate.getDate() === now.getDate() &&
      txDate.getMonth() === now.getMonth() &&
      txDate.getFullYear() === now.getFullYear();
    const isSameMonth =
      txDate.getMonth() === now.getMonth() && txDate.getFullYear() === now.getFullYear();

    const next: Record<string, unknown> = { ...raw };
    if (type === 'transfer') {
      if (isSameDay) {
        next.dailyTransferUsed = Math.max(0, this.parseNum(next.dailyTransferUsed, 0) - amount);
      }
      if (isSameMonth) {
        next.monthlyTransferUsed = Math.max(0, this.parseNum(next.monthlyTransferUsed, 0) - amount);
      }
    } else {
      if (isSameDay) {
        next.dailyWithdrawUsed = Math.max(0, this.parseNum(next.dailyWithdrawUsed, 0) - amount);
      }
      if (isSameMonth) {
        next.monthlyWithdrawUsed = Math.max(0, this.parseNum(next.monthlyWithdrawUsed, 0) - amount);
      }
    }
    next.periodDayKey = next.periodDayKey ?? this.getCurrentDayId();
    next.periodMonthKey = next.periodMonthKey ?? this.getCurrentMonthId();
    this.writeWalletLimitsLocalStorage(walletId, next);
    return this.readWalletLimitsFromLocalStorage(walletId);
  },

  // تحديث الاستخدام بعد إجراء العملية
  async updateUsage(walletId: string, amount: number, type: 'transfer' | 'withdraw', skipCheck: boolean = false): Promise<WalletDailyLimits | null> {
    try {
      const uid = auth.currentUser?.uid;
      if (uid && isManualFirestoreHoldEffective(uid)) {
        return this.updateUsageLocal(walletId, amount, type, skipCheck);
      }

      // التحقق من إمكانية إجراء العملية أولاً (إلا إذا تم تخطي التحقق)
      if (!skipCheck) {
        const canPerform = await this.canPerformOperation(walletId, amount, type);
        if (!canPerform.canPerform) {
          throw new Error(canPerform.message || 'لا يمكن إجراء العملية');
        }
      }

      const limitsRef = doc(db, 'walletLimits', walletId);
      
      // تحديث الاستخدام بشكل ذري باستخدام increment
      const updateData: any = {
        updatedAt: serverTimestamp(),
        periodDayKey: this.getCurrentDayId(),
        periodMonthKey: this.getCurrentMonthId(),
      };

      if (type === 'transfer') {
        updateData.dailyTransferUsed = increment(amount);
        updateData.monthlyTransferUsed = increment(amount);
      } else if (type === 'withdraw') {
        updateData.dailyWithdrawUsed = increment(amount);
        updateData.monthlyWithdrawUsed = increment(amount);
      }

      await setDoc(limitsRef, updateData, { merge: true });

      // إعادة قراءة البيانات المحدثة
      return await this.getWalletLimits(walletId);
    } catch (error) {
      console.error('خطأ في تحديث استخدام المحفظة:', error);
      throw error;
    }
  },

  async rollbackUsage(walletId: string, amount: number, type: 'transfer' | 'withdraw', transactionDate?: Date | string): Promise<WalletDailyLimits | null> {
    const uid = auth.currentUser?.uid;
    if (uid && isManualFirestoreHoldEffective(uid)) {
      return this.rollbackUsageLocal(walletId, amount, type, transactionDate);
    }
    const offline = typeof navigator !== 'undefined' && !navigator.onLine;
    if (offline && uid) {
      const loc = this.rollbackUsageLocal(walletId, amount, type, transactionDate);
      if (loc) return loc;
    }

    try {
      const limitsRef = doc(db, 'walletLimits', walletId);
      const limits = await this.getWalletLimits(walletId);
      if (!limits) {
        if (uid) {
          const loc = this.rollbackUsageLocal(walletId, amount, type, transactionDate);
          if (loc) return loc;
        }
        throw new Error('لا يمكن العثور على بيانات حدود المحفظة');
      }

      const updateData: any = {
        updatedAt: serverTimestamp()
      };

      const now = new Date();
      const txDate = transactionDate ? new Date(transactionDate) : now;

      // التحقق مما إذا كانت المعاملة في نفس اليوم
      const isSameDay = txDate.getDate() === now.getDate() && 
                        txDate.getMonth() === now.getMonth() && 
                        txDate.getFullYear() === now.getFullYear();
      
      // التحقق مما إذا كانت المعاملة في نفس الشهر
      const isSameMonth = txDate.getMonth() === now.getMonth() && 
                          txDate.getFullYear() === now.getFullYear();

      if (type === 'transfer') {
        if (isSameDay) {
          updateData.dailyTransferUsed = Math.max(0, (limits.dailyTransferUsed || 0) - amount);
        }
        if (isSameMonth) {
          updateData.monthlyTransferUsed = Math.max(0, (limits.monthlyTransferUsed || 0) - amount);
        }
      } else {
        if (isSameDay) {
          updateData.dailyWithdrawUsed = Math.max(0, (limits.dailyWithdrawUsed || 0) - amount);
        }
        if (isSameMonth) {
          updateData.monthlyWithdrawUsed = Math.max(0, (limits.monthlyWithdrawUsed || 0) - amount);
        }
      }

      // إذا لم يكن هناك تحديث (لأن المعاملة قديمة جداً)، لا داعي للكتابة
      if (Object.keys(updateData).length <= 1) {
        return limits;
      }

      await setDoc(limitsRef, { ...updateData }, { merge: true });
      return await this.getWalletLimits(walletId);
    } catch (error) {
      console.error('خطأ في التراجع عن استخدام حدود المحفظة:', error);
      if (uid) {
        const loc = this.rollbackUsageLocal(walletId, amount, type, transactionDate);
        if (loc) return loc;
      }
      throw error;
    }
  },

  // الحصول على ملخص الحدود المتبقية
  calculateRemaining(limits: WalletDailyLimits): {
    dailyTransferRemaining: number;
    dailyWithdrawRemaining: number;
    monthlyTransferRemaining: number;
    monthlyWithdrawRemaining: number;
  } {
    return {
      dailyTransferRemaining: Math.max(0, limits.dailyTransferLimit - limits.dailyTransferUsed),
      dailyWithdrawRemaining: Math.max(0, limits.dailyWithdrawLimit - limits.dailyWithdrawUsed),
      monthlyTransferRemaining: Math.max(0, limits.monthlyTransferLimit - limits.monthlyTransferUsed),
      monthlyWithdrawRemaining: Math.max(0, limits.monthlyWithdrawLimit - limits.monthlyWithdrawUsed)
    };
  },

  // إعادة تعيين جميع الحدود يدوياً (للإدارة)
  async resetAllLimits(walletId: string): Promise<WalletDailyLimits | null> {
    try {
      const limitsRef = doc(db, 'walletLimits', walletId);
      
      await setDoc(limitsRef, {
        dailyTransferUsed: 0,
        dailyWithdrawUsed: 0,
        monthlyTransferUsed: 0,
        monthlyWithdrawUsed: 0,
        lastDailyReset: serverTimestamp(),
        lastMonthlyReset: serverTimestamp(),
        updatedAt: serverTimestamp(),
        ownerId: auth.currentUser?.uid
      }, { merge: true });

      console.log(`✅ تم إعادة تعيين جميع حدود المحفظة ${walletId}`);
      return await this.getWalletLimits(walletId);
    } catch (error) {
      console.error('خطأ في إعادة تعيين جميع الحدود:', error);
      return null;
    }
  }
};

export default walletDailyLimitsService;
