import { collection, query, where, limit, getDocs, doc, setDoc } from 'firebase/firestore';
import { db, auth } from '@/firebase';
import { transactionService, userDataService, merchantWalletService, recordAutoTransaction } from '@/integrations/firebase/services';
import { getUserSubscription, SubscriptionPlan } from '@/utils/subscriptionService';
import { showNativeNotification } from '@/utils/ussdDialer';
import { calculateCommission } from '@/utils/commissionCalculator';
import type { Transaction } from '@/integrations/firebase/types';
import { Preferences } from '@capacitor/preferences';

// الحمولة المتوقعة لإشعار معاملة قادم من الموبايل
export interface MobileTransactionNotificationPayload {
  // نوع المعاملة كما يأتي من الإشعار
  // يمكن أن يكون: 'withdraw' | 'transfer' أو مباشرة 'send' | 'receive'
  type: 'withdraw' | 'transfer' | 'send' | 'receive';
  amount: number;
  provider: Transaction['provider'];
  shopId: string; // معرف المتجر/المحل
  lineId: string; // معرف الخط المستخدم للمعاملة
  walletId?: string; // معرف المحفظة إن وُجد
  senderMsisdn?: string; // رقم المرسل
  receiverMsisdn?: string; // رقم المستلم
  senderName?: string; // اسم الراسل إن توفر من نص الرسالة
  reference?: string; // مرجع فريد للمعاملة (لمنع التكرار)
  createdBy: string; // معرف من أنشأ السجل (المستخدم/النظام)
  merchantUserId?: string; // معرف مستخدم التاجر المرتبط
  note?: string; // ملاحظات إضافية إن وُجدت
}

// تحويل نوع الإشعار إلى نوع المعاملة الداخلي المستخدم في النظام
const mapNotificationTypeToTxnType = (
  type: MobileTransactionNotificationPayload['type']
): Transaction['txnType'] => {
  if (type === 'withdraw' || type === 'receive') return 'receive';
  return 'send'; // 'transfer' أو 'send' -> إرسال
};

// فحص عدم التكرار بناءً على المرجع إن وُجد
const findExistingByReference = async (reference?: string): Promise<string | null> => {
  if (!reference) return null;
  const q = query(
    collection(db, 'transactions'),
    where('reference', '==', reference),
    limit(1)
  );
  const snap = await getDocs(q);
  if (!snap.empty) {
    return snap.docs[0].id;
  }
  return null;
};

const getSelectedWalletIdFromPreferencesOrLocalStorage = async (uid?: string): Promise<string | null> => {
  try {
    const pref = await Preferences.get({ key: 'selected_wallet_id' });
    const v = String(pref?.value || '').trim();
    if (v) return v;
  } catch {}
  return findSelectedWalletId(uid || auth.currentUser?.uid || '') || null;
};

const resolveWalletIdByMsisdn = async (msisdn?: string): Promise<string | null> => {
  try {
    const num = String(msisdn || '').trim();
    if (!num) return null;
    const w = await merchantWalletService.getByMsisdn(num);
    return (w as any)?.id || null;
  } catch { return null; }
};

// الدالة الرئيسية: معالجة إشعار معاملة قادم من الموبايل بنفس منطق الموقع
export const processMobileTransactionNotification = async (
  payload: MobileTransactionNotificationPayload
): Promise<{ id: string; duplicate: boolean }> => {
  // تحقق الحد الأدنى من البيانات
  if (!payload || !payload.shopId || !payload.lineId || !payload.provider) {
    throw new Error('بيانات الإشعار غير مكتملة: يجب توفير shopId و lineId و provider');
  }

  // Check for Zero plan restriction - REMOVED per request
  // try {
  //   const subscription = await getUserSubscription(payload.createdBy);
  //   if (subscription?.planType === SubscriptionPlan.ZERO) {
  //     console.log('Skipping mobile transaction notification for Zero plan user');
  //     return { id: '', duplicate: true };
  //   }
  // } catch (e) {
  //   console.warn('Error checking subscription in processMobileTransactionNotification:', e);
  // }

  if (!payload.amount || payload.amount <= 0) {
    throw new Error('قيمة المبلغ في الإشعار غير صالحة');
  }

  // منع التكرار باستخدام المرجع إن وُجد
  const existingId = await findExistingByReference(payload.reference);
  if (existingId) {
    return { id: existingId, duplicate: true };
  }

  const txnType = mapNotificationTypeToTxnType(payload.type);

  // فضّل walletId القادم من الحمولة إن كان موجودًا، وإلا جرّب المطابقة برقم الخط/المحفظة ثم ارجع للمختار محليًا
  let effectiveWalletId = (payload.walletId && String(payload.walletId).trim())
    ? String(payload.walletId).trim()
    : '';
  if (!effectiveWalletId) {
    // حاول المطابقة باستخدام رقم محفظة التاجر المستقبل إن توفر
    let byMsisdn = await resolveWalletIdByMsisdn(payload.receiverMsisdn);
    // إن لم تُفلح، جرّب رقم المرسل (قد تُستخدم في بعض السيناريوهات)
    if (!byMsisdn) {
      byMsisdn = await resolveWalletIdByMsisdn(payload.senderMsisdn);
    }
    // إن لم تُفلح، وإذا كان lineId يبدو كرقم (MSISDN) فجرّب أيضًا
    if (!byMsisdn) {
      const maybeMsisdn = String(payload.lineId || '').replace(/\D/g, '');
      if (maybeMsisdn.length >= 10) {
        byMsisdn = await resolveWalletIdByMsisdn(maybeMsisdn);
      }
    }
    effectiveWalletId = byMsisdn || (await getSelectedWalletIdFromPreferencesOrLocalStorage(payload.createdBy)) || '';
  }
  if (!effectiveWalletId) {
    throw new Error('لم يتم تحديد المحفظة المرتبطة بالمعاملة');
  }

  try {
    const { transactionServiceExtra } = await import('@/integrations/firebase/services');
    const recent = await transactionServiceExtra.getMerchantTransactions(payload.createdBy, 50);
    const nowMs = Date.now();
    const last5 = (s: any) => String(s || '').replace(/\D/g, '').slice(-5);
    const targetLast5 = txnType === 'send' ? last5(payload.senderMsisdn || payload.lineId) : last5(payload.senderMsisdn);
    const provider = String(payload.provider || '').toLowerCase();
    for (const t of recent) {
      const tMs = (t as any)?.createdAt ? new Date((t as any).createdAt as any).getTime() : 0;
      if (Math.abs(nowMs - tMs) <= 10_000) {
        const amtEq = Number((t as any)?.amount || 0) === Number(payload.amount || 0);
        const provEq = String((t as any)?.provider || '').toLowerCase() === provider;
        const tLast5 = last5((t as any)?.senderMsisdn || (t as any)?.receiverMsisdn || (t as any)?.senderPhone || (t as any)?.receiverPhone);
        if (amtEq && provEq && tLast5 && targetLast5 && tLast5 === targetLast5) {
          return { id: String((t as any)?.id || ''), duplicate: true };
        }
      }
    }
  } catch {}

  // تجهيز بيانات المعاملة بما يتوافق مع Transaction وواجهة الإنشاء الحالية
  const transactionData: any = {
    shopId: payload.shopId,
    lineId: payload.lineId,
    merchantUserId: payload.merchantUserId || payload.createdBy,
    walletId: effectiveWalletId,
    provider: payload.provider,
    txnType,
    originType: payload.type,
    amount: payload.amount,
    fee: undefined,
    commission: undefined,
    profit: 0, // سيتم حسابه داخل الخدمة
    reference: payload.reference,
    senderMsisdn: payload.senderMsisdn,
    receiverMsisdn: payload.receiverMsisdn,
    note: payload.note,
    status: 'confirmed',
    createdBy: payload.createdBy,
    // احفظ وقت التنفيذ الفعلي
    createdAt: (payload as any).createdAt || new Date(),
    confirmedAt: new Date()
  };

  // استخدام نفس مسار الموقع: transactionService.create يحسب العمولة/الربح ويُحدث الاستخدام والتقارير
  const id = await transactionService.create(transactionData as any);

  // تحديث أرصدة المستخدم (النقدية والمحفظة) للمعاملات الصادرة (Send/Transfer)
  // المعاملات الواردة (Receive/Withdraw) يتم تحديث أرصدتها عادة عبر recordAutoTransaction أو آليات أخرى،
  // ولكن هنا نعالج التحديث المباشر للنوع 'send' كما طلب المستخدم
  if (txnType === 'send') {
    try {
      const { calculateCommission } = await import('@/utils/commissionCalculator');
      const commission = calculateCommission(payload.amount, 'send');
      const userId = payload.merchantUserId || payload.createdBy;
      const feeVal = payload.fee || 0;
      
      const userData = await userDataService.getUserData(userId);
      const balances: Record<string, number> = { ...((userData as any)?.walletBalances || {}) };
      
      // 1. خصم المبلغ + المصاريف من المحفظة
      const prevWallet = Number(balances[effectiveWalletId] || 0);
      const newWalletBalance = prevWallet - (payload.amount + feeVal);
      balances[effectiveWalletId] = newWalletBalance;
      
      // 2. إضافة المبلغ (+ العمولة) للنقدية
      // الافتراض: العميل دفع لي كاش (المبلغ + العمولة)، وأنا حولت له رصيد (المبلغ).
      // لذا النقدية تزيد بالمبلغ + العمولة.
      const prevCash = Number((userData as any)?.cashBalance || 0);
      const newCashBalance = Math.round(prevCash + payload.amount + commission);
      
      await userDataService.updateUserData(userId, { 
        walletBalances: balances, 
        cashBalance: newCashBalance,
        lastUpdated: new Date().toISOString() 
      });

      // تحديث dashboardData لضمان تزامن الموقع (Desktop Dashboard) لحظياً
      if (payload.shopId) {
        try {
          const dashboardRef = doc(db, 'dashboardData', payload.shopId);
          await setDoc(dashboardRef, {
            cashBalance: newCashBalance,
            walletBalances: balances,
            lastUpdated: new Date().toISOString()
          }, { merge: true });
        } catch (dErr) {
          console.warn('⚠️ فشل تحديث dashboardData:', dErr);
        }
      }

      // تحديث حدود المحفظة (Transfer Usage)
      const { walletDailyLimitsService } = await import('@/utils/walletDailyLimitsService');
      // نمرر true لتخطي التحقق لأن المعاملة تمت بالفعل
      await walletDailyLimitsService.updateUsage(effectiveWalletId, payload.amount, 'transfer', true);

    } catch (err) {
      console.warn('⚠️ فشل تحديث الأرصدة لمعاملة التحويل:', err);
    }
  } else {
    // معالجة السحب (Withdraw) أو الاستلام (Receive)
    try {
      const { calculateCommission } = await import('@/utils/commissionCalculator');
      // نفترض أن نوع العمولة 'receive' ينطبق على السحب والاستلام
      const commission = calculateCommission(payload.amount, 'receive');
      const userId = payload.merchantUserId || payload.createdBy;
      
      const userData = await userDataService.getUserData(userId);
      const balances: Record<string, number> = { ...((userData as any)?.walletBalances || {}) };
      
      // 1. زيادة رصيد المحفظة (استلام أموال)
      const prevWallet = Number(balances[effectiveWalletId] || 0);
      const newWalletBalance = prevWallet + payload.amount;
      balances[effectiveWalletId] = newWalletBalance;
      
      // 2. خصم المبلغ من النقدية (دفع كاش للعميل)
      // المعادلة: الكاش الجديد = الكاش القديم - المبلغ + العمولة
      // (لأننا نعطي العميل المبلغ مخصوماً منه العمولة، أو نأخذ العمولة من المبلغ)
      const prevCash = Number((userData as any)?.cashBalance || 0);
      const newCashBalance = Math.round(prevCash - payload.amount + commission);
      
      await userDataService.updateUserData(userId, {  
        walletBalances: balances, 
        cashBalance: newCashBalance,
        lastUpdated: new Date().toISOString() 
      });

      // تحديث dashboardData لضمان تزامن الموقع
      if (payload.shopId) {
        try {
          const dashboardRef = doc(db, 'dashboardData', payload.shopId);
          await setDoc(dashboardRef, {
            cashBalance: newCashBalance,
            walletBalances: balances,
            lastUpdated: new Date().toISOString()
          }, { merge: true });
        } catch (dErr) {
          console.warn('⚠️ فشل تحديث dashboardData:', dErr);
        }
      }

      // تحديث حدود المحفظة (Withdraw Usage) - فقط إذا كان النوع withdraw
      if (payload.type === 'withdraw') {
         const { walletDailyLimitsService } = await import('@/utils/walletDailyLimitsService');
         await walletDailyLimitsService.updateUsage(effectiveWalletId, payload.amount, 'withdraw', true);
      }

    } catch (err) {
      console.warn('⚠️ فشل تحديث الأرصدة لمعاملة السحب/الاستلام:', err);
    }
  }

  // إظهار إشعار على الهاتف عند تسجيل المعاملة
  try {
    const title = 'معاملة جوال جديدة';
    const msg = `نوع: ${payload.type} | المبلغ: ${payload.amount} | المزود: ${payload.provider}`;
    await showNativeNotification(msg, title);
  } catch (e) {
    // تجاهل أي أخطاء متعلقة بالإشعارات الأصلية حتى لا تؤثر على المسار الرئيسي
    console.warn('تعذر إظهار إشعار الهاتف:', e);
  }
  
  // حفظ إيصال للمستخدم في مجموعة userTransactions لعرضه في صفحة المعاملات
  try {
    const userId = payload.merchantUserId || payload.createdBy;
    if (userId) {
      // نوع الإيصال المرئي: سحب إذا كانت txnType = receive، وإلا إرسال
      const visibleType = txnType === 'receive' ? 'withdraw' : 'send';
      const commission = calculateCommission(payload.amount, txnType);

      await userDataService.saveUserTransaction(userId, {
        type: visibleType,
        amount: payload.amount,
        commission,
        status: 'completed',
        createdAt: new Date(),
        senderMsisdn: payload.senderMsisdn,
        receiverMsisdn: payload.receiverMsisdn,
        senderName: payload.senderName,
        walletId: effectiveWalletId,
        lineId: payload.lineId,
        provider: payload.provider,
        note: payload.note,
        transactionId: id // ربط الإيصال بالمعاملة الأصلية لسهولة التتبع/الحذف
      });
    } else {
      console.warn('⚠️ تعذر حفظ إيصال المستخدم: لا يوجد userId (merchantUserId أو createdBy) في الحمولة.');
    }
  } catch (err) {
    console.warn('⚠️ فشل حفظ إيصال المستخدم في userTransactions من إشعار الموبايل:', err);
  }

  return { id, duplicate: false };
};

// ————————————————————————————————————————————————————————————————
// توحيد صيغة رقم الهاتف المصري (010/011/012/015) وإزالة +20/20
const normalizeMsisdnEgypt = (raw?: string): string => {
  try {
    const s = String(raw || '').replace(/[^0-9+]/g, '');
    if (!s) return '';
    if (s.startsWith('+20')) {
      const rest = s.slice(3);
      return rest.startsWith('1') ? '0' + rest : rest;
    }
    if (s.startsWith('0020')) {
      const rest = s.slice(4);
      return rest.startsWith('1') ? '0' + rest : rest;
    }
    if (s.startsWith('20')) {
      const rest = s.slice(2);
      return rest.startsWith('1') ? '0' + rest : rest;
    }
    if (s.startsWith('0')) return s;
    if (/^(10|11|12|15)/.test(s)) return '0' + s;
    return s;
  } catch { return ''; }
};

// البحث عن محفظة مطابقة لرقم الشريحة عبر التخزين المحلي ثم البعيد مع توسيع المطابقة
const findWalletBySim = async (simNumber: string, userId?: string): Promise<{ walletId: string; msisdn: string } | null> => {
  try {
    const normSim = normalizeMsisdnEgypt(simNumber);
    const uid = userId || auth.currentUser?.uid || 'default';
    const walletsKey = `wallets_${uid}`;
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(walletsKey) : null;
    const list: any[] = raw ? JSON.parse(raw!) : [];
    const toDigits = (x: string) => String(x || '').replace(/\D/g, '');
    const locals: Array<{ walletId: string; msisdn: string; isDefault?: boolean }> = Array.isArray(list)
      ? list.map(w => ({ walletId: String(w?.id || ''), msisdn: normalizeMsisdnEgypt(String(w?.phone || w?.msisdn || '')), isDefault: !!w?.isDefault }))
          .filter(x => x.walletId && x.msisdn)
      : [];

    const exactLocal = locals.filter(w => w.msisdn === normSim);
    if (exactLocal.length === 1) return { walletId: exactLocal[0].walletId, msisdn: exactLocal[0].msisdn };
    if (exactLocal.length > 1) {
      const def = exactLocal.find(w => w.isDefault);
      return { walletId: (def?.walletId || exactLocal[0].walletId), msisdn: (def?.msisdn || exactLocal[0].msisdn) };
    }

    const tail5Local = locals.filter(w => toDigits(w.msisdn).slice(-7) === toDigits(normSim).slice(-7));
    if (tail5Local.length > 0) {
      const def = tail5Local.find(w => w.isDefault);
      return { walletId: (def?.walletId || tail5Local[0].walletId), msisdn: (def?.msisdn || tail5Local[0].msisdn) };
    }

    const remote = await merchantWalletService.getByMerchantId(uid);
    const rems: Array<{ walletId: string; msisdn: string; isDefault?: boolean }> = (remote || [])
      .map((w: any) => ({ walletId: String(w?.id || ''), msisdn: normalizeMsisdnEgypt(String(w?.msisdn || '')), isDefault: !!w?.isDefault }))
      .filter(x => x.walletId && x.msisdn);

    const exactRemote = rems.filter(w => w.msisdn === normSim);
    if (exactRemote.length === 1) return { walletId: exactRemote[0].walletId, msisdn: exactRemote[0].msisdn };
    if (exactRemote.length > 1) {
      const def = exactRemote.find(w => w.isDefault);
      return { walletId: (def?.walletId || exactRemote[0].walletId), msisdn: (def?.msisdn || exactRemote[0].msisdn) };
    }

    const tail5Remote = rems.filter(w => toDigits(w.msisdn).slice(-7) === toDigits(normSim).slice(-7));
    if (tail5Remote.length > 0) {
      const def = tail5Remote.find(w => w.isDefault);
      return { walletId: (def?.walletId || tail5Remote[0].walletId), msisdn: (def?.msisdn || tail5Remote[0].msisdn) };
    }

    return null;
  } catch { return null; }
};

export const identifyWalletBySim = async (simNumbers: string[] = [], userId?: string): Promise<{ walletId: string; msisdn: string } | null> => {
  try {
    try { console.log('identifyWalletBySim → input', simNumbers); } catch {}
    const uid = userId || auth.currentUser?.uid || 'default';
    const sims = Array.isArray(simNumbers) ? simNumbers.map(s => normalizeMsisdnEgypt(s)).filter(s => !!s) : [];
    const walletsKey = `wallets_${uid}`;
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(walletsKey) : null;
    const list: any[] = raw ? JSON.parse(raw!) : [];
    const toDigits = (x: string) => String(x || '').replace(/\D/g, '');
    const locals: Array<{ walletId: string; msisdn: string; isDefault?: boolean }> = Array.isArray(list)
      ? list.map(w => ({ walletId: String(w?.id || ''), msisdn: normalizeMsisdnEgypt(String(w?.phone || w?.msisdn || '')), isDefault: !!w?.isDefault }))
          .filter(x => x.walletId && x.msisdn)
      : [];

    // Optimize: Check local wallets FIRST before waiting for remote fetch
    const matchedLocal = new Map<string, { msisdn: string; isDefault: boolean }>();
    for (const sim of sims) {
      const simDigits = toDigits(sim);
      for (const w of locals) {
        const wDigits = toDigits(w.msisdn);
        if (w.msisdn === sim) { matchedLocal.set(w.walletId, { msisdn: w.msisdn, isDefault: !!w.isDefault }); continue; }
        if (wDigits.slice(-7) === simDigits.slice(-7)) { matchedLocal.set(w.walletId, { msisdn: w.msisdn, isDefault: !!w.isDefault }); continue; }
      }
    }
    if (matchedLocal.size > 0) {
       const matches = Array.from(matchedLocal.entries());
       const def = matches.find(([_, val]) => val.isDefault);
       const [walletId, val] = def || matches[0];
       return { walletId, msisdn: val.msisdn };
    }

    const remote = await merchantWalletService.getByMerchantId(uid);
    const rems: Array<{ walletId: string; msisdn: string; isDefault?: boolean }> = (remote || [])
      .map((w: any) => ({ walletId: String(w?.id || ''), msisdn: normalizeMsisdnEgypt(String(w?.msisdn || '')), isDefault: !!w?.isDefault }))
      .filter(x => x.walletId && x.msisdn);
    const all = [...locals, ...rems];
    const matched = new Map<string, { msisdn: string; isDefault: boolean }>();
    for (const sim of sims) {
      const simDigits = toDigits(sim);
      for (const w of all) {
        const wDigits = toDigits(w.msisdn);
        if (w.msisdn === sim) { matched.set(w.walletId, { msisdn: w.msisdn, isDefault: !!w.isDefault }); continue; }
        if (wDigits.slice(-7) === simDigits.slice(-7)) { matched.set(w.walletId, { msisdn: w.msisdn, isDefault: !!w.isDefault }); continue; }
      }
    }
    try { console.log('identifyWalletBySim → matched size', matched.size); } catch {}
    if (matched.size > 0) {
      const matches = Array.from(matched.entries());
      const def = matches.find(([_, val]) => val.isDefault);
      const [walletId, val] = def || matches[0];
      try { console.log('identifyWalletBySim → selected match', { walletId, msisdn: val.msisdn }); } catch {}
      return { walletId, msisdn: val.msisdn };
    }
    try { console.warn('identifyWalletBySim → no unique match'); } catch {}
    return null;
  } catch { return null; }
};

// كشف المحفظة من قائمة الشرائح باستخدام قواعد المطابقة (كاملة/آخر 10/آخر 7)
export async function detectWalletFromSim(
  simList: string[],
  wallets: Array<{ id: string; msisdn?: string; phone?: string; isDefault?: boolean }>
): Promise<{ walletId: string; msisdn: string } | null> {
  try {
    const fix = (n: string) => normalizeMsisdnEgypt(String(n || ''));
    const candidates = (wallets || [])
      .map(w => ({ walletId: String(w.id || ''), msisdn: fix(String(w.msisdn || w.phone || '')), isDefault: !!w.isDefault }))
      .filter(x => x.walletId && x.msisdn);
    const toDigits = (x: string) => String(x || '').replace(/\D/g, '');
    for (const sim of (simList || [])) {
      const s = fix(sim);
      const sDigits = toDigits(s);
      
      const exacts = candidates.filter(w => w.msisdn === s);
      if (exacts.length > 0) {
         const def = exacts.find(w => w.isDefault);
         const w = def || exacts[0];
         return { walletId: w.walletId, msisdn: w.msisdn };
      }

      const tail5s = candidates.filter(w => toDigits(w.msisdn).slice(-7) === sDigits.slice(-7));
      if (tail5s.length > 0) {
         const def = tail5s.find(w => w.isDefault);
         const w = def || tail5s[0];
         return { walletId: w.walletId, msisdn: w.msisdn };
      }
    }
    return null;
  } catch {
    return null;
  }
}

export async function resolveWalletBySimOrSlot(opts: { simNumbers?: string[]; subId?: number; slotIndex?: number; userId?: string }): Promise<{ walletId: string; msisdn: string } | null> {
  try {
    const uid = opts.userId || auth.currentUser?.uid || 'default';

    // Priority: Check Profile Settings for SIM 1 / SIM 2 specific numbers based on slot
    // This ensures that if the message arrives on a specific slot, we respect the user's profile configuration
    if (opts.slotIndex !== undefined && opts.slotIndex !== null && opts.slotIndex >= 0) {
      let targetSimNumber = '';
      try {
         if (opts.slotIndex === 0) {
            targetSimNumber = localStorage.getItem(`sim1Number_${uid}`) || localStorage.getItem('sim1Number') || '';
         } else if (opts.slotIndex === 1) {
            targetSimNumber = localStorage.getItem(`sim2Number_${uid}`) || localStorage.getItem('sim2Number') || '';
         }
      } catch {}
      
      if (targetSimNumber) {
        const byStaticSim = await identifyWalletBySim([targetSimNumber], uid);
        if (byStaticSim) return byStaticSim;
      }
    }

    const sims = Array.isArray(opts.simNumbers) ? opts.simNumbers : [];
    const bySim = await identifyWalletBySim(sims, uid);
    if (bySim) return bySim;
    
    const key = `simWalletBindings_${uid}`;
    let map: any = {};
    try { const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(key) : null; map = raw ? JSON.parse(raw!) : {}; } catch {}
    const subKey = String(opts.subId ?? '');
    const slotKey = String(opts.slotIndex ?? '');
    if (subKey && map[subKey] && map[subKey].walletId) return { walletId: map[subKey].walletId, msisdn: String(map[subKey].msisdn || '') };
    if (slotKey && map[`slot_${slotKey}`] && map[`slot_${slotKey}`].walletId) return { walletId: map[`slot_${slotKey}`].walletId, msisdn: String(map[`slot_${slotKey}`].msisdn || '') };

    return null;
  } catch { return null; }
}

export function bindSlotWalletMapping(opts: { userId?: string; subId?: number; slotIndex?: number; walletId: string; msisdn?: string }) {
  try {
    const uid = opts.userId || auth.currentUser?.uid || 'default';
    const key = `simWalletBindings_${uid}`;
    let map: any = {};
    try { const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(key) : null; map = raw ? JSON.parse(raw!) : {}; } catch {}
    if (opts.subId != null) { map[String(opts.subId)] = { walletId: opts.walletId, msisdn: opts.msisdn || '' }; }
    if (opts.slotIndex != null) { map[`slot_${String(opts.slotIndex)}`] = { walletId: opts.walletId, msisdn: opts.msisdn || '' }; }
    try { if (typeof localStorage !== 'undefined') localStorage.setItem(key, JSON.stringify(map)); } catch {}
  } catch {}
}

// استخراج بيانات الرسالة (المبلغ/رقم المرسل/الاسم) من نص فودافون كاش أو اتصالات كاش أو انستا باي
const extractVfSmsData = (text: string): { amount: number; senderNumber?: string; senderName?: string; provider?: 'vodafone_cash' | 'etisalat_cash' | 'instapay' } => {
  try {
    const msg = String(text || '');
    // Arabic Amount Support (VF Cash / Etisalat Cash)
    // نأخذ آخر رقم يسبق كلمة "جنيه" في الرسالة باعتباره المبلغ الصحيح
    let amount = 0;
    try {
      const allMatches = Array.from(
        msg.matchAll(/(\d+(?:[\.,]\d+)?)\s*جنيه/gi)
      );
      if (allMatches.length > 0) {
        const last = allMatches[allMatches.length - 1];
        amount = parseFloat(String(last[1]).replace(',', '.'));
      }
    } catch {
      amount = 0;
    }
    if (!amount || amount <= 0) {
      const amountMatch = msg.match(/(?:تم\s*تحويل)\s+(\d+(?:[\.,]\d+)?)\s+جنيه/i) || msg.match(/(?:تم\s*إ?ستلام\s*مبلغ|إ?ستلام\s*مبلغ|تم\s*تحويل(?:\s*مبلغ)?|تحويل\s*مبلغ)\s*([0-9]+(?:[\.,][0-9]{1,2})?)/i);
      amount = amountMatch ? parseFloat(String(amountMatch[1] || amountMatch[2]).replace(',', '.')) : 0;
    }
    
    // English Amount Support (VF Cash / InstaPay / Etisalat)
    if (!amount || amount <= 0) {
      // Matches: "Received EGP 1000", "received 1000 EGP", "transfer of EGP 1000", "Received EGP5"
      const enAmt = msg.match(/(?:received|transfer)\s*(?:of)?\s*(?:EGP)?\s*([0-9.,]+)\s*(?:EGP)?/i);
      if (enAmt) { 
        // Remove commas (thousands separator) and parse
        amount = parseFloat(String(enAmt[1]).replace(/,/g, '')); 
      }
    }

    // Sanity check
    if (amount <= 0) {
       // Fallback for any bare number if context suggests money (dangerous, but useful for some short SMS)
       // Only if we found "EGP" or "ج.م" or "جنيه" elsewhere but failed to match next to number
       // Skipping for now to avoid false positives
    }

    const senderMatch = msg.match(/(?:من\s*رقم|رقم(?:\s*العميل)?|الهاتف)\s*[:\-\s]*([\+\d]{10,14})|from\s*[:\-]?\s*([0-9+]{10,14})/i);
    let senderNumber = senderMatch ? normalizeMsisdnEgypt(senderMatch[1] || senderMatch[2]) : undefined;
    
    // InstaPay Sender Support
    if (!senderNumber) {
        // Updated Regex to handle "from 00201..." and generic "source: ..."
        // Allow optional words between 'from' and the number (e.g. "from Wallet Number ...")
        const enSender = msg.match(/from\s+(?:[^0-9\n:]{0,30})\s*([0-9+]{10,14})/i);
        if (enSender) { senderNumber = normalizeMsisdnEgypt(enSender[1]); }
        
        const enSenderGeneric = msg.match(/(?:from|sender|source)\s*[:\-\s]*([0-9+]{10,14})/i);
        if (enSenderGeneric && !senderNumber) { senderNumber = normalizeMsisdnEgypt(enSenderGeneric[1]); }
    }

    // تحديث regex لاستخراج الاسم لدعم e& money واتصالات كاش
    // Updated to handle cases where there is no space after 'باسم' like 'باسمAhmed'
    const arabicNameMatch = msg.match(/(?:المسجل\s*ب(?:إ|ا)سم|مسجل\s*ب(?:إ|ا)سم|ب(?:إ|ا)سم|اسم(?:\s*العميل)?|العميل)\s*[:\-\s]*([^\n؛،:]+?)(?=\s*(?:رصيدك|رقم|حساب|عملية|transaction|ref|reference|بنجاح|لتقييم|\.|$))/i);
    const englishNameMatch = msg.match(/(?:registered\s*(?:name|as)|from|sender|name)\s*[:\-]?\s*([A-Za-z][A-Za-z\s]+?)(?=\s*(?:balance|mobile|number|account|ref|transaction|$))/i);
    let senderName = arabicNameMatch ? String(arabicNameMatch[1]).trim() : (englishNameMatch ? String(englishNameMatch[1]).trim() : undefined);

    // Special case for e& money where name might be just before the number or after "from"
    if (!senderName && /e&\s*money/i.test(msg)) {
       // Try to capture name between "from" and "number"
       // Example: "received 5 EGP from Ahmed 011..."
       const eMoneyMatch = msg.match(/from\s+([A-Za-z\s]+?)\s+[0-9+]/i);
       if (eMoneyMatch) senderName = eMoneyMatch[1].trim();
    }

    let provider: 'vodafone_cash' | 'etisalat_cash' | 'instapay' = 'vodafone_cash';
    if (/Received\s*EGP/i.test(msg) || /instapay/i.test(msg)) {
      provider = 'instapay';
    } else if (/etisalat|e&|اتصالات/i.test(msg)) {
      provider = 'etisalat_cash';
    }

    return { amount, senderNumber, senderName, provider };
  } catch { return { amount: 0 }; }
};

// إنشاء عملية سحب تلقائيًا من رسالة فودافون كاش أو اتصالات مع تحديد المحفظة برقم الشريحة
export const processVfSmsAutoWithdraw = async (data: {
  text: string;
  sender?: string;
  simNumber?: string;
  activeSimMsisdns?: string[];
  shopId: string;
  userId: string;
}): Promise<{ id: string; duplicate: boolean }> => {
  try { console.log('processVfSmsAutoWithdraw → payload', { simNumber: data.simNumber, activeSimMsisdns: data.activeSimMsisdns }); } catch {}

  const { amount, senderNumber, senderName, provider } = extractVfSmsData(data.text);
  if (!amount || amount <= 0) throw new Error('تعذّر استخراج المبلغ من الرسالة');
  const list = Array.isArray(data.activeSimMsisdns) ? data.activeSimMsisdns : [];
  let found: { walletId: string; msisdn: string } | null = null;
  if (list.length > 0) {
    // حمّل محافظ المستخدم مرة واحدة (محلية + بعيدة) واستخدم كاشف المطابقة
    const uid = data.userId || auth.currentUser?.uid || 'default';
    const walletsKey = `wallets_${uid}`;
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(walletsKey) : null;
    const localList: any[] = raw ? JSON.parse(raw!) : [];
    const remoteList = await merchantWalletService.getByMerchantId(uid);
    const allWallets = [
      ...((Array.isArray(localList) ? localList : []).map(w => ({ id: String(w?.id || ''), phone: String(w?.phone || w?.msisdn || ''), isDefault: !!w?.isDefault }))),
      ...((Array.isArray(remoteList) ? remoteList : []).map((w: any) => ({ id: String(w?.id || ''), msisdn: String(w?.msisdn || ''), isDefault: !!w?.isDefault })))
    ];
    found = await detectWalletFromSim(list, allWallets);
  }
  if (!found) {
    const sim = normalizeMsisdnEgypt(data.simNumber || '');
    try { console.log('processVfSmsAutoWithdraw → fallback sim', sim); } catch {}
    found = await findWalletBySim(sim, data.userId);
  }
  try { console.log('processVfSmsAutoWithdraw → matched', found); } catch {}
  if (!found) throw new Error('لم يتم العثور على محفظة مطابقة لرقم الخط');

  // Save context to Capacitor Preferences for Native Background processing
  try {
    const { Preferences } = await import('@capacitor/preferences');
    await Preferences.set({ key: 'bg_user_id', value: data.userId });
    await Preferences.set({ key: 'bg_shop_id', value: data.shopId });
    if (found.walletId) {
      await Preferences.set({ key: 'bg_wallet_id', value: found.walletId });
    }
    // Also save webhook URL
    const webhookUrl = resolveSmsWebhookUrl();
    await Preferences.set({ key: 'bg_webhook_url', value: webhookUrl });
  } catch (e) {
    console.warn('Failed to save background context', e);
  }

  // Generate deterministic reference to prevent duplicates
  let uniqueRef = '';
  // Try to find explicit reference ID in text (e.g. "Ref: 017574345246")
  // Enhanced regex to catch numbers that might be attached to text or have different separators
  const refMatch = data.text.match(/(?:Ref|Reference|المرجع|عملي[ةه]|transaction\s*id|رقم\s*(?:العملي[ةه]|عملي[ةه]|التحويل|المرجع))\s*[:\-\s]*([0-9A-Za-z\-]+)/i);
                   
  if (refMatch && refMatch[1].length > 6) {
      uniqueRef = refMatch[1];
  } else {
      // Fallback to hash of content + sender + amount
      // STRIP EVERYTHING except letters and numbers to ensure consistency between Native/Web/Server
      const cleanText = data.text.replace(/[^a-zA-Z0-9\u0600-\u06FF]/g, '').slice(0, 100);
      const normalizedSender = (senderNumber || '').replace(/\D/g, '').slice(-10); // Use last 10 digits only for hash safety
      const key = `${normalizedSender}_${amount}_${cleanText}`;
      uniqueRef = btoa(unescape(encodeURIComponent(key))).replace(/[^a-zA-Z0-9]/g, '').slice(0, 32);
  }
  const reference = `SMS-AUTO-${uniqueRef}`;

  // Check for duplicates before recording
  // 1. Check by Reference
  const existingId = await findExistingByReference(reference);
  if (existingId) {
    console.log('Skipping duplicate SMS transaction (by reference):', reference);
    return { id: existingId, duplicate: true };
  }

  // 2. Check by Transaction Content (Amount, Sender, Approx Time) - Fuzzy Deduplication
  // This helps when the same SMS is received on two devices but parsed slightly differently or has no reference
  try {
     // Time window: +/- 5 minutes
     const now = new Date();
     const fiveMinutesAgo = new Date(now.getTime() - 5 * 60 * 1000);
     
     // Relaxed query: Match Amount and Time only, then filter by Sender in memory
     // This allows matching transactions where senderMsisdn might be missing or formatted differently
     const fuzzyQ = query(
        collection(db, 'transactions'),
        where('amount', '==', amount),
        where('createdAt', '>=', fiveMinutesAgo),
        orderBy('createdAt', 'desc'),
        limit(5) // Fetch a few candidates
     );
     
     const fuzzySnap = await getDocs(fuzzyQ);
     
     // Normalize sender number for comparison
     const normSender = senderNumber ? normalizeMsisdnEgypt(senderNumber) : '';
     
     const match = fuzzySnap.docs.find(doc => {
        const data = doc.data();
        
        // Check if sender matches OR is empty/undefined in DB (Manual entry might miss it)
        const dbSender = data.senderMsisdn || data.senderPhone || '';
        const normDbSender = normalizeMsisdnEgypt(dbSender);
        
        // Match if:
        // 1. Senders are identical (normalized)
        // 2. DB sender is empty (User didn't enter it manually)
        // 3. One of them is empty
        const senderMatch = !normSender || !normDbSender || normSender === normDbSender;
        
        // Also check if it's the same wallet
        // In UserDashboardPage, 'fromWallet' is used for the selected wallet
        const dbWalletId = data.walletId || data.fromWallet;
        const walletMatch = !effectiveWalletId || !dbWalletId || effectiveWalletId === dbWalletId;

        // Ensure transaction type is compatible (e.g. both are incoming or both are outgoing)
        // SMS 'receive' maps to 'receive' or 'withdraw' in some contexts
        // SMS 'send' maps to 'send' or 'transfer'
        // We can just rely on Amount/Time/Wallet for now as Amount collision + Time collision is rare
        
        return senderMatch && walletMatch;
     });

     if (match) {
        console.log('Skipping duplicate SMS transaction (fuzzy match):', match.id);
        return { id: match.id, duplicate: true };
     }
  } catch (e) {
     console.warn('Fuzzy deduplication check failed:', e);
  }

  const smsText = String(data.text || '');
  const isTransfer = /(تم\s*تحويل\s*مبلغ|تم\s*تحويل\s+\d+\s*جنيه|transferred\s*amount|sent\s*amount)/i.test(smsText);

  const id = await recordAutoTransaction({
    shopId: data.shopId,
    lineId: found.msisdn,
    walletId: found.walletId,
    amount,
    senderMsisdn: senderNumber,
    senderName: senderName,
    text: data.text,
    note: provider === 'etisalat_cash' ? 'SMS-Etisalat' : (provider === 'instapay' ? 'SMS-InstaPay' : 'SMS-VF'),
    provider: provider || 'vodafone_cash',
    createdBy: data.userId,
    txnType: isTransfer ? 'send' : 'receive'
  });
  return { id, duplicate: false } as any;
};

const resolveSmsWebhookUrl = (): string => {
  const cf = (import.meta as any)?.env?.VITE_CLOUDFLARE_SMS_WEBHOOK_URL as string | undefined;
  if (cf) return cf;
  const worker = 'https://frosty-sun-0baf.alkaptin2030.workers.dev/';
  if (worker) return worker;
  const pid = (import.meta as any)?.env?.VITE_FIREBASE_PROJECT_ID as string | undefined;
  const region = 'us-central1';
  return `https://${region}-${pid}.cloudfunctions.net/smsWebhook`;
};

const findSelectedWalletId = (uid?: string): string | null => {
  try {
    const userId = uid || auth.currentUser?.uid || '';
    const keys = Object.keys(localStorage);
    const selPrefix = `selectedWallet_${userId}`;
    const walletsPrefix = `wallets_${userId}`;
    const selectedKey = keys.find(k => k.startsWith(selPrefix));
    if (selectedKey) {
      const v = localStorage.getItem(selectedKey) || '';
      if (v) return v;
    }
    const walletsKey = keys.find(k => k.startsWith(walletsPrefix));
    if (walletsKey) {
      const arrStr = localStorage.getItem(walletsKey) || '';
      if (arrStr) {
        const arr = JSON.parse(arrStr);
        if (Array.isArray(arr) && arr.length > 0) {
          const def = arr.find((w: any) => w?.isDefault);
          return (def?.id || arr[0]?.id || null);
        }
      }
    }
  } catch {}
  return null;
};

export function initMobileSmsBridge() {
  if (typeof window === 'undefined') return () => {};
  const handler = async (ev: Event) => {
    try {
      const d = (ev as CustomEvent<any>).detail || {};
      try { console.log('📩 APP RECEIVED SMS →', d); } catch {}
      const message: string = String(d.text || '');
      const sender: string = String(d.sender || d.msisdn || '');
      const userId = auth.currentUser?.uid || '';
      const walletId = findSelectedWalletId(userId) || '';
      const shopId = undefined;
      const url = resolveSmsWebhookUrl();
      if (!message || !userId || !walletId) return;
      const timestamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
      try {
        await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ message, sender, timestamp, walletId, userId, shopId })
        });
      } catch {}
    } catch {}
  };
  // SMS bridge disabled: rely on notification events only
  return () => {};
}

