/**
 * يمنع رفع طابور Firestore للخادم أثناء تفعيل «الأوفلاين اليدوي».
 * لا يستورد firebase لتفادي دورات الاستيراد.
 */

export const MANUAL_FIRESTORE_HOLD_STORAGE_PREFIX = 'cashyManualFirestoreHold_';

const STORAGE_PREFIX = MANUAL_FIRESTORE_HOLD_STORAGE_PREFIX;

let inMemoryHold = false;
let currentUid: string | null = null;

const listeners = new Set<() => void>();

function notify(): void {
  listeners.forEach((cb) => {
    try {
      cb();
    } catch {
      /* ignore */
    }
  });
  if (typeof window !== 'undefined') {
    try {
      window.dispatchEvent(new CustomEvent('manualFirestoreHoldChanged'));
    } catch {
      /* ignore */
    }
  }
}

export function getManualFirestoreHoldStorageKey(uid: string): string {
  return `${STORAGE_PREFIX}${uid}`;
}

/** يُستدعى قبل `initializeFirestore`: إن وُجد مفتاح تأجيل مفعّل لأي مستخدم نستخدم ذاكرة فقط ونُجنّب b815 مع IndexedDB */
export function hasPersistedManualFirestoreHold(): boolean {
  if (typeof localStorage === 'undefined') return false;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !k.startsWith(STORAGE_PREFIX)) continue;
      if (localStorage.getItem(k) === 'true') return true;
    }
  } catch {
    /* ignore */
  }
  return false;
}

export function readManualFirestoreHoldFromStorage(uid: string | null | undefined): boolean {
  if (!uid || typeof localStorage === 'undefined') return false;
  try {
    return localStorage.getItem(getManualFirestoreHoldStorageKey(uid)) === 'true';
  } catch {
    return false;
  }
}

export function writeManualFirestoreHoldToStorage(uid: string | null | undefined, active: boolean): void {
  if (!uid || typeof localStorage === 'undefined') return;
  try {
    if (active) {
      localStorage.setItem(getManualFirestoreHoldStorageKey(uid), 'true');
    } else {
      localStorage.removeItem(getManualFirestoreHoldStorageKey(uid));
    }
  } catch {
    /* ignore */
  }
}

/** حالة الجلسة الحالية (مفعّل = لا رفع للخادم حتى يُطفأ المفتاح). */
export function isManualFirestoreHold(): boolean {
  return inMemoryHold;
}

/**
 * التأجيل فعّال من الذاكرة أو من localStorage (مهم بعد الريفريش قبل restoreManualFirestoreHoldAfterLogin).
 */
export function isManualFirestoreHoldEffective(uid: string | null | undefined): boolean {
  if (!uid) return isManualFirestoreHold();
  return inMemoryHold || readManualFirestoreHoldFromStorage(uid);
}

export function getManualFirestoreHoldUserId(): string | null {
  return currentUid;
}

/**
 * يحدّث الذاكرة والتخزين. يمرّر user.uid عند التغيير من الإعدادات.
 */
export function setManualFirestoreHold(active: boolean, uid?: string | null): void {
  inMemoryHold = active;
  const u = uid ?? currentUid;
  if (u) writeManualFirestoreHoldToStorage(u, active);
  notify();
}

/**
 * بعد تسجيل الدخول: يقرأ التفضيل المحفوظ ويحدّث الذاكرة. لا يغيّر شبكة Firestore.
 * @returns true إذا كان المستخدم قد فعّل التأجيل سابقاً
 */
export function restoreManualFirestoreHoldAfterLogin(uid: string): boolean {
  currentUid = uid;
  inMemoryHold = readManualFirestoreHoldFromStorage(uid);
  notify();
  return inMemoryHold;
}

/** عند تسجيل الخروج: يمسح الذاكرة فقط (التخزين يبقى لكل مستخدم). */
export function resetManualFirestoreHoldSession(): void {
  currentUid = null;
  inMemoryHold = false;
  notify();
}

export function subscribeManualFirestoreHold(callback: () => void): () => void {
  listeners.add(callback);
  return () => listeners.delete(callback);
}

if (typeof window !== 'undefined') {
  window.addEventListener('storage', (e: StorageEvent) => {
    if (!e.key || !e.key.startsWith(STORAGE_PREFIX)) return;
    const uid = currentUid;
    if (!uid || e.key !== getManualFirestoreHoldStorageKey(uid)) return;
    inMemoryHold = e.newValue === 'true';
    notify();
  });
}
