import React, { createContext, useContext, useEffect, useState } from 'react';
import { useFirebaseAuth } from '@/contexts/FirebaseAuthContext';
import { db } from '@/firebase';
import { doc, getDoc, setDoc, updateDoc } from 'firebase/firestore';

export interface ShiftPermissions {
  sales?: boolean;
  debts?: boolean;
  deficiencies?: boolean;
  cards?: boolean;
  lines?: boolean;
  myNumbers?: boolean;
  installments?: boolean;
  maintenance?: boolean;
  machines?: boolean;
  expenses?: boolean;
  settings?: boolean;
  branches?: boolean;
  transfers?: boolean;
  withdrawals?: boolean;
}

export interface ShiftUser {
  name: string;
  username: string;
  permissions?: ShiftPermissions;
  allowedWalletIds?: string[];
}

interface ShiftContextValue {
  shiftUser: ShiftUser | null;
  isShiftActive: boolean;
  shiftStartAt: number | null;
  setShiftUser: (user: ShiftUser | null) => void;
  startShift: () => void;
  endShift: () => void;
  refreshShiftStatus: () => Promise<void>;
}

const ShiftContext = createContext<ShiftContextValue | undefined>(undefined);

export const ShiftProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [shiftUser, setShiftUserState] = useState<ShiftUser | null>(null);
  const [isShiftActive, setIsShiftActive] = useState<boolean>(false);
  const [shiftStartAt, setShiftStartAt] = useState<number | null>(null);
  const { profile, user } = useFirebaseAuth();

  useEffect(() => {
    try {
      const savedUser = localStorage.getItem('cashier_shift_user');
      const savedActive = localStorage.getItem('cashier_shift_active');
      const savedStartAt = localStorage.getItem('cashier_shift_start_at');
      if (savedUser) setShiftUserState(JSON.parse(savedUser));
      if (savedActive) setIsShiftActive(savedActive === 'true');
      if (savedStartAt) setShiftStartAt(Number(savedStartAt));
    } catch {}
  }, []);

  const refreshShiftStatus = async () => {
    if (!profile?.shopId) return;
    try {
      const ref = doc(db, 'cashierShift', profile.shopId);
      const snap = await getDoc(ref);
      if (snap.exists()) {
        const data = snap.data() as any;
        const cloudActive = !!data?.isShiftActive;
        const cloudStartAt = data?.shiftStartAt ?? null;
        
        // المنطق الجديد: الاعتماد على التخزين المحلي لتحديد حالة الوردية للجهاز الحالي
        // إذا كانت الوردية مغلقة سحابياً، نغلقها محلياً
        // إذا كانت مفتوحة سحابياً، لا نفتحها محلياً إلا إذا كان الجهاز مسجل دخول في الوردية
        
        const localActive = localStorage.getItem('cashier_shift_active') === 'true';
        
        if (!cloudActive && localActive) {
           // الوردية أغلقت من جهاز آخر أو من الأدمن
           setIsShiftActive(false);
           setShiftUserState(null);
           localStorage.setItem('cashier_shift_active', 'false');
           localStorage.removeItem('cashier_shift_user');
           return;
        }

        if (cloudActive && !localActive) {
            // الوردية مفتوحة لكن هذا الجهاز ليس هو جهاز الكاشير (أو لم يسجل دخول كوردية)
            // نبقيه في وضع الأدمن (خارج الوردية)
            setIsShiftActive(false);
            setShiftUserState(null);
            return;
        }

        if (cloudActive && localActive) {
             // هذا الجهاز في وضع الوردية، والوردية نشطة سحابياً
             setIsShiftActive(true);
             
             // استعادة بيانات المستخدم من المحلي فقط
             try {
                const savedUser = localStorage.getItem('cashier_shift_user');
                if (savedUser) setShiftUserState(JSON.parse(savedUser));
             } catch {}
             
             // مزامنة وقت البدء من السحابة إذا وجد
             if (cloudStartAt) {
                 setShiftStartAt(Number(cloudStartAt));
                 localStorage.setItem('cashier_shift_start_at', String(cloudStartAt));
             }
        }
      } else {
         // Initialize if not exists
         await setDoc(ref, { isShiftActive: false, shiftStartAt: null, shiftUser: null });
      }
    } catch (e) {
      console.warn('Failed to refresh shift status:', e);
    }
  };

  useEffect(() => {
    refreshShiftStatus();
  }, [profile?.shopId]);

  const setShiftUser = (user: ShiftUser | null) => {
    setShiftUserState(user);
    try {
      if (user) localStorage.setItem('cashier_shift_user', JSON.stringify(user));
      else localStorage.removeItem('cashier_shift_user');
    } catch {}
    // حفظ المستخدم في السحابة لضمان التزامن عبر الأجهزة
    try {
      if (profile?.shopId) {
        const ref = doc(db, 'cashierShift', profile.shopId);
        updateDoc(ref, { shiftUser: user || null });
      }
    } catch {}
  };

  const startShift = () => {
    setIsShiftActive(true);
    try { localStorage.setItem('cashier_shift_active', 'true'); } catch {}
    const now = Date.now();
    setShiftStartAt(now);
    try { localStorage.setItem('cashier_shift_start_at', String(now)); } catch {}

    // مزامنة حالة الوردية مع Firestore
    try {
      if (profile?.shopId) {
        const ref = doc(db, 'cashierShift', profile.shopId);
        updateDoc(ref, { isShiftActive: true, shiftStartAt: now });
      }
    } catch {}

    // حفظ أرصدة البداية تلقائياً للاستخدام في إيصال التسليم
    try {
      const getCashBalanceKey = () => `cashBalance_${user?.uid || 'default'}`;
      const cashKey = getCashBalanceKey();
      const legacyCashKey = `userCashBalance_${user?.uid || 'default'}`;
      const walletsKey = `walletBalances_${user?.uid || 'default'}`;
      // محاولة استرجاع القيم من المفاتيح الاحتياطية (Last Known Good Configuration)
      const lastKnownCash = localStorage.getItem('lastKnownCashBalance');
      const lastKnownWallets = localStorage.getItem('lastKnownWalletBalances');

      let cashStr = localStorage.getItem(cashKey);
      
      // إذا لم نجد قيمة في المفتاح الأساسي، أو كانت القيمة 0، نحاول استخدام آخر قيمة معروفة
      if ((!cashStr || cashStr === '0') && lastKnownCash && lastKnownCash !== '0') {
        cashStr = lastKnownCash;
      }

      if (cashStr == null) {
        const legacy = localStorage.getItem(legacyCashKey);
        if (legacy != null) {
          cashStr = legacy;
          try {
            localStorage.setItem(cashKey, legacy);
            localStorage.removeItem(legacyCashKey);
          } catch {}
        }
      }
      if (cashStr == null && user?.uid) {
        const oldGlobalCash = localStorage.getItem('cashBalance');
        const oldUserCash = localStorage.getItem('userCashBalance');
        if (oldGlobalCash != null) {
          try { localStorage.setItem(cashKey, oldGlobalCash); localStorage.removeItem('cashBalance'); } catch {}
          cashStr = oldGlobalCash;
        } else if (oldUserCash != null) {
          try { localStorage.setItem(cashKey, oldUserCash); localStorage.removeItem('userCashBalance'); } catch {}
          cashStr = oldUserCash;
        }
      }
      
      let walletsStr = localStorage.getItem(walletsKey);
      if ((!walletsStr || walletsStr === '{}') && lastKnownWallets && lastKnownWallets !== '{}') {
        walletsStr = lastKnownWallets;
      }

      // فلوس الدرج عند الدخول
      if (cashStr) {
        localStorage.setItem('shiftStartDrawerFunds', cashStr);
      } else {
        localStorage.setItem('shiftStartDrawerFunds', '0');
      }
      // أرصدة المحافظ عند الدخول (تفصيل)
      if (walletsStr) {
        localStorage.setItem('shiftStartWalletBalances', walletsStr);
      } else {
        localStorage.setItem('shiftStartWalletBalances', '{}');
      }
    } catch {}

    // قراءة احتياطية مباشرة من Firebase لضمان التقاط أرصدة البداية حتى بدون فتح لوحة المستخدم
    try {
      if (profile?.shopId) {
        (async () => {
          try {
            const dataRef = doc(db, 'dashboardData', profile.shopId);
            const snap = await getDoc(dataRef);
            if (snap.exists()) {
              const data: any = snap.data();
              const fbCash = Number(data?.cashBalance ?? 0);
              const fbWallets = data?.walletBalances ?? {};

              // لا نستبدل القيم إن كانت محفوظة بالفعل من المحلية؛ نستخدم Firebase فقط إذا كانت القيم صفرية/مفقودة
              try {
                const lastKnownCash = localStorage.getItem('lastKnownCashBalance');
                const lastKnownWallets = localStorage.getItem('lastKnownWalletBalances');
                
                const currentStartCashStr = localStorage.getItem('shiftStartDrawerFunds');
                const currentStartWalletsStr = localStorage.getItem('shiftStartWalletBalances');
                const currentStartCashVal = currentStartCashStr ? parseFloat(currentStartCashStr) : 0;
                const currentStartWalletsObj = currentStartWalletsStr ? JSON.parse(currentStartWalletsStr) : {};
                const noStartCash = !currentStartCashStr || !Number.isFinite(currentStartCashVal) || currentStartCashVal === 0;
                const noStartWallets = !currentStartWalletsStr || Object.keys(currentStartWalletsObj || {}).length === 0;

                if (noStartCash) {
                  // الأولوية لآخر رصيد معروف محلياً إذا كان Firebase يرجع صفراً
                  if (fbCash === 0 && lastKnownCash && lastKnownCash !== '0') {
                    localStorage.setItem('shiftStartDrawerFunds', lastKnownCash);
                  } else {
                    localStorage.setItem('shiftStartDrawerFunds', String(Number.isFinite(fbCash) ? fbCash : 0));
                  }
                }
                
                if (noStartWallets) {
                  // الأولوية لآخر محافظ معروفة محلياً إذا كان Firebase يرجع فارغاً
                  if ((!fbWallets || Object.keys(fbWallets).length === 0) && lastKnownWallets && lastKnownWallets !== '{}') {
                     localStorage.setItem('shiftStartWalletBalances', lastKnownWallets);
                  } else {
                    localStorage.setItem('shiftStartWalletBalances', JSON.stringify(fbWallets || {}));
                  }
                }
              } catch {}
            }
          } catch (e) {
            // تجاهل أي أخطاء في القراءة من Firebase للحفاظ على سلاسة الواجهة
            console.warn('Shift start Firebase read failed:', e);
          }
        })();
      }
    } catch {}
  };

  const endShift = () => {
    setIsShiftActive(false);
    try { localStorage.setItem('cashier_shift_active', 'false'); } catch {}
    // تحديث حالة الوردية في Firestore
    try {
      if (profile?.shopId) {
        const ref = doc(db, 'cashierShift', profile.shopId);
        updateDoc(ref, { isShiftActive: false });
      }
    } catch {}
    // ملاحظة: لا نقوم بتصفير وقت بداية الوردية هنا لضمان احتساب التقرير بعد إنهائها
  };

  return (
    <ShiftContext.Provider value={{ shiftUser, isShiftActive, shiftStartAt, setShiftUser, startShift, endShift, refreshShiftStatus }}>
      {children}
    </ShiftContext.Provider>
  );
};

export const useShift = () => {
  const ctx = useContext(ShiftContext);
  if (!ctx) {
    throw new Error('useShift must be used within ShiftProvider');
  }
  return ctx;
};
