import React, { Component, ErrorInfo, ReactNode } from 'react';
import { Button } from '@/components/ui/button';
import { RefreshCcw, AlertTriangle } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class GlobalErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
    
    // إذا كان الخطأ هو NotFoundError الشهير (غالبًا بسبب إضافات المتصفح أو الترجمة)،
    // يمكننا محاولة إعادة التحميل تلقائيًا مرة واحدة أو مجرد تسجيله.
    // في الوقت الحالي، سنعرض واجهة الخطأ.
  }

  private handleReload = () => {
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      // التحقق مما إذا كان الخطأ متعلق بـ DOM Node missing (مشكلة Google Translate الشائعة)
      const isNodeError = this.state.error?.message?.includes('removeChild') || 
                          this.state.error?.message?.includes('NotFoundError') ||
                          this.state.error?.message?.includes('The node to be removed is not a child of this node');

      if (isNodeError) {
        // في حالة خطأ removeChild، نعيد تحميل الصفحة تلقائيًا لأنها حالة مستعصية تتطلب إعادة بناء DOM
        // نستخدم setTimeout لضمان عدم الدخول في حلقة لانهائية سريعة جدًا إذا استمر الخطأ
        // لكن بما أن هذا ErrorBoundary في الأعلى، إعادة التحميل هي الحل الأسلم
        // لتجنب الحلقة اللانهائية، يمكن التحقق من sessionStorage
        const reloadCount = parseInt(sessionStorage.getItem('node_error_reload_count') || '0');
        if (reloadCount < 2) {
            sessionStorage.setItem('node_error_reload_count', String(reloadCount + 1));
            window.location.reload();
            return null; // لن يظهر شيء لأن الصفحة ستعاد تحميلها
        }
        // إذا تكرر الخطأ أكثر من مرتين، نعرض الرسالة للمستخدم
        setTimeout(() => sessionStorage.removeItem('node_error_reload_count'), 10000);
      }

      return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-gray-50 p-4 text-center dark:bg-gray-900">
          <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 space-y-4">
            <div className="flex justify-center">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 rounded-full">
                <AlertTriangle className="w-8 h-8 text-red-600 dark:text-red-400" />
              </div>
            </div>
            
            <h2 className="text-xl font-bold text-gray-900 dark:text-gray-100">
              عذراً، حدث خطأ غير متوقع
            </h2>
            
            <p className="text-sm text-gray-600 dark:text-gray-400">
              {isNodeError 
                ? 'يبدو أن هناك تعارضاً مع إضافات المتصفح أو الترجمة التلقائية. يرجى تحديث الصفحة.' 
                : 'حدث خطأ أثناء تشغيل التطبيق. يرجى محاولة تحديث الصفحة.'}
            </p>

            {(
              process.env.NODE_ENV === 'development' ||
              (typeof window !== 'undefined' && (window as any).Capacitor)
            ) && (
              <pre className="text-xs text-left bg-gray-100 dark:bg-gray-950 p-2 rounded overflow-auto max-h-32 dir-ltr">
                {this.state.error?.toString()}
              </pre>
            )}

            <Button onClick={this.handleReload} className="w-full gap-2">
              <RefreshCcw className="w-4 h-4" />
              تحديث الصفحة
            </Button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}
