import { doc, updateDoc, getDoc, collection, query, where, getDocs, writeBatch } from 'firebase/firestore';
import { db } from '../firebase';

// أنواع الخطط المتاحة
export enum SubscriptionPlan {
  MONTHLY = 'monthly',
  QUARTERLY = 'quarterly',
  HALF_YEARLY = 'half_yearly',
  YEARLY = 'yearly',
  LIFETIME = 'lifetime',
  ZERO = 'zero',
  TAHWEELA = 'tahweela',
  FIVE_MINUTES = 'five_minutes',
  BRANCH = 'branch'
}

// واجهة بيانات الاشتراك
export interface SubscriptionData {
  planType: SubscriptionPlan | null;
  startDate: Date | null;
  endDate: Date | null;
  isActive: boolean;
  activatedBy?: string; // معرف الادمن الذي فعل الحساب
  activatedAt?: Date; // تاريخ التفعيل
}

// واجهة بيانات المستخدم مع الاشتراك
export interface UserWithSubscription {
  id: string;
  email: string;
  phone?: string;
  displayName?: string;
  isActive: boolean;
  createdAt: any;
  lastLogin?: any;
  subscription?: SubscriptionData;
  // دعم باقات الفروع (Branch Packages)
  branchPackage?: {
    requested?: boolean;
    status?: 'pending' | 'active' | 'rejected' | string;
    requestedAt?: any;
    activatedAt?: any;
    activatedBy?: string;
  };
  sessionLimit?: number | null;
  sessionLimitDisabled?: boolean;
}

/**
 * Helper to safely parse Firestore dates (Timestamp, Serialized Timestamp, Date, string)
 */
export const parseFirestoreDate = (date: any): Date | null => {
  if (!date) return null;
  
  // Handle Date object
  if (date instanceof Date) {
    return isNaN(date.getTime()) ? null : date;
  }
  
  // Handle Firestore Timestamp
  if (date.toDate && typeof date.toDate === 'function') {
    return date.toDate();
  }
  
  // Handle serialized Timestamp (seconds/nanoseconds)
  if (date.seconds !== undefined && typeof date.seconds === 'number') {
    return new Date(date.seconds * 1000);
  }
  
  // Handle string or number
  const d = new Date(date);
  return isNaN(d.getTime()) ? null : d;
};

/**
 * حساب تاريخ انتهاء الاشتراك بناءً على نوع الخطة
 * القواعد الجديدة:
 * - الباقة الشهرية: 30 يومًا من تاريخ التفعيل
 * - الباقة السنوية: 365 يومًا من تاريخ التفعيل  
 * - الباقة المفتوحة: لا تنتهي إلا بإيقاف يدوي
 */
export const calculateEndDate = (planType: SubscriptionPlan, startDate: Date = new Date()): Date | null => {
  const start = parseFirestoreDate(startDate) || new Date();
  switch (planType) {
    case SubscriptionPlan.MONTHLY: {
      const monthlyEnd = new Date(start);
      monthlyEnd.setDate(monthlyEnd.getDate() + 30);
      return monthlyEnd;
    }
    case SubscriptionPlan.FIVE_MINUTES: {
      const end = new Date(start);
      end.setMinutes(end.getMinutes() + 5);
      return end;
    }
    case SubscriptionPlan.TAHWEELA: {
      const end = new Date(start);
      end.setDate(end.getDate() + 30);
      return end;
    }
    case SubscriptionPlan.QUARTERLY: {
      const quarterlyEnd = new Date(start);
      quarterlyEnd.setDate(quarterlyEnd.getDate() + 90);
      return quarterlyEnd;
    }
    case SubscriptionPlan.HALF_YEARLY: {
      const halfYearlyEnd = new Date(start);
      halfYearlyEnd.setDate(halfYearlyEnd.getDate() + 180);
      return halfYearlyEnd;
    }
    case SubscriptionPlan.YEARLY: {
      const yearlyEnd = new Date(start);
      yearlyEnd.setDate(yearlyEnd.getDate() + 365);
      return yearlyEnd;
    }
    case SubscriptionPlan.LIFETIME:
      return null;
    case SubscriptionPlan.ZERO:
      return null;
    default:
      return null;
  }
};

/**
 * التحقق من صحة الاشتراك
 */
export const isSubscriptionValid = (subscription: SubscriptionData | undefined): boolean => {
  if (!subscription || !subscription.isActive) {
    return false;
  }
  
  // إذا كانت الخطة مدى الحياة، فهي صالحة دائماً
  if (subscription.planType === SubscriptionPlan.LIFETIME) {
    return true;
  }
  
  // التحقق من تاريخ الانتهاء
  if (!subscription.endDate) {
    // إذا لم يتوفر تاريخ انتهاء بشكل صحيح، اعتبر الاشتراك صالحًا مؤقتًا لتجنب إلغاء خاطئ
    // تحصين ضد مشاكل التحويل من Timestamp/Date/string
    const now = new Date();
    const activatedAt = parseFirestoreDate(subscription.activatedAt);
    
    // إذا تم التفعيل مؤخرًا (أقل من 4 ساعات)، اعتبره صالحًا
    if (activatedAt && (now.getTime() - activatedAt.getTime()) < 4 * 60 * 60 * 1000) {
      return true;
    }
    return true;
  }
  
  const now = new Date();
  // دعم قراءة Timestamp من Firestore أو Date أو string
  const endDate = parseFirestoreDate(subscription.endDate);
  
  // إذا كان التاريخ غير صالح (NaN)، لا تُعطّل الاشتراك بشكل خاطئ
  if (!endDate) {
    const activatedAt = parseFirestoreDate(subscription.activatedAt);
    if (activatedAt && (now.getTime() - activatedAt.getTime()) < 4 * 60 * 60 * 1000) {
      return true;
    }
    return true;
  }
  return now <= endDate;
};

/** نتيجة فحص التجربة المجانية (مثل FreeTrialService.checkTrialValidity) */
export type TrialValidityLite = { isValid: boolean; isExpired: boolean };

/**
 * تحويل حقل subscription من مستند Firestore إلى شكل يُمرَّر لـ isSubscriptionValid.
 * إذا غاب subscription.isActive في المستند القديم، يُعتبر مفعّلاً ما لم يُضبط صراحةً false.
 */
export const subscriptionFromUserDocRaw = (raw: any): SubscriptionData | undefined => {
  if (!raw || typeof raw !== 'object') return undefined;
  const planType = (raw.planType ?? raw.plan ?? null) as SubscriptionPlan | null;
  if (planType == null && !raw.endDate && raw.isActive === undefined) return undefined;
  return {
    planType,
    startDate: parseFirestoreDate(raw.startDate),
    endDate: parseFirestoreDate(raw.endDate),
    isActive: raw.isActive !== false,
    activatedAt: parseFirestoreDate(raw.activatedAt) ?? undefined,
    activatedBy: typeof raw.activatedBy === 'string' ? raw.activatedBy : undefined,
  };
};

/**
 * هل يُسمح بالدخول للوحة المستخدم؟
 * يعالج اختلاف الحقول: اشتراك ساري (تواريخ + subscription.isActive) بينما users.isActive=false بسبب تحديث جزئي أو بيانات قديمة.
 */
export const isDashboardAccessAllowed = (
  userData: Record<string, any> | undefined | null,
  trialValidity?: TrialValidityLite | null
): boolean => {
  if (!userData) return false;
  if (userData.isActive === true) return true;
  if (trialValidity && trialValidity.isValid && !trialValidity.isExpired) return true;
  const sub = subscriptionFromUserDocRaw(userData.subscription);
  return isSubscriptionValid(sub);
};

/** للوحة الأدمن: نشط فعلياً (حساب أو اشتراك ساري أو تجربة ظاهرة على المستند) */
export const isUserEffectivelyActiveForAdmin = (userData: any): boolean => {
  if (!userData) return false;
  if (userData.isActive === true) return true;
  if (userData.isOnFreeTrial === true) {
    const end = parseFirestoreDate(userData.freeTrialEndDate);
    if (!end) return true;
    return new Date() <= end;
  }
  const sub = subscriptionFromUserDocRaw(userData.subscription);
  return isSubscriptionValid(sub);
};

/**
 * الحصول على عدد الأيام المتبقية في الاشتراك
 */
export const getDaysRemaining = (subscription: SubscriptionData | undefined): number | null => {
  if (!subscription || !subscription.isActive) {
    return null;
  }
  
  // إذا كانت الخطة مدى الحياة
  if (subscription.planType === SubscriptionPlan.LIFETIME) {
    return -1; // رمز للدلالة على أنها مدى الحياة
  }
  
  if (!subscription.endDate) {
    return null;
  }
  
  const now = new Date();
  // دعم قراءة Timestamp من Firestore أو Date أو string
  const endDate = parseFirestoreDate(subscription.endDate);
  
  if (!endDate) {
    return null;
  }
  const diffTime = endDate.getTime() - now.getTime();
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  
  return diffDays > 0 ? diffDays : 0;
};

/**
 * تفعيل اشتراك للمستخدم
 */
export const activateUserSubscription = async (
  userId: string,
  planType: SubscriptionPlan,
  adminId: string,
  variant?: string | null,
  customStartDate?: Date | null,
  customEndDate?: Date | null
): Promise<void> => {
  try {
    const startDate = customStartDate || new Date();
    const endDate = customEndDate || calculateEndDate(planType, startDate);
    
    const subscriptionData: SubscriptionData = {
      planType,
      startDate,
      endDate,
      isActive: true,
      activatedBy: adminId,
      activatedAt: new Date() // Keep track of actual action time
    };
    
    console.log('🔄 Activating subscription for user:', {
      userId,
      planType,
      adminId,
      subscriptionData
    });
    
    // تحديث بيانات المستخدم في قاعدة البيانات
    const userRef = doc(db, 'users', userId);
    await updateDoc(userRef, {
      subscription: subscriptionData,
      isActive: true, // تفعيل الحساب أيضاً
      approved: true, // الموافقة على الحساب
      // إيقاف أي تجربة مجانية قائمة حتى لا تُلغي الاشتراك الجديد
      isOnFreeTrial: false,
      freeTrialStartDate: null,
      freeTrialEndDate: null,
      updatedAt: new Date()
    });
    
    // Check if this user is a branch (has ownerId), if so, update the branch reference in the parent's subcollection
    try {
        const userSnap = await getDoc(userRef);
        if (userSnap.exists()) {
            const userData = userSnap.data();
            if (userData.ownerId) {
                // This is a branch, update the reference in parent's collection
                const parentId = userData.ownerId;
                // Try to update in subcollection
                try {
                    const branchRef = doc(db, 'users', parentId, 'branches', userId);
                    await updateDoc(branchRef, {
                         isActive: true, // Mark branch as active in list
                         updatedAt: new Date()
                    });
                } catch (e) {
                    console.warn('Could not update branch reference in parent subcollection', e);
                }
            }
        }
    } catch (e) {
        console.warn('Error syncing branch status to parent:', e);
    }

    console.log('✅ Subscription data updated in Firestore');
    
    // إرسال إشعار فوري للمستخدم بالتفعيل
    if (typeof window !== 'undefined') {
      // إرسال إشعار مخصص للمستخدم المفعل
      const event = new CustomEvent('subscriptionActivated', {
        detail: { userId, planType, timestamp: new Date().toISOString() }
      });
      window.dispatchEvent(event);
      
      console.log('📢 Subscription activation event dispatched:', { userId, planType });
      
      // إرسال إشعار عام لجميع المكونات
      const globalEvent = new CustomEvent('userSubscriptionUpdated', {
        detail: { 
          userId, 
          planType, 
          isActive: true,
          timestamp: new Date().toISOString()
        }
      });
      window.dispatchEvent(globalEvent);
      
      console.log('📢 Global subscription update event dispatched');
    }
    
    console.log(`✅ تم تفعيل اشتراك ${planType} للمستخدم ${userId}`);
  } catch (error) {
    console.error('❌ خطأ في تفعيل الاشتراك:', error);
    throw new Error('فشل في تفعيل الاشتراك');
  }
};

/**
 * إلغاء تفعيل اشتراك المستخدم
 */
export const deactivateUserSubscription = async (userId: string): Promise<void> => {
  try {
    const batch = writeBatch(db);
    const userRef = doc(db, 'users', userId);

    // 1. Deactivate main user
    batch.update(userRef, {
      'subscription.isActive': false,
      isActive: false, // إلغاء تفعيل الحساب أيضاً
      // Cancel branch package if exists
      'branchPackage.status': 'canceled',
      'branchPackage.canceledAt': new Date(),
      // إيقاف أي تجربة مجانية قائمة لضمان تعطيل الوصول فعلياً
      isOnFreeTrial: false,
      freeTrialStartDate: null,
      freeTrialEndDate: null,
      updatedAt: new Date()
    });

    // 2. Deactivate all associated branch users
    // Find users where ownerId == userId (These are the branch accounts)
    const branchesQuery = query(collection(db, 'users'), where('ownerId', '==', userId));
    const branchesSnapshot = await getDocs(branchesQuery);

    branchesSnapshot.forEach((branchDoc) => {
        batch.update(branchDoc.ref, {
            isActive: false, // This will trigger PendingApprovalPage logic to block access
            'subscription.isActive': false, // Ensure subscription is also off
            updatedAt: new Date()
        });
    });
    
    await batch.commit();
    
    console.log(`✅ تم إلغاء تفعيل اشتراك المستخدم ${userId} وجميع فروعه (${branchesSnapshot.size})`);
  } catch (error) {
    console.error('❌ خطأ في إلغاء تفعيل الاشتراك:', error);
    throw new Error('فشل في إلغاء تفعيل الاشتراك');
  }
};

/**
 * إنهاء صلاحية باقة الفروع فقط (دون إلغاء الاشتراك الرئيسي إذا كان منفصلاً)
 */
export const expireBranchPackage = async (userId: string): Promise<void> => {
    try {
        const batch = writeBatch(db);
        const userRef = doc(db, 'users', userId);

        // 1. Mark branch package as expired
        batch.update(userRef, {
            'branchPackage.status': 'expired',
            'branchPackage.expiredAt': new Date(),
            updatedAt: new Date()
        });

        // 2. Deactivate all associated branch users
        const branchesQuery = query(collection(db, 'users'), where('ownerId', '==', userId));
        const branchesSnapshot = await getDocs(branchesQuery);

        branchesSnapshot.forEach((branchDoc) => {
            batch.update(branchDoc.ref, {
                isActive: false,
                updatedAt: new Date()
            });
        });

        await batch.commit();
        console.log(`✅ Branch package expired for user ${userId}`);
    } catch (e) {
        console.error('Failed to expire branch package:', e);
    }
};

/**
 * التحقق من صلاحية باقة الفروع
 */
export const checkBranchPackageExpiration = async (userId: string, branchPackage: any): Promise<void> => {
    if (branchPackage?.status !== 'active' || !branchPackage.endDate) return;

    // Use parseFirestoreDate helper
    const endDate = parseFirestoreDate(branchPackage.endDate);
    if (!endDate) return;

    if (new Date() > endDate) {
        console.log(`Branch package expired for user ${userId}. Deactivating...`);
        await expireBranchPackage(userId);
    }
};

/**
 * الحصول على بيانات اشتراك المستخدم
 */
export const getUserSubscription = async (userId: string): Promise<SubscriptionData | null> => {
  try {
    const userRef = doc(db, 'users', userId);
    const userDoc = await getDoc(userRef);
    
    if (!userDoc.exists()) {
      return null;
    }
    
    const userData = userDoc.data();
    return userData.subscription || null;
  } catch (error) {
    console.error('❌ خطأ في الحصول على بيانات الاشتراك:', error);
    return null;
  }
};

