/**
 * الحصول على نص وصفي لنوع الخطة
 */
export const getPlanDisplayName = (planType: SubscriptionPlan | null): string => {
  switch (planType) {
    case SubscriptionPlan.MONTHLY:
      return 'شهرية';
    case SubscriptionPlan.QUARTERLY:
      return 'ربع سنوية';
    case SubscriptionPlan.HALF_YEARLY:
      return 'نصف سنوية';
    case SubscriptionPlan.YEARLY:
      return 'سنوية';
    case SubscriptionPlan.LIFETIME:
      return 'مدى الحياة';
    case SubscriptionPlan.ZERO:
      return 'زيرو';
    case SubscriptionPlan.TAHWEELA:
      return 'تحويله';
    case SubscriptionPlan.FIVE_MINUTES:
      return '5 دقايق';
    case SubscriptionPlan.BRANCH:
      return 'باقة فرعية';
    default:
      return 'غير محدد';
  }
};

/**
 * الحصول على لون الحالة للعرض في الواجهة
 */
export const getSubscriptionStatusColor = (subscription: SubscriptionData | undefined): string => {
  if (!subscription) {
    return 'text-gray-500';
  }
  
  if (!subscription.isActive) {
    return 'text-red-500';
  }
  
  if (subscription.planType === SubscriptionPlan.LIFETIME) {
    return 'text-green-600';
  }
  
  const daysRemaining = getDaysRemaining(subscription);
  if (daysRemaining === null || daysRemaining <= 0) {
    return 'text-red-500';
  }
  
  if (daysRemaining <= 7) {
    return 'text-yellow-500';
  }
  
  return 'text-green-500';
};

/**
 * تنسيق التاريخ للعرض باللغة العربية
 */
export const formatDate = (date: any): string => {
  const parsedDate = parseFirestoreDate(date);
  
  if (!parsedDate) {
    return 'غير محدد';
  }
  
  return parsedDate.toLocaleDateString('ar-EG', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });
};

export const isPaidPlan = (plan: SubscriptionPlan | null | undefined): boolean => {
  return plan === SubscriptionPlan.MONTHLY || plan === SubscriptionPlan.QUARTERLY || plan === SubscriptionPlan.HALF_YEARLY || plan === SubscriptionPlan.YEARLY || plan === SubscriptionPlan.LIFETIME;
};

export const shouldShowMobileAds = (subscription: SubscriptionData | undefined, isMobile: boolean): boolean => {
  if (!isMobile) return false;
  if (!subscription) return false;
  const plan = subscription.planType;
  if (plan === SubscriptionPlan.ZERO || plan === SubscriptionPlan.TAHWEELA || plan === SubscriptionPlan.FIVE_MINUTES) return true;
  if (isPaidPlan(plan)) return false;
  return false;
};
