import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useFirebaseAuth } from "@/contexts/FirebaseAuthContext";
import { toast } from "sonner";
import { ArrowRight, Eye, EyeOff, Lock, Mail } from "lucide-react";
import { Checkbox } from "@/components/ui/checkbox";
import { auth } from "@/firebase";
import { setPersistence, browserLocalPersistence, browserSessionPersistence } from "firebase/auth";

/** مسار أصول `public/` متوافق مع Electron (`base: "./"`) — لا تستخدم `/name.png` المطلق */
const publicAsset = (file: string) => `${import.meta.env.BASE_URL}${file.replace(/^\//, "")}`;

const UserLoginPage = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isOffline, setIsOffline] = useState(typeof navigator !== 'undefined' ? !navigator.onLine : false);

  useEffect(() => {
    const handleStatus = () => setIsOffline(!navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  const [rememberLogin, setRememberLogin] = useState<boolean>(true);
  const { signIn, user: currentUser, checkSubscriptionStatus, loading } = useFirebaseAuth();
  const navigate = useNavigate();
  useEffect(() => {
    try {
      if (currentUser && !loading) {
        navigate('/user/dashboard');
      }
    } catch {}
  }, [currentUser, loading, navigate]);

  // استرجاع آخر بريد تم استخدامه للتسجيل
  useEffect(() => {
    try {
      const last = typeof window !== 'undefined' ? window.localStorage.getItem('cashy:lastEmail') : null;
      if (last) setEmail(last);
    } catch {}
    try {
      const remember = typeof window !== 'undefined' ? window.localStorage.getItem('cashy:rememberLogin') : null;
      if (remember === 'true') setRememberLogin(true);
      else if (remember === 'false') setRememberLogin(false);
    } catch {}
    (async () => {
      try {
        if ((typeof navigator !== 'undefined') && (navigator as any).credentials && window.localStorage.getItem('cashy:rememberLogin') === 'true') {
          const cred: any = await (navigator as any).credentials.get?.({ password: true, mediation: 'optional' });
          if (cred && cred.type === 'password') {
            if (cred.id) setEmail(cred.id);
            if (cred.password) setPassword(cred.password);
          }
        }
        if (window.localStorage.getItem('cashy:rememberLogin') === 'true') {
          try {
            const remembered = sessionStorage.getItem('cashy:rememberedPassword');
            if (remembered && !password) setPassword(remembered);
          } catch {}
        }
      } catch {}
    })();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // في حال الضغط أثناء التنفيذ، نعرض سبب المنع ونوقف
    if (isLoading) {
      toast.info("جارٍ تنفيذ تسجيل الدخول، يرجى الانتظار...");
      return;
    }
    // التحقق من الاتصال قبل البدء
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
      toast.error("لا يوجد اتصال بالإنترنت. يرجى التأكد من الشبكة ثم المحاولة.");
      return;
    }
    
    // تطبيع البريد وكلمة المرور قبل الإرسال (أسماء مختلفة لتجنب أي تعارضات)
    const safeEmail = (email || '').trim().toLowerCase();
    const safePassword = (password || '').trim();
    console.log('🔐 بدء عملية تسجيل الدخول:', { email: safeEmail, password: "***" });
    
    if (!email || !password) {
      toast.error("يرجى ملء جميع الحقول");
      return;
    }
    // تحقق صيغة البريد
    if (!/^\S+@\S+\.\S+$/.test(safeEmail)) {
      toast.error("صيغة البريد الإلكتروني غير صحيحة");
      return;
    }

    setIsLoading(true);
    
    try {
      try {
        await setPersistence(auth, rememberLogin ? browserLocalPersistence : browserSessionPersistence);
        try { window.localStorage.setItem('cashy:rememberLogin', rememberLogin ? 'true' : 'false'); } catch {}
      } catch {}
      console.log('🔐 استدعاء signIn...');
      const { error } = await signIn(safeEmail, safePassword);
      console.log('🔐 SignIn result:', { error });
      
      if (error) {
        console.error("❌ خطأ في تسجيل الدخول:", error);
        const code = (error as any)?.code;
        if (code === 'auth/user-not-found') {
          toast.error('لا يوجد حساب بهذا البريد الإلكتروني');
        } else if (code === 'auth/wrong-password') {
          toast.error('كلمة المرور غير صحيحة');
        } else if (code === 'auth/invalid-credential') {
          toast.error('البريد الإلكتروني أو كلمة المرور غير صحيحة');
        } else if (code === 'auth/too-many-requests') {
          toast.error('تم تجاوز عدد المحاولات المسموح، حاول لاحقاً');
        } else {
          toast.error((error as any)?.message || "حدث خطأ أثناء تسجيل الدخول");
        }
      } else {
        console.log("✅ تم تسجيل الدخول بنجاح!");
        toast.success("تم تسجيل الدخول بنجاح!");
        try {
          if (rememberLogin && (navigator as any).credentials && (window as any).PasswordCredential) {
            const cred = new (window as any).PasswordCredential({ id: safeEmail, name: safeEmail, password: safePassword });
            await (navigator as any).credentials.store(cred);
          }
          if (rememberLogin) {
            try { sessionStorage.setItem('cashy:rememberedPassword', safePassword); } catch {}
          } else {
            try { sessionStorage.removeItem('cashy:rememberedPassword'); } catch {}
          }
        } catch {}
        // تمت إزالة التحديث التلقائي للصفحة لمنع التحديث المزدوج
        // سيتم التوجيه عبر useEffect في الأعلى عندما يتغير user
        // setTimeout(() => { try { window.location.reload(); } catch {} }, 800);
      }
    } catch (error) {
      console.error("❌ خطأ غير متوقع:", error);
      toast.error("حدث خطأ غير متوقع");
    } finally {
      setIsLoading(false);
    }
  };

  // فحص سريع قبل النقر على زر التسجيل لعرض سبب المنع إن وُجد
  const preClickCheck = (e: React.MouseEvent<HTMLButtonElement>) => {
    // في حالة التنفيذ الجاري أو انقطاع الشبكة نمنع الإرسال ونوضح السبب
    if (isLoading) {
      e.preventDefault();
      e.stopPropagation();
      toast.info("جارٍ تنفيذ تسجيل الدخول، يرجى الانتظار...");
      return;
    }
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
      e.preventDefault();
      e.stopPropagation();
      toast.error("لا يوجد اتصال بالإنترنت. يرجى التأكد من الشبكة ثم المحاولة.");
      return;
    }
    // تنبيهات إرشادية دون منع الإرسال، المتصفح سيتولى التحقق عبر required
    if (!email) {
      toast.error("يرجى إدخال البريد الإلكتروني");
    }
    if (!password) {
      toast.error("يرجى إدخال كلمة المرور");
    }
    const safeEmail = (email || '').trim().toLowerCase();
    if (safeEmail && !/^\S+@\S+\.\S+$/.test(safeEmail)) {
      toast.error("صيغة البريد الإلكتروني غير صحيحة");
    }
  };

  const goToForgotPasswordWithCode = () => {
    navigate("/user/forgot-password");
  };

  // منع الارتداد فقط على الأجهزة اللمسية لتفادي تأثيرات غير مرغوبة على سطح المكتب
  useEffect(() => {
    if (!(typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(pointer: coarse)').matches)) {
      return; // لا نغير أنماط الصفحة على الأجهزة غير اللمسية
    }

    const htmlEl = document.documentElement;
    const bodyEl = document.body;
    const prevHtmlOverflow = htmlEl.style.overflow;
    const prevBodyOverflow = bodyEl.style.overflow;
    const prevHtmlOverscroll = (htmlEl.style as any).overscrollBehaviorY;
    const prevBodyOverscroll = (bodyEl.style as any).overscrollBehaviorY;

    htmlEl.style.overflow = 'hidden';
    bodyEl.style.overflow = 'hidden';
    (htmlEl.style as any).overscrollBehaviorY = 'none';
    (bodyEl.style as any).overscrollBehaviorY = 'none';

    return () => {
      htmlEl.style.overflow = prevHtmlOverflow || '';
      bodyEl.style.overflow = prevBodyOverflow || '';
      (htmlEl.style as any).overscrollBehaviorY = prevHtmlOverscroll || '';
      (bodyEl.style as any).overscrollBehaviorY = prevBodyOverscroll || '';
    };
  }, []);

  

  return (
    <div className="relative min-h-[100dvh] w-full overflow-hidden bg-[#180a35] px-4 py-8">
      <div className="pointer-events-none absolute inset-0">
        <div className="absolute -right-20 -top-24 h-72 w-72 rounded-full bg-cyan-500/20 blur-3xl" />
        <div className="absolute -left-20 bottom-8 h-80 w-80 rounded-full bg-fuchsia-500/20 blur-3xl" />
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_35%_20%,rgba(60,221,180,0.18),transparent_35%),radial-gradient(circle_at_75%_80%,rgba(59,130,246,0.18),transparent_35%)]" />
      </div>

      {isOffline && (
        <div className="absolute left-4 right-4 top-4 z-50 rounded-xl border border-red-300/40 bg-red-500/80 px-4 py-2 text-center text-sm font-medium text-white shadow-lg backdrop-blur">
          لا يوجد اتصال بالإنترنت. يمكنك تصفح التطبيق ولكن لا يمكنك تسجيل الدخول.
        </div>
      )}

      <div className="relative z-10 mx-auto flex min-h-[calc(100dvh-4rem)] w-full max-w-6xl items-center justify-center">
        <div className="grid w-full overflow-hidden rounded-3xl border border-white/15 bg-white/5 shadow-[0_20px_80px_rgba(0,0,0,0.45)] backdrop-blur-2xl lg:grid-cols-[1.05fr_1fr]">
          <div className="relative hidden min-h-[min(560px,70vh)] lg:flex flex-col border-r border-white/10 bg-gradient-to-br from-emerald-400/20 via-teal-400/10 to-transparent p-10">
            <div className="shrink-0">
              <span className="inline-flex items-center rounded-full border border-white/20 bg-white/10 px-4 py-1 text-xs font-semibold tracking-wider text-white/90">
                CASHY LINK
              </span>
            </div>
            <div className="flex flex-1 flex-col items-center justify-center py-10 px-2 min-h-0">
              <img
                src={publicAsset("cashy-brand-logo.png")}
                alt="CASHY LINK"
                className="h-auto w-full max-w-[240px] object-contain drop-shadow-[0_16px_48px_rgba(0,0,0,0.4)]"
                width={512}
                height={512}
                decoding="async"
              />
            </div>
            <div className="shrink-0 rounded-2xl border border-white/15 bg-black/20 p-4 text-sm text-white/80">
              <p className="font-semibold text-white">🔒 جلسة آمنة ومشفرة</p>
              <p className="mt-1 text-xs text-white/70">
                يتم حماية بياناتك أثناء تسجيل الدخول بتشفير كامل.
              </p>
            </div>
          </div>

          <div className="p-6 sm:p-8 lg:p-10">
            <div className="mx-auto w-full max-w-md">
              <div className="mb-8 text-center">
                <div className="mx-auto mb-4 flex h-20 w-20 items-center justify-center overflow-hidden rounded-2xl border border-white/20 bg-white/95 p-1.5 shadow-[0_10px_30px_rgba(37,99,235,0.25)] dark:bg-white/90">
                  <img
                    src={publicAsset("cashy-brand-logo.png")}
                    alt=""
                    className="h-full w-full object-contain"
                    width={80}
                    height={80}
                    decoding="async"
                  />
                </div>
                <p className="text-xs font-semibold uppercase tracking-[0.25em] text-white/65">CASHY LINK</p>
                <h1 className="mt-2 text-3xl font-extrabold text-white">تسجيل دخول المستخدم</h1>
                <p className="mt-1 text-sm text-white/75">أدخل بياناتك للوصول إلى حسابك</p>
              </div>

              <form onSubmit={handleSubmit} className="space-y-5" autoComplete="on">
                <div className="space-y-2">
                  <label htmlFor="email" className="block text-sm font-medium text-white/90">
                    البريد الإلكتروني
                  </label>
                  <div className="relative">
                    <Mail className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/70" />
                    <Input
                      id="username"
                      type="email"
                      placeholder="أدخل بريدك الإلكتروني"
                      value={email}
                      onChange={(e) => {
                        const v = e.target.value;
                        setEmail(v);
                        try { window.localStorage.setItem('cashy:lastEmail', v); } catch {}
                      }}
                      name="username"
                      autoComplete="username"
                      className="user-login-email-input h-12 rounded-xl border border-white/25 bg-black/25 pl-10 pr-4 !text-white placeholder:!text-white/55 shadow-inner backdrop-blur-sm focus-visible:border-emerald-400/70 focus-visible:ring-2 focus-visible:ring-emerald-400/45 focus-visible:ring-offset-0 dark:bg-black/30"
                      dir="rtl"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label htmlFor="password" className="block text-sm font-medium text-white/90">
                    كلمة المرور
                  </label>
                  <div className="relative">
                    <Lock className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" />
                    <Input
                      id="password"
                      type={showPassword ? "text" : "password"}
                      placeholder="أدخل كلمة المرور"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="h-12 rounded-xl border border-slate-200/90 bg-white pl-10 pr-11 text-slate-900 placeholder:text-slate-400 shadow-sm focus-visible:border-emerald-400/60 focus-visible:ring-2 focus-visible:ring-emerald-400/40 focus-visible:ring-offset-0 dark:bg-white dark:text-slate-900"
                      name="password"
                      autoComplete="current-password"
                      dir="rtl"
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 transition-colors hover:text-slate-800"
                    >
                      {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                    </button>
                  </div>
                </div>

                <div className="flex items-center justify-between gap-3 pt-1">
                  <div className="flex items-center gap-2">
                    <Checkbox id="rememberLogin" checked={rememberLogin} onCheckedChange={(v) => setRememberLogin(!!v)} />
                    <label htmlFor="rememberLogin" className="text-sm text-white/85">
                      حفظ بيانات الدخول
                    </label>
                  </div>

                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={goToForgotPasswordWithCode}
                    className="h-auto p-0 text-sm font-normal text-emerald-200 hover:bg-transparent hover:text-emerald-100"
                  >
                    <Mail className="ml-1 h-4 w-4" />
                    نسيت كلمة المرور؟
                  </Button>
                </div>

                <button
                  type="submit"
                  onClick={preClickCheck}
                  className="group flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-emerald-500 to-blue-500 px-4 font-semibold text-white shadow-[0_8px_24px_rgba(16,185,129,0.35)] transition-all duration-200 hover:from-emerald-400 hover:to-blue-400 focus:outline-none focus:ring-2 focus:ring-emerald-300/70 disabled:cursor-not-allowed disabled:opacity-70"
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <>
                      <div className="h-5 w-5 animate-spin rounded-full border-2 border-white/30 border-b-white" />
                      جاري تسجيل الدخول...
                    </>
                  ) : (
                    <>
                      <ArrowRight className="h-5 w-5 transition-transform group-hover:translate-x-1" />
                      تسجيل الدخول
                    </>
                  )}
                </button>
              </form>

              <div className="mt-6 rounded-xl border border-white/10 bg-black/20 p-4 text-center">
                <p className="text-sm text-white/80">
                  ليس لديك حساب؟{" "}
                  <Link
                    to="/user/register"
                    className="font-semibold text-emerald-200 transition-colors hover:text-emerald-100 hover:underline"
                  >
                    إنشاء حساب جديد
                  </Link>
                </p>
                <p className="mt-3 text-xs leading-6 text-white/70">
                  في حالة وجود مشكلة يمكنك التواصل معنا عبر واتساب{" "}
                  <a
                    href="https://wa.me/201000392539"
                    target="_blank"
                    rel="noreferrer"
                    className="font-semibold text-emerald-200 hover:text-emerald-100 hover:underline"
                  >
                    01000392539
                  </a>{" "}
                  أو عبر البريد الإلكتروني{" "}
                  <a
                    href="mailto:info@cashy-link.com"
                    className="font-semibold text-blue-200 hover:text-blue-100 hover:underline"
                  >
                    info@cashy-link.com
                  </a>
                </p>
              </div>

              <p className="mt-4 text-center text-xs text-white/65">🔒 جلسة آمنة ومشفرة</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserLoginPage;
