import * as React from "react"

import { cn } from "@/lib/utils"

const Input = React.forwardRef<HTMLInputElement, React.ComponentProps<"input">>(
  ({ className, type, ...props }, ref) => {
    // Ensure controlled inputs never receive undefined as value
    const safeProps = { ...props } as Record<string, any>;
    if (Object.prototype.hasOwnProperty.call(safeProps, 'value') && safeProps.value === undefined) {
      safeProps.value = '';
      if (import.meta.env.DEV) {
        // Helpful log to locate offending inputs during development
        console.warn('Input received undefined value; coercing to empty string', {
          id: safeProps.id,
          name: safeProps.name,
          type,
        });
      }
    }

    return (
      <input
        type={type}
        className={cn(
          "flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-base ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
          className
        )}
        ref={ref}
        {...safeProps}
      />
    )
  }
)
Input.displayName = "Input"

export { Input }
