/** توحيد اسم منفذ ويندوز COM (COM3 / com12 → COM3 / COM12) لتفادي تكرار نفس المنفذ بأحرف مختلفة */
export function canonicalModemPortPath(p: string): string {
  const t = (p || '').trim();
  const m = t.match(/^com(\d+)$/i);
  if (m) return `COM${m[1]}`;
  return t;
}

/** قراءة إعداد منفذ مع دمج مفاتيح قديمة باختلاف حالة الأحرف */
export function lookupModemPortSettings<T extends Record<string, unknown>>(
  settings: Record<string, T> | null | undefined,
  portPath: string
): T | undefined {
  if (!settings || !portPath) return undefined;
  const needle = canonicalModemPortPath(portPath).toLowerCase();
  for (const k of Object.keys(settings)) {
    if (canonicalModemPortPath(k).toLowerCase() === needle) return settings[k];
  }
  return undefined;
}

/**
 * تجميع كل مسارات المودم المُعرَّفة للتطبيق: الافتراضي + إعدادات المحافظ + منافذ مضافة يدوياً.
 * يُستخدم في الاستماع لـ SMS واستطلاع صندوق الوارد.
 */
export function getAllConfiguredModemPortPaths(): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const add = (p: string) => {
    const t = canonicalModemPortPath(p);
    if (!t) return;
    const k = t.toLowerCase();
    if (seen.has(k)) return;
    seen.add(k);
    out.push(t);
  };
  try {
    add(localStorage.getItem('cashyModemPort') || '');
  } catch {}
  try {
    const settingsRaw = localStorage.getItem('cashyModemPortSettings');
    const settings = settingsRaw ? JSON.parse(settingsRaw) : {};
    Object.keys(settings || {}).forEach((path: string) => add(path));
  } catch {}
  try {
    const manualRaw = localStorage.getItem('cashyModemManualPorts');
    const manual = manualRaw ? JSON.parse(manualRaw) : [];
    if (Array.isArray(manual)) {
      manual.forEach((path: unknown) => add(String(path || '')));
    }
  } catch {}
  return out;
}

export const CASHY_MODEM_MANUAL_PORTS_KEY = 'cashyModemManualPorts';
