import { useEffect, useState } from 'react';

export function useNotificationConsent() {
  const [permission, setPermission] = useState<NotificationPermission | 'unsupported'>('default');
  const [hasRequested, setHasRequested] = useState(false);

  useEffect(() => {
    try {
      const stored = localStorage.getItem('notificationPermission');
      if (stored === 'granted' || stored === 'denied' || stored === 'default') {
        setPermission(stored as NotificationPermission);
      }
      const alreadyRequested = localStorage.getItem('notificationConsentRequested') === 'true';
      setHasRequested(alreadyRequested);
    } catch {}
  }, []);

  const requestConsent = async (): Promise<NotificationPermission | 'unsupported'> => {
    if (typeof window !== 'undefined' && 'Notification' in window) {
      const perm = await Notification.requestPermission();
      setPermission(perm);
      try {
        localStorage.setItem('notificationPermission', perm);
        localStorage.setItem('notificationConsentRequested', 'true');
        setHasRequested(true);
      } catch {}
      return perm;
    }
    return 'unsupported';
  };

  return { permission, hasRequested, requestConsent };
}
