import React, { useState, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Shield, Eye, EyeOff, AlertCircle, Lock } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { MasterPinService } from '@/utils/masterPinService';
import { auth } from '@/firebase';
import PasswordConfirmDialog from '@/components/PasswordConfirmDialog';
import { cn } from '@/lib/utils';

interface MasterPinDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
  title?: string;
  description?: string;
  mode?: 'verify' | 'create' | 'change';
  className?: string;
  overlayClassName?: string;
  userId?: string;
  userRole?: string;
}

export const MasterPinDialog: React.FC<MasterPinDialogProps> = ({
  open,
  onOpenChange,
  onSuccess,
  title = "الرقم السري الرئيسي",
  description = "رقم سري موحد لإدارة جميع عناصر الموقع",
  mode = 'verify',
  className,
  overlayClassName,
  userId,
  userRole
}) => {
  const [currentPin, setCurrentPin] = useState('');
  const [newPin, setNewPin] = useState('');
  const [confirmPin, setConfirmPin] = useState('');
  const [showCurrentPin, setShowCurrentPin] = useState(false);
  const [showNewPin, setShowNewPin] = useState(false);
  const [showConfirmPin, setShowConfirmPin] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();
  const [hasMasterPin, setHasMasterPin] = useState(false);
  const [useOverrideReset, setUseOverrideReset] = useState(false);
  const canOverrideReset = (userRole === 'admin' || userRole === 'staff');
  const [isPasswordConfirmOpen, setIsPasswordConfirmOpen] = useState(false);
  const [passwordVerified, setPasswordVerified] = useState(false);
  const formRef = useRef<HTMLFormElement | null>(null);
  
  // Internal mode state to handle switching from verify to change
  const [internalMode, setInternalMode] = useState(mode);

  useEffect(() => {
    setInternalMode(mode);
  }, [mode]);

  useEffect(() => {
    let mounted = true;
    const check = async () => {
      try {
        const effectiveUserId = userId || auth.currentUser?.uid;
        const has = await MasterPinService.hasMasterPin(effectiveUserId);
        if (mounted) setHasMasterPin(has);
      } catch {}
    };
    if (open) check();
    return () => { mounted = false; };
  }, [userId, open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    const effectiveUserId = userId || auth.currentUser?.uid;

    try {
      if (internalMode === 'verify') {
        if (!currentPin) {
          setError('يرجى إدخال الرقم السري الرئيسي');
          setIsLoading(false);
          return;
        }
        const ok = await MasterPinService.verifyMasterPin(currentPin, effectiveUserId);
        if (!ok) {
          setError('الرقم السري غير صحيح');
          setIsLoading(false);
          return;
        }
        toast({ title: "تم التأكيد", description: "تم التحقق من الرقم السري بنجاح" });
        onSuccess?.();
        handleClose();
      } else if (internalMode === 'create') {
        if (!newPin || newPin.length < 4) {
          setError('يجب أن يكون الرقم السري الجديد 4 أرقام على الأقل');
          setIsLoading(false);
          return;
        }
        if (newPin !== confirmPin) {
          setError('الرقم السري الجديد وتأكيده غير متطابقين');
          setIsLoading(false);
          return;
        }
        const created = await MasterPinService.createMasterPin(newPin, effectiveUserId);
        if (!created) {
          setError('تعذر إنشاء الرقم السري الرئيسي');
          setIsLoading(false);
          return;
        }
        toast({ title: "تم تعيين الرقم السري الرئيسي", description: "تم تعيين الرقم السري الرئيسي بنجاح" });
        onSuccess?.();
        handleClose();
      } else if (internalMode === 'change') {
        // منع التغيير إذا لم يتم تحميل المستخدم لضمان التطابق في مفاتيح التخزين
        if (!effectiveUserId) {
          setError('لا يمكن تغيير الرقم السري قبل تحميل حساب المستخدم. الرجاء إعادة المحاولة بعد تسجيل الدخول أو انتظار التحميل.');
          setIsLoading(false);
          return;
        }
        // إذا كان هناك رقم سري محفوظ، تحقق من الحالي ما لم يكن هناك تجاوز إداري
        if (hasMasterPin && !useOverrideReset) {
          if (!passwordVerified) {
            if (!currentPin) {
              setError('يرجى إدخال الرقم السري الحالي أو تأكيد كلمة الدخول');
              setIsLoading(false);
              return;
            }
            const ok = await MasterPinService.verifyMasterPin(currentPin, effectiveUserId);
            if (!ok) {
              setError('الرقم السري الحالي غير صحيح');
              setIsLoading(false);
              return;
            }
          }
        }
        if (!newPin || newPin.length < 4) {
          setError('يجب أن يكون الرقم السري الجديد 4 أرقام على الأقل');
          setIsLoading(false);
          return;
        }
        if (newPin !== confirmPin) {
          setError('الرقم السري الجديد وتأكيده غير متطابقين');
          setIsLoading(false);
          return;
        }
        const changed = hasMasterPin
          ? (
            (useOverrideReset && canOverrideReset) || passwordVerified
              ? await MasterPinService.createMasterPin(newPin, effectiveUserId) // إعادة تعيين بدون الحاجة للرقم الحالي بعد تحقق كلمة الدخول أو صلاحية إدارية
              : await MasterPinService.changeMasterPin(currentPin, newPin, effectiveUserId)
            )
          : await MasterPinService.createMasterPin(newPin, effectiveUserId);
        if (!changed) {
          setError('تعذر تغيير الرقم السري الرئيسي');
          setIsLoading(false);
          return;
        }
        toast({ title: hasMasterPin ? (((useOverrideReset && canOverrideReset) || passwordVerified) ? "تم إعادة تعيين الرقم السري الرئيسي" : "تم تغيير الرقم السري الرئيسي") : "تم تعيين الرقم السري الرئيسي", description: hasMasterPin ? (((useOverrideReset && canOverrideReset) || passwordVerified) ? "تمت إعادة التعيين بدون الحاجة للرقم الحالي" : "تم تغيير الرقم السري الرئيسي بنجاح") : "تم تعيين الرقم السري الرئيسي بنجاح" });
        onSuccess?.();
        handleClose();
      }
    } catch (error) {
      setError('حدث خطأ أثناء معالجة الرقم السري');
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    setCurrentPin('');
    setNewPin('');
    setConfirmPin('');
    setError('');
    setShowCurrentPin(false);
    setShowNewPin(false);
    setShowConfirmPin(false);
    setPasswordVerified(false);
    setIsPasswordConfirmOpen(false);
    setUseOverrideReset(false);
    setInternalMode(mode);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent
        className={cn("sm:max-w-md bg-transparent border-0 shadow-none p-0", className)}
        dir="rtl"
        overlayClassName={overlayClassName}
      >
        <div className="rounded-2xl bg-white border border-gray-200 shadow-2xl px-6 py-5">
        <DialogHeader className="px-0 pt-0">
          <DialogTitle className="flex items-center gap-2 justify-center text-gray-900 text-xl font-bold leading-snug text-center">
            <Shield className="h-5 w-5 text-blue-600" />
            {title}
          </DialogTitle>
        </DialogHeader>

        <div className="mt-1 text-center text-xs md:text-sm text-gray-600 leading-relaxed mb-4">
          {description}
        </div>

        <form ref={formRef} onSubmit={handleSubmit} className="space-y-4">
          {/* الرقم السري الحالي (للتحقق أو التغيير) */}
          {(internalMode === 'verify' || (internalMode === 'change' && hasMasterPin)) && (
            <div className="space-y-2">
              <Label htmlFor="currentPin" className="text-right block text-gray-700 dark:text-gray-300">
                {internalMode === 'verify' ? 'الرقم السري الرئيسي' : 'الرقم السري الحالي'}
              </Label>
              <div className="relative">
                <Input
                  id="currentPin"
                  type={showCurrentPin ? "text" : "password"}
                  autoComplete="off"
                  value={currentPin}
                  onChange={(e) => setCurrentPin(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { try { formRef.current?.requestSubmit(); } catch {} } }}
                  placeholder={internalMode === 'verify' ? 'أدخل الرقم السري الرئيسي' : 'أدخل الرقم السري الحالي'}
                  className="pr-10 bg-white dark:bg-white border border-blue-500/60 text-gray-900 placeholder:text-slate-400 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:border-blue-500 text-lg tracking-[0.2em]"
                  dir="ltr"
                  inputMode="numeric"
                  autoFocus
                  disabled={internalMode === 'change' && passwordVerified}
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="absolute left-0 top-0 h-full px-3 py-2 hover:bg-transparent text-gray-500 dark:text-gray-400"
                  onClick={() => setShowCurrentPin(!showCurrentPin)}
                >
                  {showCurrentPin ? (
                    <EyeOff className="h-4 w-4" />
                  ) : (
                    <Eye className="h-4 w-4" />
                  )}
                </Button>
              </div>

              {/* Forgot PIN Button for Verify Mode */}
              {internalMode === 'verify' && (
                <div className="text-xs text-gray-600 dark:text-gray-400 mt-2 flex items-center justify-between">
                  <span>نسيت الرقم السري الرئيسي؟</span>
                  <Button
                    type="button"
                    variant="link"
                    size="sm"
                    className="h-auto p-0 text-blue-600 dark:text-blue-400 hover:no-underline"
                    onClick={() => setIsPasswordConfirmOpen(true)}
                  >
                    إعادة تعيين
                  </Button>
                </div>
              )}

              {internalMode === 'change' && hasMasterPin && canOverrideReset && (
                <div className="text-xs text-gray-600 dark:text-gray-400 mt-2 flex items-center justify-between">
                  <span>نسيت الرقم السري؟</span>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="h-7 px-2 dark:border-gray-700 dark:text-gray-300"
                    onClick={() => {
                      setUseOverrideReset(prev => !prev);
                    }}
                  >
                    {useOverrideReset ? 'إلغاء إعادة التعيين الإدارية' : 'إعادة تعيين بدون الرقم الحالي'}
                  </Button>
                </div>
              )}
              {internalMode === 'change' && hasMasterPin && (
                <div className="text-xs text-gray-600 dark:text-gray-400 mt-2 flex items-center justify-between">
                  <span>لا تعرف الرقم الحالي؟ يمكنك تأكيد بكلمة الدخول</span>
                  <Button
                    type="button"
                    variant="secondary"
                    size="sm"
                    className="h-7 px-2 dark:bg-gray-800 dark:text-gray-200 dark:hover:bg-gray-700"
                    onClick={() => setIsPasswordConfirmOpen(true)}
                  >
                    تأكيد بكلمة الدخول
                  </Button>
                </div>
              )}
              {internalMode === 'change' && passwordVerified && (
                <div className="text-[11px] text-green-600 dark:text-green-400">تم التحقق من كلمة الدخول — يمكنك المتابعة بدون الرقم الحالي</div>
              )}
            </div>
          )}

          {/* الرقم السري الجديد (للإنشاء أو التغيير) */}
          {(internalMode === 'create' || internalMode === 'change') && (
            <div className="space-y-2">
              <Label htmlFor="newPin" className="text-right block text-gray-700 dark:text-gray-300">
                {internalMode === 'create' ? 'الرقم السري الرئيسي الجديد' : 'الرقم السري الجديد'}
              </Label>
              <div className="relative">
                <Input
                  id="newPin"
                  type={showNewPin ? "text" : "password"}
                  autoComplete="off"
                  value={newPin}
                  onChange={(e) => setNewPin(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { try { formRef.current?.requestSubmit(); } catch {} } }}
                  placeholder={internalMode === 'create' ? 'أدخل الرقم السري الجديد' : 'أدخل الرقم السري الجديد'}
                  className="pr-10 bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-900 dark:text-gray-100"
                  dir="ltr"
                  inputMode="numeric"
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="absolute left-0 top-0 h-full px-3 py-2 hover:bg-transparent text-gray-500 dark:text-gray-400"
                  onClick={() => setShowNewPin(!showNewPin)}
                >
                  {showNewPin ? (
                    <EyeOff className="h-4 w-4" />
                  ) : (
                    <Eye className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
          )}

          {/* تأكيد الرقم السري الجديد (للإنشاء أو التغيير) */}
          {(internalMode === 'create' || internalMode === 'change') && (
            <div className="space-y-2">
              <Label htmlFor="confirmPin" className="text-right block text-gray-700 dark:text-gray-300">
                تأكيد الرقم السري الجديد
              </Label>
              <div className="relative">
                <Input
                  id="confirmPin"
                  type={showConfirmPin ? "text" : "password"}
                  autoComplete="off"
                  value={confirmPin}
                  onChange={(e) => setConfirmPin(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { try { formRef.current?.requestSubmit(); } catch {} } }}
                  placeholder="أعد إدخال الرقم السري الجديد"
                  className="pr-10 bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-900 dark:text-gray-100"
                  dir="ltr"
                  inputMode="numeric"
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="absolute left-0 top-0 h-full px-3 py-2 hover:bg-transparent text-gray-500 dark:text-gray-400"
                  onClick={() => setShowConfirmPin(!showConfirmPin)}
                >
                  {showConfirmPin ? (
                    <EyeOff className="h-4 w-4" />
                  ) : (
                    <Eye className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
          )}

          {/* رسالة الخطأ */}
          {error && (
            <div className="flex items-center gap-2 text-red-600 dark:text-red-400 text-sm bg-red-50 dark:bg-red-900/30 p-3 rounded-lg border border-red-100 dark:border-red-900/50">
              <AlertCircle className="h-4 w-4" />
              {error}
            </div>
          )}

          {/* أزرار التحكم */}
          <div className="flex gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              className="flex-1 dark:border-gray-700 dark:text-gray-300 dark:hover:bg-gray-800"
            >
              إلغاء
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              className="flex-1 bg-blue-600 hover:bg-blue-700 text-white"
            >
              {isLoading ? (
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  جاري المعالجة...
                </div>
              ) : (
                <>
                  <Lock className="h-4 w-4 mr-2" />
                  {internalMode === 'verify' ? 'تحقق' : internalMode === 'create' ? 'إنشاء' : 'تغيير'}
                </>
              )}
            </Button>
          </div>
        </form>
        <PasswordConfirmDialog
          open={isPasswordConfirmOpen}
          onOpenChange={setIsPasswordConfirmOpen}
          title="تأكيد بكلمة دخول الحساب"
          description="أدخل كلمة المرور المستخدمة لتسجيل الدخول للسماح بتغيير الرقم السري"
          onSuccess={() => {
            setPasswordVerified(true);
            setIsPasswordConfirmOpen(false);
            setError('');
            if (internalMode === 'verify') {
                setInternalMode('change');
            }
          }}
        />
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default MasterPinDialog;
