import { auth } from '@/firebase'
import { processMobileTransactionNotification } from '@/utils/mobileTransactionHandler'
import { getUserSubscription, SubscriptionPlan } from '@/utils/subscriptionService'

type VfDetail = {
  title?: string
  text?: string
  packageName?: string
  appName?: string
  postedAt?: number
  simSlot?: number
  receiverMsisdn?: string
  sender?: string // Added sender for hash
  handledInBackground?: boolean
}

const parseAmount = (text: string): number | null => {
  try {
    // 1. Arabic: "مبلغ X"
    let m = text.match(/(?:مبلغ|قيمة|رصيد)\s*[:]?\s*([0-9]+(?:[.,][0-9]+)?)/);
    if (m) return Number(m[1].replace(',', '.'));

    // 2. English: "Received EGP5" (specific no-space)
    m = text.match(/received\s*EGP([0-9]+(?:[.,][0-9]+)?)/i);
    if (m) return Number(m[1].replace(',', ''));

    // 3. English: "Received EGP 5" or "Amount 5"
    m = text.match(/(?:amount|balance|transferred|received)\s*(?:is|:)?\s*(?:EGP)?\s*([0-9]+(?:[.,][0-9]+)?)/i);
    if (m) return Number(m[1].replace(',', ''));

    // 4. Fallback: "EGP 5" or "5 EGP"
    m = text.match(/EGP\s*([0-9]+(?:[.,][0-9]+)?)/i);
    if (m) return Number(m[1].replace(',', ''));
    
    m = text.match(/([0-9]+(?:[.,][0-9]+)?)\s*EGP/i);
    if (m) return Number(m[1].replace(',', ''));

    // 5. Legacy Fallback (Arabic suffix mostly)
    m = text.match(/([0-9]+[.,]?[0-9]*)\s*(?:جنيه)/);
    if (m) return Number(m[1].replace(',', ''));
    
    // 6. Arabic currency abbreviation: "ج.م" or "ج م" with optional dots
    m = text.match(/([0-9]+(?:[.,][0-9]+)?)\s*ج\.?\s*\.?م\.?/i) || text.match(/([0-9]+(?:[.,][0-9]+)?)\s*ج\s*م/i);
    if (m) return Number(String(m[1]).replace(',', '.'));
    
    return null;
  } catch { return null }
}

const parseMsisdn = (text: string): string | undefined => {
  try {
    // Supports 01xxxxxxxxx, +201xxxxxxxxx, 00201xxxxxxxxx
    const m = text.match(/((?:002|\+2)?01[0-9]{9})/);
    if (m) {
        let num = m[1];
        if (num.startsWith('002')) num = num.substring(3);
        if (num.startsWith('+2')) num = num.substring(2);
        return num;
    }
    return undefined
  } catch { return undefined }
}

const parseFee = (text: string): number | undefined => {
  try {
    // Supports: "مصاريف الخدمة 5", "رسوم التحويل 1.00", "مصاريف 5"
    const m = text.match(/(?:مصاريف|رسوم)(?:\s+(?:الخدمة|التحويل))?\s*([0-9]+(?:[.,][0-9]+)?)/);
    if (!m) return undefined;
    const raw = m[1].replace(',', '.');
    return Number(raw) || 0;
  } catch { return undefined; }
}

const resolveSelectedWalletId = (): string | null => {
  try {
    const uid = auth.currentUser?.uid || 'default'
    const anyKey = Object.keys(localStorage).find(k => k.startsWith(`selectedWallet_${uid}`))
    if (anyKey) {
      const v = localStorage.getItem(anyKey) || ''
      if (v) return v
    }
    const walletsKey = Object.keys(localStorage).find(k => k.startsWith(`wallets_${uid}`))
    if (walletsKey) {
      const arrStr = localStorage.getItem(walletsKey) || ''
      if (arrStr) {
        const arr = JSON.parse(arrStr)
        if (Array.isArray(arr) && arr.length > 0) {
          const def = arr.find((w: any) => w?.isDefault)
          return (def?.id || arr[0]?.id || null)
        }
      }
    }
  } catch {}
  return null
}

const resolveSelectedShopId = (): string | null => {
  try {
    const uid = auth.currentUser?.uid || ''
    const key = uid ? `selectedShopId_${uid}` : 'selectedShopId'
    const v = localStorage.getItem(key) || ''
    return v || null
  } catch { return null }
}

const resolveWalletIdByPhoneNumber = (userId: string, phoneNumber: string): string | null => {
  try {
    const walletsKey = `wallets_${userId}`
    const arrStr = localStorage.getItem(walletsKey)
    if (!arrStr) return null
    const arr = JSON.parse(arrStr)
    if (Array.isArray(arr)) {
      const cleanPhone = phoneNumber.trim()
      const found = arr.find((w: any) => 
        (w.phone && String(w.phone).trim() === cleanPhone) || 
        (w.msisdn && String(w.msisdn).trim() === cleanPhone)
      )
      return found ? found.id : null
    }
  } catch { }
  return null
}

export const processVfNotification = async (detail: VfDetail, toast?: { toast: (opts: any) => void }): Promise<void> => {
  const text = String(detail?.text || '').trim()
  const title = String(detail?.title || '').trim()
  const pkg = String(detail?.packageName || '').toLowerCase()
  const appName = String(detail?.appName || '').toLowerCase()
  if (!text) return
  // Relax detection: support Ana Vodafone, Etisalat Cash (e& money), InstaPay, and Arabic keywords
  const looksVodafone = (
    /vodafone|emeint|myservices|etisalat|e&|instapay/.test(pkg) ||
    /vodafone|vf\-?cash|فودافون|كاش|etisalat|e&|money|instapay/.test(appName) ||
    /تم\s*إ?ستلام\s*مبلغ|تم\s*تحويل|تحويل\s*مبلغ|فودافون\s*كاش|أنا\s*فودافون|ana\s*vodafone|e&\s*money|etisalat|received|transferred|sent/i.test(text)
  )
  if (!looksVodafone) return
  try { console.log('VF/ETISALAT NOTIFICATION RECEIVED', detail) } catch {}

  // Prevent double counting if handled by Native Android Service
  if (detail.handledInBackground) {
    console.log('Transaction handled in background (Native). Skipping Web processing to prevent double counting.');
    if (toast && toast.toast) {
       toast.toast({
         title: "تمت المعالجة",
         description: "تم تسجيل المعاملة تلقائياً في الخلفية.",
       });
    }
    return;
  }

  const isWithdraw = /سحب|إ?ستلام|مستلم|received/i.test(text)
  const isTransfer = /تم\s*تحويل|تحويل\s*مبلغ|transferred|sent/i.test(text)
  
  // Check Auto-Record Preference for Transfers
  if (isTransfer) {
    const uid = auth.currentUser?.uid || undefined;
    const perUser = uid ? localStorage.getItem(`autoTransferRecord_${uid}`) : null;
    const global = localStorage.getItem('autoTransferRecord');
    const pref = perUser ?? global;
    // Default to TRUE if not set, to ensure automatic recording works as requested
    const isAutoTransferEnabled = pref !== 'false';
    if (!isAutoTransferEnabled) {
      console.log('Transfer detected but Auto-Record is disabled by user preference. Ignoring.');
      return;
    }
  }
  
  let amount = parseAmount(text)
  // Specific regex for Transfer Out as requested: تم تحويل\s+(\d+(\.\d+)?)\s+جنيه
  if (isTransfer) {
    const transferMatch = text.match(/تم\s*تحويل\s+(\d+(?:[.,]\d+)?)\s+جنيه/);
    if (transferMatch) {
       amount = Number(transferMatch[1].replace(',', '.'));
    } else {
        // Fallback: Try to find ANY amount if the strict regex failed but it's a transfer
        // Sometimes "1500" might not have decimals or spaces exactly as expected
        const simpleMatch = text.match(/تم\s*تحويل\s+([0-9.,]+)\s+/);
        if (simpleMatch) {
             const val = Number(simpleMatch[1].replace(',', '.'));
             if (val > 0) amount = val;
        }
    }
  }

  const msisdn = parseMsisdn(text)
  const fee = parseFee(text) || 0
  if (!amount || amount <= 0) { return }

  // Determine provider
  let provider: 'vodafone_cash' | 'etisalat_cash' | 'instapay' = 'vodafone_cash'
  if (/etisalat|e&|اتصالات/i.test(text) || /etisalat|e&/i.test(pkg) || /etisalat|e&/i.test(appName)) {
    provider = 'etisalat_cash'
  } else if (/instapay/i.test(text) || /instapay/i.test(pkg) || /instapay/i.test(appName)) {
    provider = 'instapay'
  }

  const userId = auth.currentUser?.uid || ''
  
  // Resolve My SIM Number (Wallet Owner) based on SIM Slot first
  // Priority: Profile Settings (sim1/sim2) -> Android Detected Number -> undefined
  let mySimNumber: string | undefined = undefined
  
  if (detail?.simSlot !== undefined && userId) {
      try {
          if (detail.simSlot === 0) { // SIM 1
              const s1 = localStorage.getItem(`sim1Number_${userId}`) ?? localStorage.getItem('sim1Number');
              if (s1) mySimNumber = String(s1).trim();
              // Fallback to auto-detected SIMs if profile is not set
              if (!mySimNumber && Array.isArray(detail.activeSimMsisdns) && detail.activeSimMsisdns[0]) {
                  mySimNumber = String(detail.activeSimMsisdns[0]).trim();
              }
          } else if (detail.simSlot === 1) { // SIM 2
              const s2 = localStorage.getItem(`sim2Number_${userId}`) ?? localStorage.getItem('sim2Number');
              if (s2) mySimNumber = String(s2).trim();
              // Fallback to auto-detected SIMs if profile is not set
              if (!mySimNumber && Array.isArray(detail.activeSimMsisdns) && detail.activeSimMsisdns[1]) {
                  mySimNumber = String(detail.activeSimMsisdns[1]).trim();
              }
          }
      } catch (e) { console.error('Error resolving SIM from profile', e) }
  }

  // Determine Wallet ID with Strict SIM Mapping
  let walletId: string | undefined = undefined;

  if (detail?.simSlot !== undefined) {
      // Strict Check: Must have a configured SIM number in profile
      if (!mySimNumber) {
          console.warn('Transaction detected but no SIM number found in profile for slot', detail?.simSlot);
          if (toast && toast.toast) {
              toast.toast({
                  title: "تنبيه",
                  description: `تم اكتشاف عملية على الشريحة ${detail.simSlot + 1} ولكن لم يتم تحديد رقم الشريحة في إعدادات البروفايل.`,
                  variant: "destructive"
              });
          }
          return;
      }
      
      // Strict Check: Must find a wallet matching this SIM number
      const foundWalletId = resolveWalletIdByPhoneNumber(userId, mySimNumber);
      if (foundWalletId) {
          walletId = foundWalletId;
      } else {
          console.warn('Transaction detected but no wallet found for number', mySimNumber);
          if (toast && toast.toast) {
              toast.toast({
                  title: "تنبيه",
                  description: `لم يتم العثور على محفظة مسجلة بالرقم ${mySimNumber}. يرجى التأكد من إضافة المحفظة في البرنامج.`,
                  variant: "destructive"
              });
          }
          return;
      }
  } else {
      // Fallback for cases where simSlot is missing (should not happen with new app version)
      walletId = resolveSelectedWalletId() || undefined
  }

  const shopId = resolveSelectedShopId() || ''
  const lineId = walletId || 'default-line'
  if (!userId || !walletId || !shopId) { return }

  try {
    const subscription = await getUserSubscription(userId)
    if (subscription?.planType === SubscriptionPlan.ZERO) {
      console.log('Ignoring Notification for Zero Plan user')
      return
    }
  } catch {}

  const refBase = `${title}|${text}|${detail?.sender || ''}|${detail?.postedAt || Date.now()}`
  const reference = `VF-${btoa(unescape(encodeURIComponent(refBase))).slice(0, 24)}`
  const type: 'withdraw' | 'transfer' = isWithdraw ? 'withdraw' : (isTransfer ? 'transfer' : 'withdraw')
  
  // Note: mySimNumber is already resolved above
  // If undefined (e.g. fallback path), try receiverMsisdn from detail
  if (!mySimNumber) mySimNumber = detail?.receiverMsisdn || undefined

  const payload = {
    type,
    amount,
    provider,
    shopId,
    lineId,
    walletId,
    // If Withdraw (Receive): Sender is Other (msisdn), Receiver is Me (mySimNumber)
    // If Transfer (Send): Sender is Me (mySimNumber), Receiver is Other (msisdn)
    senderMsisdn: type === 'withdraw' ? (msisdn || undefined) : mySimNumber,
    receiverMsisdn: type === 'withdraw' ? mySimNumber : (msisdn || undefined),
    reference,
    fee,
    createdBy: userId,
    merchantUserId: userId,
    note: provider === 'etisalat_cash' ? 'إشعار اتصالات كاش' : (provider === 'instapay' ? 'إشعار انستا باي' : 'إشعار فودافون كاش')
  }

  try { await processMobileTransactionNotification(payload as any) } catch {}
}
